// true = demo build (fake headsets)
// false = real build, talks to the quest over adb
const kDemo = false;

// same as version in pubspec.yaml, the updater checks against this
const kVersion = '1.0.0';
// latest.json on github: version, url, sha256, notes
const kUpdateUrl = 'https://raw.githubusercontent.com/faisaldacoolkid/lightcat-sideloader/main/latest.json';

ServerSocket? _instanceLock;

Future<bool> _claimInstance() async {
  try {
    _instanceLock = await ServerSocket.bind(InternetAddress.loopbackIPv4, kDemo ? 47822 : 47821);
    _instanceLock!.listen((c) {
      c.destroy();
      showWindow();
    });
    return true;
  } catch (_) {
    try {
      final c = await Socket.connect(InternetAddress.loopbackIPv4, kDemo ? 47822 : 47821, timeout: const Duration(seconds: 1));
      c.destroy();
    } catch (_) {}
    return false;
  }
}

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  PaintingBinding.instance.imageCache
    ..maximumSizeBytes = 48 << 20
    ..maximumSize = 150;
  if (!await _claimInstance()) exit(0);
  await Prefs.load();
  if (kDemo) {
    for (final k in ['terms', 'name', 'nameChangedAt', 'metaNoticeSeen', 'sideloadWarned', 'trayHint', 'updateNotified']) {
      Prefs.data.remove(k);
    }
    Prefs.data.removeWhere((k, _) => k.startsWith('alert_'));
  }
  if (kDemo) Demo.seed();
  await windowManager.ensureInitialized();
  try {
    await localNotifier.setup(appName: 'Lightcat Sideloader', shortcutPolicy: ShortcutPolicy.requireCreate);
  } catch (_) {}
  const opts = WindowOptions(
    size: Size(1280, 780),
    minimumSize: Size(1280, 780),
    center: true,
    backgroundColor: Pal.bg,
    titleBarStyle: TitleBarStyle.hidden,
    title: 'Lightcat Sideloader',
  );
  windowManager.waitUntilReadyToShow(opts, () async {
    await windowManager.setResizable(false);
    await windowManager.setPreventClose(true);
    await windowManager.setMaximizable(true);
    await windowManager.show();
    await windowManager.focus();
    await fixFrame();
  });
  runApp(const LightcatApp());
}

