const deviceArt = <String, String>{
  'q3': '',
  'q3s': '',
  'qpro': '',
  'q2': '',
  'c3l': '',
  'c3r': '',
  'cprol': '',
  'cpror': '',
  'c2l': '',
  'c2r': '',
};

final _artCache = <String, List<int>>{};
List<int>? artBytes(String key) {
  final b64 = deviceArt[key];
  if (b64 == null) return null;
  return _artCache.putIfAbsent(key, () => base64Decode(b64));
}

class DeviceArt extends StatelessWidget {
  final String model;
  final double width, height;
  const DeviceArt({super.key, required this.model, required this.width, required this.height});
  @override
  Widget build(BuildContext context) {
    final b = artBytes(model);
    if (b == null) return SizedBox(width: width, height: height, child: CustomPaint(painter: HeadsetPainter(Pal.a, Pal.b)));
    return SizedBox(
      width: width,
      height: height,
      child: Image.memory(Uint8List.fromList(b), fit: BoxFit.contain, filterQuality: FilterQuality.high, isAntiAlias: true, gaplessPlayback: true),
    );
  }
}

String controllerKey(String model, bool left) {
  final base = model == 'qpro' ? 'cpro' : (model == 'q2' ? 'c2' : 'c3');
  return '$base${left ? 'l' : 'r'}';
}

Color batteryColor(int level) => level <= 20 ? Pal.bad : (level < 80 ? Pal.warn : Pal.good);
List<Color> batteryGrad(int level) => level <= 20
    ? const [Pal.bad, Color(0xFFFB7185)]
    : (level < 80 ? const [Pal.warn, Color(0xFFFB923C)] : const [Pal.good, Color(0xFF2DD4BF)]);

List<int> icoFromPng(List<int> png) {
  List<int> le32(int v) => [v & 255, (v >> 8) & 255, (v >> 16) & 255, (v >> 24) & 255];
  return [0, 0, 1, 0, 1, 0, 0, 0, 0, 0, 1, 0, 32, 0, ...le32(png.length), ...le32(22), ...png];
}

class Note {
  final int id;
  final String title, body;
  final IconData icon;
  final Color color;
  bool closing = false;
  Note(this.id, this.title, this.body, this.icon, this.color);
}

class Notes extends ChangeNotifier {
  static final Notes i = Notes._();
  Notes._();
  final list = <Note>[];
  final _timers = <int, Timer>{};
  int _n = 0;

  void push(String title, String body, {IconData icon = Icons.notifications_rounded, Color? color}) {
    if (Prefs.data['inAppNotes'] == false) return;
    final n = Note(++_n, title, body, icon, color ?? Pal.a);
    list.insert(0, n);
    while (list.length > 3) {
      _timers.remove(list.removeLast().id)?.cancel();
    }
    notifyListeners();
    resume(n.id, const Duration(seconds: 10));
  }

  void hold(int id) => _timers.remove(id)?.cancel();

  void resume(int id, Duration left) {
    _timers.remove(id)?.cancel();
    _timers[id] = Timer(left, () => dismiss(id));
  }

  void dismiss(int id) {
    _timers.remove(id)?.cancel();
    final at = list.indexWhere((n) => n.id == id);
    if (at < 0 || list[at].closing) return;
    list[at].closing = true;
    notifyListeners();
    Future.delayed(const Duration(milliseconds: 340), () {
      list.removeWhere((n) => n.id == id);
      notifyListeners();
    });
  }
}

