class _NoteCard extends StatefulWidget {
  final Note n;
  const _NoteCard({super.key, required this.n});
  @override
  State<_NoteCard> createState() => _NoteCardState();
}

class _NoteCardState extends State<_NoteCard> with SingleTickerProviderStateMixin {
  late final AnimationController bar = AnimationController(vsync: this, duration: const Duration(seconds: 10))..forward();

  @override
  void dispose() {
    bar.dispose();
    super.dispose();
  }

  void _enter() {
    if (widget.n.closing) return;
    bar.stop();
    Notes.i.hold(widget.n.id);
  }

  void _leave() {
    if (widget.n.closing) return;
    final left = Duration(milliseconds: math.max(1200, ((1 - bar.value) * 10000).round()));
    bar.forward();
    Notes.i.resume(widget.n.id, left);
  }

  @override
  Widget build(BuildContext context) {
    final n = widget.n;
    return TweenAnimationBuilder<double>(
      tween: Tween<double>(begin: 0, end: n.closing ? 0 : 1),
      duration: ms(340),
      curve: Curves.easeOutCubic,
      builder: (_, v, child) => Opacity(
        opacity: v.clamp(0.0, 1.0),
        child: Transform.translate(offset: Offset(0, (1 - v) * -26), child: child),
      ),
      child: MouseRegion(
        onEnter: (_) => _enter(),
        onExit: (_) => _leave(),
        child: Padding(
          padding: const EdgeInsets.only(bottom: 10),
          child: Container(
            width: 420,
            decoration: BoxDecoration(
              color: Pal.card2.withValues(alpha: .97),
              borderRadius: BorderRadius.circular(18),
              border: Border.all(color: n.color.withValues(alpha: .75), width: 2),
              boxShadow: [BoxShadow(color: Colors.black.withValues(alpha: .35), blurRadius: 30, offset: const Offset(0, 10))],
            ),
            clipBehavior: Clip.antiAlias,
            child: Column(mainAxisSize: MainAxisSize.min, children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 14, 16, 12),
                child: IntrinsicHeight(
                  child: Row(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
                    Align(
                      alignment: Alignment.topCenter,
                      child: Container(
                        width: 38,
                        height: 38,
                        decoration: BoxDecoration(color: n.color.withValues(alpha: .16), borderRadius: BorderRadius.circular(12)),
                        child: Icon(n.icon, color: n.color, size: 21),
                      ),
                    ),
                    const SizedBox(width: 12),
                    Expanded(
                      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                        Text(n.title, style: t(14, w: FontWeight.w700)),
                        const SizedBox(height: 3),
                        Text(n.body, style: t(12.5, c: Pal.sub, h: 1.4)),
                      ]),
                    ),
                    const SizedBox(width: 6),
                    Center(child: IconBtn(icon: Icons.close_rounded, tip: 'Dismiss', onTap: () => Notes.i.dismiss(n.id))),
                  ]),
                ),
              ),
              Padding(
                padding: const EdgeInsets.fromLTRB(18, 0, 18, 10),
                child: ClipRRect(
                  borderRadius: BorderRadius.circular(3),
                  child: AnimatedBuilder(
                    animation: bar,
                    builder: (_, __) => Align(
                      alignment: Alignment.centerLeft,
                      child: FractionallySizedBox(
                        widthFactor: (1 - bar.value).clamp(0.0, 1.0),
                        child: Container(height: 3, color: n.color.withValues(alpha: .8)),
                      ),
                    ),
                  ),
                ),
              ),
            ]),
          ),
        ),
      ),
    );
  }
}

