Future<void> notifyUser(String title, String body,
    {bool inApp = true, IconData icon = Icons.notifications_rounded, Color? color}) async {
  if (inApp) Notes.i.push(title, body, icon: icon, color: color);
  try {
    await LocalNotification(title: title, body: body).show();
  } catch (_) {}
}

class Alerts {
  static final _last = <String, int>{};
  static final _fullSent = <String, bool>{}, _lowSent = <String, bool>{};
  static final _pad = <String, int?>{};

  static void forget(String id) {
    _last.remove(id);
    _pad.removeWhere((k, _) => k.startsWith('$id/'));
  }

  static bool _once(String key) {
    final now = DateTime.now().millisecondsSinceEpoch;
    final last = (Prefs.data['alert_$key'] as num?)?.toInt() ?? 0;
    if (now - last < 20 * 60 * 1000) return false;
    Prefs.set('alert_$key', now);
    return true;
  }

  static void pads(DeviceInfo d) {
    for (final side in ['left', 'right']) {
      final v = side == 'left' ? d.left : d.right;
      final on = side == 'left' ? d.leftOn : d.rightOn;
      final key = '${d.id}/$side';
      final prev = _pad[key];
      _pad[key] = on ? v : null;
      if (v == null || prev == null || !on) continue;
      if (Prefs.data['notifyPads'] == false) continue;
      if (prev > 20 && v <= 20 && _once('pad_${d.id}_$side')) {
        final hand = side == 'left' ? 'Left' : 'Right';
        if (d.rechargeablePads) {
          notifyUser('Charge the controllers', '$hand controller of your ${d.name} is at $v%. Put it on the charging dock.');
        } else {
          notifyUser('Change the controller battery', '$hand controller of your ${d.name} is at $v%. Swap in a fresh AA battery.');
        }
      }
    }
  }

  static final _spaceSent = <String, bool>{};

  static void check(DeviceInfo d) {
    if (d.totalGb > 0) {
      if (d.freeGb > 12) _spaceSent[d.id] = false;
      if (d.freeGb <= 8 && _spaceSent[d.id] != true) {
        _spaceSent[d.id] = true;
        notifyUser('${d.name} storage is almost full',
            'Only ${d.freeGb.toStringAsFixed(1)} GB free. Remove something before installing more.',
            icon: Icons.sd_storage_rounded, color: Pal.warn);
      }
    }
    final lv = d.battery;
    final prev = _last[d.id];
    _last[d.id] = lv;
    if (prev == null) {
      _fullSent[d.id] = lv >= 100;
      _lowSent[d.id] = lv <= 15;
      return;
    }
    if (lv < 95) _fullSent[d.id] = false;
    if (lv > 25 || d.charging) _lowSent[d.id] = false;
    if (Prefs.data['notifyFull'] != false &&
        _fullSent[d.id] != true &&
        d.charging &&
        prev < 100 &&
        lv >= 100 &&
        _once('full_${d.id}')) {
      _fullSent[d.id] = true;
      notifyUser('${d.name} is fully charged', 'It is best to unplug it now so the battery does not wear out.',
          icon: Icons.battery_full_rounded, color: Pal.good);
    }
    if (Prefs.data['notifyLow'] != false &&
        _lowSent[d.id] != true &&
        !d.charging &&
        prev > 15 &&
        lv <= 15 &&
        _once('low_${d.id}')) {
      _lowSent[d.id] = true;
      notifyUser('${d.name} battery is low', 'Only $lv% left. Plug it in soon.',
          icon: Icons.battery_alert_rounded, color: Pal.bad);
    }
  }
}

class Devices extends ChangeNotifier {
  static final Devices i = Devices._();
  Devices._();

  Map<String, dynamic> get all => Map<String, dynamic>.from((Prefs.data['devices'] as Map?) ?? {});

  static void remember(DeviceInfo d) {
    if (d.id.isEmpty) return;
    final m = i.all;
    m[d.id] = {
      'name': d.name,
      'model': d.model,
      'battery': d.battery,
      'left': d.left,
      'right': d.right,
      'seen': DateTime.now().millisecondsSinceEpoch,
    };
    Prefs.set('devices', m);
    i.notifyListeners();
  }

  Future<void> forget(String id) async {
    final m = all..remove(id);
    await Prefs.set('devices', m);
    notifyListeners();
  }
}

String agoText(int ms) {
  final d = DateTime.now().difference(DateTime.fromMillisecondsSinceEpoch(ms));
  if (d.inMinutes < 2) return 'just now';
  if (d.inHours < 1) return '${d.inMinutes} min ago';
  if (d.inDays < 1) return '${d.inHours} h ago';
  if (d.inDays == 1) return 'yesterday';
  return '${d.inDays} days ago';
}

Future<void> fixFrame() async {
  try {
    if (await windowManager.isMaximized()) return;
    await windowManager.setTitleBarStyle(TitleBarStyle.hidden, windowButtonVisibility: false);
    final sz = await windowManager.getSize();
    await windowManager.setSize(Size(sz.width + 1, sz.height));
    await windowManager.setSize(sz);
  } catch (_) {}
}

final appVisible = ValueNotifier<bool>(true);

Future<void> showWindow() async {
  appVisible.value = true;
  await windowManager.show();
  await windowManager.focus();
  await fixFrame();
}

Future<void> quitApp() async {
  await windowManager.hide();
  try {
    await trayManager.destroy();
  } catch (_) {}
  await Cast.i.stopAll();
  try {
    if (!kDemo) await Process.start(Adb.path, const ['kill-server'], mode: ProcessStartMode.detached);
  } catch (_) {}
  await windowManager.setPreventClose(false);
  await windowManager.destroy();
}

class Tray with TrayListener {
  static final Tray i = Tray._();
  Tray._();
  bool _ready = false;
  String _tip = '';

  Future<void> init() async {
    try {
      final f = File('${Prefs.dir}\\tray.ico');
      await f.parent.create(recursive: true);
      await f.writeAsBytes(icoFromPng(logoBytes));
      await trayManager.setIcon(f.path);
      trayManager.addListener(this);
      _ready = true;
      await refresh();
    } catch (_) {}
  }

  String get _status {
    final d = Device.i.info;
    if (Device.i.link == Link.unauthorized) return 'Headset waiting for permission';
    if (Device.i.link != Link.connected || d == null) return 'No headset connected';
    return '${d.name} connected (${d.wifi ? 'wireless' : 'USB'})';
  }

  String? get _battery {
    final d = Device.i.info;
    if (Device.i.link != Link.connected || d == null) return null;
    final state = d.charging ? (d.slow ? 'charging slowly' : 'charging') : (d.full ? 'fully charged' : 'not charging');
    return 'Battery ${d.battery}%, $state';
  }

  Future<void> refresh() async {
    if (!_ready) return;
    final tip = ['Lightcat Sideloader', _status, if (_battery != null) _battery!].join('\n');
    if (tip == _tip) return;
    _tip = tip;
    try {
      await trayManager.setToolTip(tip);
    } catch (_) {}
  }

  @override
  void onTrayIconMouseDown() => showWindow();

  @override
  void onTrayIconRightMouseDown() async {
    await trayManager.setContextMenu(Menu(items: [
      MenuItem(label: _status, disabled: true),
      if (_battery != null) MenuItem(label: _battery!, disabled: true),
      MenuItem.separator(),
      MenuItem(key: 'open', label: 'Open Lightcat'),
      MenuItem(key: 'quit', label: 'Quit'),
    ]));
    await trayManager.popUpContextMenu();
  }

  @override
  void onTrayMenuItemClick(MenuItem item) {
    if (item.key == 'open') showWindow();
    if (item.key == 'quit') quitApp();
  }
}

