class Updater extends ChangeNotifier {
  static final Updater i = Updater._();
  Updater._();

  Map<String, dynamic>? available;
  bool dismissed = false;
  double? progress;
  String? error;
  Timer? _t;

  void start() {
    if (kDemo) return;
    Future.delayed(const Duration(seconds: 10), check);
    _t ??= Timer.periodic(const Duration(hours: 6), (_) => check());
  }

  void dismiss() {
    dismissed = true;
    notifyListeners();
  }

  static bool _newer(String a, String b) {
    List<int> p(String v) =>
        v.split('+').first.split('.').map((x) => int.tryParse(x.replaceAll(RegExp(r'[^0-9]'), '')) ?? 0).toList();
    final x = p(a), y = p(b);
    for (var i = 0; i < 3; i++) {
      final xi = i < x.length ? x[i] : 0, yi = i < y.length ? y[i] : 0;
      if (xi != yi) return xi > yi;
    }
    return false;
  }

  Future<bool> check({bool force = false}) async {
    final j = await Net.json(kUpdateUrl, tries: 2);
    if (j is! Map) return false;
    final v = '${j['version'] ?? ''}';
    final url = '${j['url'] ?? ''}';
    if (v.isEmpty || !url.startsWith('https://') || !_newer(v, kVersion)) return false;
    available = Map<String, dynamic>.from(j);
    if (force) dismissed = false;
    notifyListeners();
    if (Prefs.data['updateNotified'] != v) {
      await Prefs.set('updateNotified', v);
      notifyUser('Update available', 'Lightcat $v is ready to install.');
    }
    return true;
  }

  Future<void> install() async {
    final a = available;
    if (a == null || progress != null) return;
    error = null;
    progress = 0;
    notifyListeners();
    try {
      final file = File('${Directory.systemTemp.path}\\LightcatSetup-${a['version']}.exe');
      final req = await HttpClient().getUrl(Uri.parse('${a['url']}'));
      final res = await req.close();
      if (res.statusCode != 200) throw 'Download failed (${res.statusCode})';
      final total = res.contentLength;
      var got = 0;
      final sink = file.openWrite();
      await for (final chunk in res) {
        sink.add(chunk);
        got += chunk.length;
        if (total > 0) {
          progress = got / total;
          notifyListeners();
        }
      }
      await sink.close();
      final want = '${a['sha256'] ?? ''}'.trim().toLowerCase();
      if (want.isNotEmpty) {
        final r = await Process.run('powershell',
            ['-NoProfile', '-Command', "(Get-FileHash -Algorithm SHA256 -LiteralPath '${file.path}').Hash"]);
        if ('${r.stdout}'.trim().toLowerCase() != want) {
          await file.delete();
          throw 'The download did not match its checksum, so it was not installed';
        }
      }
      await Process.start(file.path, ['/SILENT', '/CLOSEAPPLICATIONS', '/RESTARTAPPLICATIONS'],
          mode: ProcessStartMode.detached);
      await quitApp();
    } catch (e) {
      error = '$e';
      progress = null;
      notifyListeners();
    }
  }
}

