class Prefs {
  static Map<String, dynamic> data = {};

  static String get dir => '${Platform.environment['APPDATA'] ?? Directory.current.path}\\LightcatSideloader${kDemo ? 'Demo' : ''}';

  static File get _file => File('$dir\\config.json');

  static Future<void> load() async {
    try {
      if (await _file.exists()) {
        final d = jsonDecode(await _file.readAsString());
        if (d is Map<String, dynamic>) data = d;
      }
    } catch (_) {}
    Pal.accent.value = math.min(math.max(((data['accent'] as num?) ?? 0).toInt(), 0), Pal.accents.length - 1);
    Pal.reduceMotion.value = data['reduceMotion'] == true;
  }

  static Future<void> set(String key, Object? value) async {
    data[key] = value;
    try {
      await _file.parent.create(recursive: true);
      await _file.writeAsString(jsonEncode(data));
    } catch (_) {}
  }

  static bool get termsAccepted => data['terms'] == true;

  static List<Map<String, dynamic>> get library => [
        for (final e in (data['library'] as List? ?? const []))
          if (e is Map) Map<String, dynamic>.from(e)
      ];

  static Future<void> saveLibrary(List<Map<String, dynamic>> l) => set('library', l);

  static int ratingFor(int id) => ((data['ratings'] as Map?)?['$id'] as num?)?.toInt() ?? 0;

  static Future<void> rate(int id, int stars) {
    final m = Map<String, dynamic>.from((data['ratings'] as Map?) ?? {});
    m['$id'] = stars;
    return set('ratings', m);
  }
}

