class Net {
  static String? lastError;

  static final HttpClient _c = HttpClient()
    ..connectionTimeout = const Duration(seconds: 10)
    ..idleTimeout = const Duration(seconds: 4)
    ..userAgent = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) LightcatSideloader/0.2';

  static Future<dynamic> json(String url, {int tries = 3}) async {
    for (var n = 0; n < tries; n++) {
      try {
        final req = await _c.getUrl(Uri.parse(url));
        final res = await req.close().timeout(const Duration(seconds: 15));
        if (res.statusCode == 200) {
          final body = await res.transform(utf8.decoder).join();
          return jsonDecode(body);
        }
        await res.drain<void>();
        lastError = 'HTTP ${res.statusCode}';
        if (res.statusCode == 429) {
          final ra = int.tryParse(res.headers.value('retry-after') ?? '');
          if (ra != null && ra > 0 && ra <= 10) await Future.delayed(Duration(seconds: ra));
        }
        if (res.statusCode != 429 && res.statusCode < 500) return null;
      } catch (e) {
        lastError = e is TimeoutException ? 'timed out' : 'no connection';
      }
      if (n < tries - 1) await Future.delayed(Duration(milliseconds: 700 * (n + 1)));
    }
    return null;
  }
}

