  static Future<String> exec(List<String> args) async {
    var a = [...args];
    String? s;
    if (a.length >= 2 && a[0] == '-s') {
      s = a[1];
      a = a.sublist(2);
    }
    if (a.isEmpty) return '';
    switch (a[0]) {
      case 'devices':
        final lines = ['List of devices attached'];
        var n = 0;
        for (final id in plugged) {
          final h = _hs[id];
          if (h == null) continue;
          lines.add('$id        device product:${h.$2} model:${h.$1.replaceAll(' ', '_')} device:${h.$2} transport_id:${++n}');
        }
        return lines.join('\n');
      case 'install':
        await Future.delayed(const Duration(seconds: 3));
        return 'Performing Streamed Install\nSuccess';
      case 'push':
        await Future.delayed(const Duration(seconds: 2));
        return '1 file pushed, 0 skipped. 41.6 MB/s (184023551 bytes in 4.217s)';
      case 'pull':
        await Future.delayed(const Duration(seconds: 1));
        return 'adb: error: demo version, nothing was copied';
      case 'uninstall':
        return 'Success';
      case 'shell':
        return _shell(s ?? plugged.firstOrNull ?? _q3, a.skip(1).join(' '));
      case 'connect':
        return 'connected to ${a.length > 1 ? a[1] : 'device'}';
      default:
        return '';
    }
  }

  static final _props = <String, String>{};

  static String _shell(String s, String c) {
    final h = _hs[s] ?? _hs[_q3]!;
    final sp = RegExp(r'^setprop ([\w.]+) (.*)$').firstMatch(c);
    if (sp != null) {
      _props['$s|${sp.group(1)}'] = sp.group(2)!.replaceAll('"', '');
      return '';
    }
    if (c.contains(r'$(getprop debug.')) {
      return RegExp(r'echo (\w+)=\$\(getprop ([\w.]+)\)')
          .allMatches(c)
          .map((m) => '${m.group(1)}=${_props['$s|${m.group(2)}'] ?? ''}')
          .join('\n');
    }
    if (c.contains('mWakefulness')) return s == _q3s ? 'mWakefulness=Asleep' : 'mWakefulness=Awake';
    if (c.contains('ro.product.model')) return h.$1;
    if (c.contains('ro.serialno')) return s;
    if (c.contains('current_speed')) return h.$3;
    if (c.startsWith('dumpsys battery')) {
      final lv = h.$5 ? math.min(100, h.$4 + _secs ~/ 60) : math.max(5, h.$4 - _secs ~/ 60);
      final amps = s == _q2 ? 900000 : 3000000;
      return 'Current Battery Service state:\n  status: ${h.$5 ? (lv >= 100 ? 5 : 2) : 3}\n  level: $lv\n'
          '  Max charging current: $amps\n  Max charging voltage: 5000000';
    }
    if (c.contains('OVRRemoteService')) {
      if (s == _pro) {
        return 'Paired device: 3C1D, Type: Right, Battery: ${math.max(1, 19 - _secs ~/ 45)}%, Status: Connected';
      }
      if (s == _q3s) {
        return 'Paired device: 2B11, Type: Left, Battery: ${math.max(1, 64 - _secs ~/ 50)}%, Status: Connected';
      }
      if (s == _q2) {
        return 'Paired device: 1A01, Type: Left, Battery: ${math.max(1, 41 - _secs ~/ 60)}%, Status: Connected\n'
            'Paired device: 1A02, Type: Right, Battery: ${math.max(1, 12 - _secs ~/ 90)}%, Status: Connected';
      }
      return 'Paired device: 2A4F, Type: Left, Battery: ${math.max(1, 87 - _secs ~/ 30)}%, Status: Connected\n'
          'Paired device: 2A50, Type: Right, Battery: ${math.max(1, 73 - _secs ~/ 40)}%, Status: Connected';
    }
    if (c.startsWith('df')) {
      return 'Filesystem 1K-blocks Used Available Use% Mounted on\n'
          '/dev/fuse ${h.$6} ${h.$6 - h.$7} ${h.$7} ${(h.$6 - h.$7) * 100 ~/ h.$6}% /storage/emulated';
    }
    if (c.startsWith('pm list packages')) {
      return [
        for (final l in _apps[s] ?? _apps[_q3]!)
          () {
            final p = l.split(' ');
            return 'package:${p[0]} versionCode:${p[1]} installer=${p[2]}';
          }()
      ].join('\n');
    }
    if (c.startsWith('pm path')) return 'package:/data/app/~~demo/base.apk';
    if (c.startsWith('ls -p')) {
      final m = RegExp(r'"(.*?)/?"').firstMatch(c);
      var p = m?.group(1) ?? '/sdcard';
      if (p.endsWith('/')) p = p.substring(0, p.length - 1);
      if (p == '/sdcard/Download') return _dl[s] ?? _dl[_q3]!;
      return _files[p] ?? 'demo_photo.jpg\ndemo_clip.mp4\nnotes.txt';
    }
    if (c.startsWith('ip -f inet')) return '    inet 192.168.1.${h.$8}/24 brd 192.168.1.255 scope global wlan0';
    return '';
  }
}

class AdbDev {
  final String serial, state, model;
  AdbDev(this.serial, this.state, this.model);
}

class DeviceInfo {
  String name;
  final String serial;
  String id = '';
  String? usb;
  int? left, right;
  bool leftOn = true, rightOn = true;
  int battery = 0;
  bool charging = false;
  bool full = false;
  bool slow = false;
  bool asleep = false;
  double watts = 0;
  double freeGb = 0;
  double totalGb = 0;
  DeviceInfo(this.name, this.serial);
  bool get wifi => serial.contains(':');
  String get model {
    final n = name.toLowerCase();
    if (n.contains('3s')) return 'q3s';
    if (n.contains('pro')) return 'qpro';
    if (n.contains('3')) return 'q3';
    if (n.contains('2')) return 'q2';
    return '';
  }

  int get usbLevel => usb == 'USB 2.0' ? 1 : (usb != null && usb!.startsWith('USB 1') ? 2 : 0);
  bool get slowUsb => usbLevel > 0;

  bool get rechargeablePads => model == 'qpro';
  String get powerText => charging && battery >= 100
      ? 'Fully charged'
      : charging
      ? (slow ? 'Charging slowly' : 'Charging now')
      : (full ? 'Fully charged' : 'Running on battery');
}

class Adb {
  static String? _path;
  static String? serial;

  static String get path {
    if (_path != null) return _path!;
    final exeDir = File(Platform.resolvedExecutable).parent.path;
    for (final c in ['$exeDir\\platform-tools\\adb.exe', r'C:\src\platform-tools\adb.exe']) {
      if (File(c).existsSync()) return _path = c;
    }
    return _path = 'adb';
  }

  static Future<String> exec(List<String> args, {Duration timeout = const Duration(seconds: 25)}) async {
    if (kDemo) return Demo.exec(args);
    try {
      final r = await Process.run(path, args).timeout(timeout);
      final out = '${r.stdout}'.trim();
      final err = '${r.stderr}'.trim();
      if (out.isEmpty) return err;
      if (err.isEmpty) return out;
      return '$out\n$err';
    } on TimeoutException {
      return 'error: timed out';
    } catch (e) {
      return 'error: $e';
    }
  }

  static Future<String> run(List<String> args, {Duration timeout = const Duration(seconds: 25), String? on}) {
    final s = on ?? serial;
    return exec([if (s != null) ...['-s', s], ...args], timeout: timeout);
  }

  static Future<String> shell(String cmd, {String? on}) => run(['shell', cmd], on: on);

  static Future<List<int>?> bytes(List<String> args) async {
    if (kDemo) return null;
    try {
      final r = await Process.run(path, [if (serial != null) ...['-s', serial!], ...args], stdoutEncoding: null)
          .timeout(const Duration(seconds: 20));
      final out = r.stdout;
      if (out is List<int> && out.isNotEmpty) return out;
    } catch (_) {}
    return null;
  }

  static Future<List<AdbDev>> devices() async {
    final out = await exec(['devices', '-l'], timeout: const Duration(seconds: 15));
    final res = <AdbDev>[];
    for (final line in out.split('\n')) {
      final l = line.trim();
      if (l.isEmpty || l.startsWith('List of') || l.startsWith('*') || l.startsWith('error')) continue;
      final p = l.split(RegExp(r'\s+'));
      if (p.length < 2) continue;
      final mp = p.firstWhere((x) => x.startsWith('model:'), orElse: () => '');
      res.add(AdbDev(p[0], p[1], mp.isEmpty ? '' : mp.substring(6).replaceAll('_', ' ')));
    }
    return res;
  }

  static Future<DeviceInfo> info(AdbDev d) async {
    final on = d.serial;
    var name = (await shell('getprop ro.product.model', on: on)).trim();
    if (name.isEmpty || name.startsWith('error')) name = d.model.isEmpty ? 'Quest' : d.model;
    if (!name.toLowerCase().startsWith('meta')) name = 'Meta $name';
    final inf = DeviceInfo(name, d.serial);
    final sn = (await shell('getprop ro.serialno', on: on)).trim();
    inf.id = sn.isEmpty || sn.startsWith('error') ? d.serial : sn;
    if (!inf.wifi) inf.usb = await usbSpeed(on);
    await battery(inf);
    await controllers(inf);
    await storage(inf);
    return inf;
  }

  static String? _speedFrom(String raw) {
    final out = raw.toLowerCase();
    if (out.contains('super-speed-plus') || out.contains('superspeed_plus') || out.contains('super_speed_plus')) return 'USB 3.2';
    if (out.contains('super-speed') || out.contains('superspeed') || out.contains('super_speed')) return 'USB 3.0';
    if (out.contains('high-speed') || out.contains('high_speed') || out.contains('highspeed')) return 'USB 2.0';
    if (out.contains('full-speed') || out.contains('full_speed') || out.contains('fullspeed')) return 'USB 1.1';
    if (out.contains('low-speed') || out.contains('low_speed') || out.contains('lowspeed')) return 'USB 1.0';
    for (final m in RegExp(r'speed[^0-9\n]{0,24}(\d{2,5})').allMatches(out)) {
      final v = int.parse(m.group(1)!);
      if (v >= 10000) return 'USB 3.2';
      if (v >= 5000) return 'USB 3.0';
      if (v >= 480) return 'USB 2.0';
      if (v >= 12) return 'USB 1.1';
    }
    return null;
  }

  static Future<String?> usbSpeed(String serial) async {
    final out = await shell(
        r'cat /sys/class/udc/*/current_speed 2>/dev/null; cat /sys/devices/platform/*/*dwc3*/udc/*/current_speed 2>/dev/null; dumpsys usb 2>/dev/null | grep -i speed',
        on: serial);
    final a = _speedFrom(out);
    if (a != null || kDemo) return a;
    final b = await _hostSpeed(serial);
    if (b != null) return b;
    return _speedFrom(await shell(r'dmesg 2>/dev/null | grep -iE "(high|super|full)[- ]?speed" | tail -1', on: serial));
  }

  static Future<String?> _hostSpeed(String serial) async {
    try {
      final s = await Socket.connect(InternetAddress.loopbackIPv4, 5037, timeout: const Duration(seconds: 2));
      const cmd = 'host:track-devices-proto-text';
      s.write('${cmd.length.toRadixString(16).padLeft(4, '0')}$cmd');
      final buf = <int>[];
      final sub = s.listen(buf.addAll, onError: (_) {});
      await Future.delayed(const Duration(milliseconds: 900));
      await sub.cancel();
      s.destroy();
      final txt = latin1.decode(buf, allowInvalid: true);
      final at = txt.indexOf(serial);
      if (at < 0) return null;
      final next = txt.indexOf('serial:', at + 1);
      final block = txt.substring(at, next < 0 ? txt.length : next);
      final m = RegExp(r'negotiated_speed:\s*(\d+)').firstMatch(block);
      return m == null ? null : _speedFrom('speed ${m.group(1)}');
    } catch (_) {
      return null;
    }
  }

  static Future<void> controllers(DeviceInfo inf) async {
    final out = await shell('dumpsys OVRRemoteService | grep -iE "battery|type:"', on: inf.serial);
    if (!out.contains('Type:')) {
      inf.left = inf.right = null;
      return;
    }
    int? l, r;
    var lOn = false, rOn = false;
    for (final line in out.split('\n')) {
      final side = RegExp(r'Type:\s*(Left|Right)', caseSensitive: false).firstMatch(line)?.group(1)?.toLowerCase();
      final bat = RegExp(r'Battery:\s*(\d+)').firstMatch(line);
      if (side == null || bat == null) continue;
      final status = RegExp(r'Status:\s*([A-Za-z_]+)').firstMatch(line)?.group(1)?.toLowerCase() ?? '';
      final on = !status.contains('disconnect');
      final v = on ? int.parse(bat.group(1)!) : 0;
      if (side == 'left') {
        l = v;
        lOn = on;
      } else {
        r = v;
        rOn = on;
      }
    }
    inf.left = l ?? 0;
    inf.right = r ?? 0;
    inf.leftOn = l != null && lOn;
    inf.rightOn = r != null && rOn;
  }

  static Future<void> storage(DeviceInfo inf) async {
    final df = await shell('df -k /sdcard', on: inf.serial);
    final lines = df.split('\n').where((l) => l.trim().isNotEmpty).toList();
    if (lines.length >= 2) {
      final p = lines.last.trim().split(RegExp(r'\s+'));
      if (p.length >= 4) {
        inf.totalGb = (int.tryParse(p[1]) ?? 0) / 1048576;
        inf.freeGb = (int.tryParse(p[3]) ?? 0) / 1048576;
      }
    }
  }

  static Future<void> battery(DeviceInfo inf) async {
    final out = await shell('dumpsys battery', on: inf.serial);
    final wake = await shell('dumpsys power | grep -m1 mWakefulness', on: inf.serial);
    inf.asleep = wake.contains('Asleep') || wake.contains('Dozing');
    final lv = RegExp(r'level:\s*(\d+)').firstMatch(out);
    final st = RegExp(r'status:\s*(\d+)').firstMatch(out);
    final cur = RegExp(r'Max charging current:\s*(\d+)').firstMatch(out);
    final volt = RegExp(r'Max charging voltage:\s*(\d+)').firstMatch(out);
    if (lv != null) inf.battery = int.parse(lv.group(1)!);
    final s = st == null ? 0 : int.parse(st.group(1)!);
    inf.charging = s == 2;
    inf.full = s == 5;
    if (inf.charging && cur != null && volt != null) {
      inf.watts = int.parse(cur.group(1)!) * int.parse(volt.group(1)!) / 1e12;
      inf.slow = inf.watts > 0 && inf.watts < 7.5;
    } else {
      inf.watts = 0;
      inf.slow = false;
    }
  }
}

enum Link { searching, unauthorized, connected }

class Device extends ChangeNotifier {
  static final Device i = Device._();
  Device._();

  final live = <String, DeviceInfo>{};
  String? selectedId = Prefs.data['selected'] as String?;
  bool unauthorized = false;
  Timer? _timer;
  bool _busy = false;
  int _tick = 0;

  DeviceInfo? get info {
    for (final d in live.values) {
      if (d.id == selectedId) return d;
    }
    return null;
  }

  Link get link => info != null ? Link.connected : (unauthorized ? Link.unauthorized : Link.searching);

  bool isLive(String id) => live.values.any((d) => d.id == id);

  void select(String id) {
    if (id == selectedId) return;
    selectedId = id;
    Prefs.set('selected', id);
    Adb.serial = info?.serial;
    notifyListeners();
    Tray.i.refresh();
  }

  Future<void> plugDemo(String id) async {
    Demo.plug(id);
    for (var n = 0; n < 8 && !isLive(id); n++) {
      await _poll();
      if (!isLive(id)) await Future.delayed(const Duration(milliseconds: 300));
    }
    select(id);
  }

  Future<void> unplugDemo(String id) async {
    Demo.unplug(id);
    for (var n = 0; n < 8 && isLive(id); n++) {
      await _poll();
      if (isLive(id)) await Future.delayed(const Duration(milliseconds: 300));
    }
  }

  void start() {
    _poll();
    _timer ??= Timer.periodic(const Duration(seconds: 2), (_) => _poll());
  }

  int _idle = 0;

  Future<void> _poll() async {
    if (!appVisible.value && ++_idle % 4 != 0) return;
    if (appVisible.value) _idle = 0;
    if (_busy) return;
    _busy = true;
    try {
      final list = await Adb.devices();
      final ok = list.where((d) => d.state == 'device').toList();
      var changed = false;
      final wasUnauth = unauthorized;
      unauthorized = list.any((d) => d.state == 'unauthorized');
      if (wasUnauth != unauthorized) changed = true;

      for (final serial in live.keys.toList()) {
        if (ok.any((d) => d.serial == serial)) continue;
        final gone = live.remove(serial)!;
        Devices.remember(gone);
        Alerts.forget(gone.id);
        changed = true;
        if (gone.id == selectedId && live.isNotEmpty) selectedId = live.values.first.id;
      }

      final fresh = <DeviceInfo>[];
      for (final d in ok) {
        if (live.containsKey(d.serial)) continue;
        final inf = await Adb.info(d);
        live[d.serial] = inf;
        fresh.add(inf);
        Devices.remember(inf);
        Alerts.check(inf);
        Alerts.pads(inf);
        changed = true;
      }
      if (info == null && fresh.isNotEmpty) selectedId = fresh.first.id;
      if (selectedId == null && live.isNotEmpty) selectedId = live.values.first.id;
      if (changed) Prefs.set('selected', selectedId);

      if (!changed) {
        _tick++;
        for (final d in live.values) {
          if (_tick.isEven) {
            await Adb.battery(d);
            Alerts.check(d);
          } else {
            await Adb.controllers(d);
            Alerts.pads(d);
          }
          if (_tick % 15 == 0) await Adb.storage(d);
          if (_tick % 8 == 0) Devices.remember(d);
        }
      }
      Adb.serial = info?.serial;
      notifyListeners();
      Tray.i.refresh();
    } catch (_) {
    } finally {
      _busy = false;
    }
  }
}

class Pick {
  static const _head =
      r"Add-Type -AssemblyName System.Windows.Forms; $o = New-Object System.Windows.Forms.Form -Property @{TopMost=$true}; ";

  static Future<List<String>> files({bool android = true, String? filter}) {
    filter ??=
        android ? 'Android files (*.apk;*.obb)|*.apk;*.obb|All files (*.*)|*.*' : 'All files (*.*)|*.*';
    return _run(_head +
        r"$f = New-Object System.Windows.Forms.OpenFileDialog; $f.Multiselect = $true; $f.Filter = '" +
        filter +
        r"'; if ($f.ShowDialog($o) -eq 'OK') { $f.FileNames -join '|' }");
  }

  static Future<List<String>> folder() => _run(_head +
      r"$f = New-Object System.Windows.Forms.FolderBrowserDialog; if ($f.ShowDialog($o) -eq 'OK') { $f.SelectedPath }");

  static Future<List<String>> _run(String script) async {
    try {
      final r = await Process.run('powershell', ['-NoProfile', '-STA', '-Command', script]);
      final out = '${r.stdout}'.trim();
      if (out.isEmpty) return <String>[];
      return out.split('|').map((e) => e.trim()).where((e) => e.isNotEmpty).toList();
    } catch (_) {
      return <String>[];
    }
  }
}

class Job {
  final String path, name, kind;
  String state = 'queued';
  String note = 'Waiting in line';
  double? progress;
  Job(this.path, this.name, this.kind);
}

class Installer {
  static Future<(bool, String)> handle(Job j) async {
    final r = await _handle(j);
    Notes.i.push(r.$1 ? '${j.name} is ready' : 'Could not install ${j.name}', r.$2,
        icon: r.$1 ? Icons.check_circle_rounded : Icons.error_outline_rounded, color: r.$1 ? Pal.good : Pal.bad);
    return r;
  }

  static Future<(bool, String)> _handle(Job j) {
    if (j.kind == 'APK') return apk(j.path, j);
    if (j.kind == 'OBB') return obb(j.path, j);
    return folder(j.path, j);
  }

  static Future<String> _push(String local, String remote, Job? j) async {
    if (j == null) return Adb.run(['push', local, remote], timeout: const Duration(hours: 1));
    final isDir = FileSystemEntity.isDirectorySync(local);
    final total = _size(local);
    final target = isDir ? '${remote.endsWith('/') ? remote : '$remote/'}${baseName(local)}' : remote;
    j.progress = 0;
    InstallQueue.i.ping();
    final poll = Timer.periodic(const Duration(milliseconds: 500), (_) async {
      final out = await Adb.shell(isDir ? 'du -sk "$target" 2>/dev/null' : 'stat -c %s "$target" 2>/dev/null');
      final n = int.tryParse(out.trim().split(RegExp(r'\s+')).first);
      if (n == null || total <= 0) return;
      j.progress = ((isDir ? n * 1024 : n) / total).clamp(0.0, .99).toDouble();
      InstallQueue.i.ping();
    });
    try {
      return await Adb.run(['push', local, remote], timeout: const Duration(hours: 1));
    } finally {
      poll.cancel();
      j.progress = 1;
      InstallQueue.i.ping();
    }
  }

  static int _size(String p) {
    if (!FileSystemEntity.isDirectorySync(p)) return File(p).lengthSync();
    var n = 0;
    for (final e in Directory(p).listSync(recursive: true)) {
      if (e is File) n += e.lengthSync();
    }
    return n;
  }

  static Future<(bool, String)> apk(String path, [Job? j]) async {
    if (j != null) {
      const tmp = '/data/local/tmp/lightcat_install.apk';
      final pushed = await _push(path, tmp, j);
      if (pushed.contains('pushed')) {
        j.note = 'Installing…';
        InstallQueue.i.ping();
        final res = await Adb.run(['shell', 'pm install -r -g "$tmp"; rm -f "$tmp"'], timeout: const Duration(minutes: 20));
        if (res.contains('Success')) return (true, 'Installed');
        final f = RegExp(r'Failure \[(.+?)\]').firstMatch(res);
        if (f != null) return (false, f.group(1)!);
      }
    }
    final out = await Adb.run(['install', '-r', '-g', path], timeout: const Duration(minutes: 20));
    if (out.contains('Success')) return (true, 'Installed');
    final m = RegExp(r'Failure \[(.+?)\]').firstMatch(out);
    return (false, m?.group(1) ?? _short(out));
  }

  static Future<(bool, String)> obb(String path, [Job? j]) async {
    final name = baseName(path);
    final parts = name.split('.');
    if (parts.length < 4) return (false, 'Rename to main.<version>.<package>.obb so Lightcat knows where it goes');
    final pkg = parts.sublist(2, parts.length - 1).join('.');
    await Adb.shell('mkdir -p /sdcard/Android/obb/$pkg');
    final out = await _push(path, '/sdcard/Android/obb/$pkg/$name', j);
    if (out.contains('pushed')) return (true, 'Copied to Android/obb/$pkg');
    return (false, _short(out));
  }

  static Future<(bool, String)> folder(String path, [Job? j]) async {
    final ents = Directory(path).listSync();
    final apks = ents.whereType<File>().where((f) => f.path.toLowerCase().endsWith('.apk')).toList();
    final looseObb = ents.whereType<File>().where((f) => f.path.toLowerCase().endsWith('.obb')).toList();
    final obbDirs = ents.whereType<Directory>().where((d) {
      if (!baseName(d.path).contains('.')) return false;
      return d.listSync().any((f) => f.path.toLowerCase().endsWith('.obb'));
    }).toList();
    if (apks.isEmpty && looseObb.isEmpty && obbDirs.isEmpty) return (false, 'No APK or OBB files in this folder');

    for (final a in apks) {
      final r = await apk(a.path, j);
      if (!r.$1) return (false, '${baseName(a.path)}: ${r.$2}');
    }
    for (final d in obbDirs) {
      final out = await _push(d.path, '/sdcard/Android/obb/', j);
      if (!out.contains('pushed')) return (false, _short(out));
    }
    for (final f in looseObb) {
      final r = await obb(f.path, j);
      if (!r.$1) return r;
    }
    final bits = <String>[
      if (apks.isNotEmpty) '${apks.length} APK',
      if (obbDirs.isNotEmpty || looseObb.isNotEmpty) 'OBB data',
    ];
    return (true, 'Installed ${bits.join(' + ')}');
  }

  static String _short(String s) {
    final l = s.split('\n').map((e) => e.trim()).where((e) => e.isNotEmpty).toList();
    if (l.isEmpty) return 'Something went wrong';
    final last = l.last;
    return last.length > 120 ? '${last.substring(0, 120)}…' : last;
  }
}

class InstallQueue extends ChangeNotifier {
  static final InstallQueue i = InstallQueue._();
  InstallQueue._();

  final jobs = <Job>[];
  bool _running = false;
  int finished = 0;

  void ping() => notifyListeners();

  void add(List<String> paths, void Function(String) warn) {
    for (final p in paths) {
      final name = baseName(p);
      final low = p.toLowerCase();
      String? kind;
      if (FileSystemEntity.isDirectorySync(p)) {
        kind = 'Folder';
      } else if (low.endsWith('.apk')) {
        kind = 'APK';
      } else if (low.endsWith('.obb')) {
        kind = 'OBB';
      } else if (low.endsWith('.zip')) {
        warn('Extract $name first, then drop the folder here.');
        continue;
      }
      if (kind == null) {
        warn('$name isn’t an APK, OBB or folder, so it was skipped.');
        continue;
      }
      jobs.insert(0, Job(p, name, kind));
    }
    notifyListeners();
    _process();
  }

  void clearFinished() {
    jobs.removeWhere((j) => j.state == 'done' || j.state == 'failed');
    notifyListeners();
  }

  Future<void> _process() async {
    if (_running) return;
    _running = true;
    while (true) {
      Job? next;
      for (final j in jobs.reversed) {
        if (j.state == 'queued') {
          next = j;
          break;
        }
      }
      if (next == null) break;
      if (Device.i.link != Link.connected) {
        next.state = 'failed';
        next.note = 'Connect your headset, then drop it again';
        notifyListeners();
        continue;
      }
      next.state = 'working';
      next.note = 'Copying to headset…';
      notifyListeners();
      final r = await Installer.handle(next);
      next.state = r.$1 ? 'done' : 'failed';
      next.note = r.$2;
      if (r.$1) finished++;
      notifyListeners();
    }
    _running = false;
  }
}

class ToastData {
  final String msg;
  final IconData icon;
  final Color? color;
  final int id;
  ToastData(this.msg, this.icon, this.color, this.id);
}

class Toasts extends ChangeNotifier {
  static final Toasts i = Toasts._();
  Toasts._();
  final items = <ToastData>[];
  int _n = 0;

  void show(String msg, IconData icon, Color? color) {
    items.add(ToastData(msg, icon, color, _n++));
    if (items.length > 3) items.removeAt(0);
    notifyListeners();
  }

  void remove(ToastData d) {
    items.remove(d);
    notifyListeners();
  }
}

void toast(BuildContext c, String msg, {IconData icon = Icons.check_circle_rounded, Color? color}) =>
    Toasts.i.show(msg, icon, color);

class ToastLayer extends StatelessWidget {
  const ToastLayer({super.key});
  @override
  Widget build(BuildContext context) => Align(
        alignment: Alignment.bottomCenter,
        child: Padding(
          padding: const EdgeInsets.only(bottom: 22),
          child: ListenableBuilder(
            listenable: Toasts.i,
            builder: (_, __) => Column(
              mainAxisSize: MainAxisSize.min,
              children: [for (final d in Toasts.i.items) ToastView(key: ValueKey(d.id), d: d)],
            ),
          ),
        ),
      );
}

class ToastView extends StatefulWidget {
  final ToastData d;
  const ToastView({super.key, required this.d});
  @override
  State<ToastView> createState() => _ToastViewState();
}

class _ToastViewState extends State<ToastView> with SingleTickerProviderStateMixin {
  late final AnimationController c = AnimationController(vsync: this, duration: ms(380))..forward();
  late final CurvedAnimation curve = CurvedAnimation(parent: c, curve: Curves.easeOutCubic, reverseCurve: Curves.easeInCubic);
  Timer? _t;

  @override
  void initState() {
    super.initState();
    _t = Timer(const Duration(milliseconds: 3200), () async {
      if (!mounted) return;
      await c.reverse();
      Toasts.i.remove(widget.d);
    });
  }

  @override
  void dispose() {
    _t?.cancel();
    curve.dispose();
    c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => SizeTransition(
        sizeFactor: curve,
        axisAlignment: 1,
        child: FadeTransition(
          opacity: curve,
          child: Glide(
            anim: curve,
            from: const Offset(0, 22),
            child: KeyedSubtree(
              child: Padding(
                padding: const EdgeInsets.only(top: 8),
                child: Container(
                  width: 460,
                  padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 14),
                  decoration: BoxDecoration(
                    color: Pal.card2,
                    borderRadius: BorderRadius.circular(14),
                    border: Border.all(color: (widget.d.color ?? Pal.a).withValues(alpha: .55), width: 1.8),
                    boxShadow: const [BoxShadow(color: Color(0x66000000), blurRadius: 30, offset: Offset(0, 10))],
                  ),
                  child: Row(children: [
                    Icon(widget.d.icon, color: widget.d.color ?? Pal.a, size: 19),
                    const SizedBox(width: 12),
                    Expanded(child: Text(widget.d.msg, style: t(13.5))),
                  ]),
                ),
              ),
            ),
          ),
        ),
      );
}

class SmoothScroll extends StatefulWidget {
  final Widget Function(ScrollController c, ScrollPhysics p) builder;
  const SmoothScroll({super.key, required this.builder});
  @override
  State<SmoothScroll> createState() => _SmoothScrollState();
}

class _SmoothScrollState extends State<SmoothScroll> with SingleTickerProviderStateMixin {
  static final _all = <_SmoothScrollState>{};
  final c = ScrollController();
  double? _target;
  Duration _last = Duration.zero;
  late final _tick = createTicker(_step);

  @override
  void initState() {
    super.initState();
    _all.add(this);
  }

  @override
  void dispose() {
    _all.remove(this);
    _tick.dispose();
    c.dispose();
    super.dispose();
  }

  static bool keyScroll(double delta, {bool toEnd = false, bool toStart = false}) {
    _SmoothScrollState? best;
    for (final st in _all) {
      if (!st.mounted || !st.c.hasClients || !TickerMode.valuesOf(st.context).enabled) continue;
      final pos = st.c.position;
      if (pos.maxScrollExtent <= 0) continue;
      if (best == null || pos.viewportDimension > best.c.position.viewportDimension) best = st;
    }
    if (best == null) return false;
    final pos = best.c.position;
    final from = best._target ?? pos.pixels;
    final next = toEnd ? pos.maxScrollExtent : (toStart ? 0.0 : from + delta);
    best._to(next);
    return true;
  }

  void _to(double v) {
    final pos = c.position;
    final next = cl(v, pos.minScrollExtent, pos.maxScrollExtent);
    if (Pal.reduceMotion.value) {
      _target = null;
      c.jumpTo(next);
      return;
    }
    if (!_tick.isActive && (next - pos.pixels).abs() < .3) return;
    _target = next;
    if (!_tick.isActive) {
      _last = Duration.zero;
      _tick.start();
    }
  }

  void _step(Duration now) {
    final target = _target;
    if (target == null || !c.hasClients) {
      _tick.stop();
      return;
    }
    final dt = math.min((now - _last).inMicroseconds / 1e6, .05);
    _last = now;
    final pos = c.position;
    final left = target - pos.pixels;
    if (left.abs() < .3) {
      c.jumpTo(target);
      _target = null;
      _tick.stop();
      return;
    }
    c.jumpTo(pos.pixels + left * (1 - math.exp(-dt / .085)));
  }

  void _signal(PointerSignalEvent e) {
    if (e is! PointerScrollEvent || !c.hasClients) return;
    _to((_target ?? c.position.pixels) + e.scrollDelta.dy * 1.15);
  }

  void _pan(PointerPanZoomUpdateEvent e) {
    if (!c.hasClients) return;
    final pos = c.position;
    _target = null;
    c.jumpTo(cl(pos.pixels - e.panDelta.dy, pos.minScrollExtent, pos.maxScrollExtent));
  }

  @override
  Widget build(BuildContext context) => Listener(
        onPointerSignal: _signal,
        onPointerPanZoomUpdate: _pan,
        child: Stack(children: [
          Positioned.fill(child: widget.builder(c, const NeverScrollableScrollPhysics())),
          Positioned(right: 0, top: 6, bottom: 6, width: 22, child: _Thumb(c: c, onDrag: () => _target = null)),
        ]),
      );
}

class _Thumb extends StatefulWidget {
  final ScrollController c;
  final VoidCallback onDrag;
  const _Thumb({required this.c, required this.onDrag});
  @override
  State<_Thumb> createState() => _ThumbState();
}

class _ThumbState extends State<_Thumb> {
  bool awake = false, near = false, drag = false;
  Timer? _t;

  @override
  void initState() {
    super.initState();
    widget.c.addListener(_moved);
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) setState(() {});
    });
  }

  @override
  void dispose() {
    widget.c.removeListener(_moved);
    _t?.cancel();
    super.dispose();
  }

  void _moved() {
    if (!mounted) return;
    setState(() => awake = true);
    _t?.cancel();
    _t = Timer(const Duration(milliseconds: 1100), () {
      if (mounted) setState(() => awake = false);
    });
  }

  @override
  Widget build(BuildContext context) {
    final c = widget.c;
    if (!c.hasClients || !c.position.hasContentDimensions || c.position.maxScrollExtent <= 0) {
      return const SizedBox.shrink();
    }
    return LayoutBuilder(builder: (_, box) {
      final pos = c.position;
      final track = box.maxHeight;
      final max = pos.maxScrollExtent;
      final len = cl(track * pos.viewportDimension / (pos.viewportDimension + max), 48, track);
      final span = track - len;
      final top = span <= 0 ? 0.0 : span * cl(pos.pixels / max, 0, 1);
      final show = awake || near || drag;
      return MouseRegion(
        opaque: false,
        onEnter: (_) => setState(() => near = true),
        onExit: (_) => setState(() => near = false),
        child: Stack(children: [
          Positioned(
            right: 3,
            top: top,
            width: 14,
            height: len,
            child: IgnorePointer(
              ignoring: !show,
              child: GestureDetector(
                behavior: HitTestBehavior.opaque,
                onVerticalDragStart: (_) {
                  widget.onDrag();
                  setState(() => drag = true);
                },
                onVerticalDragUpdate: (d) {
                  if (span <= 0) return;
                  widget.onDrag();
                  c.jumpTo(cl(pos.pixels + d.delta.dy * max / span, 0, max));
                },
                onVerticalDragEnd: (_) => setState(() => drag = false),
                onVerticalDragCancel: () => setState(() => drag = false),
                child: AnimatedOpacity(
                  opacity: show ? 1 : 0,
                  duration: ms(220),
                  child: Align(
                    alignment: Alignment.centerRight,
                    child: AnimatedContainer(
                      duration: ms(140),
                      width: near || drag ? 9 : 6,
                      decoration: BoxDecoration(
                        color: Colors.white.withValues(alpha: drag ? .5 : (near ? .36 : .22)),
                        borderRadius: BorderRadius.circular(8),
                      ),
                    ),
                  ),
                ),
              ),
            ),
          ),
        ]),
      );
    });
  }
}

