class _HoverState extends State<Hover> {
  bool h = false, down = false;
  @override
  Widget build(BuildContext context) {
    final tap = widget.onTap != null;
    return MouseRegion(
      cursor: tap ? SystemMouseCursors.click : MouseCursor.defer,
      onEnter: (_) => setState(() => h = true),
      onExit: (_) => setState(() {
        h = false;
        down = false;
      }),
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        onTap: widget.onTap,
        onTapDown: tap ? (_) => setState(() => down = true) : null,
        onTapUp: tap ? (_) => setState(() => down = false) : null,
        onTapCancel: tap ? () => setState(() => down = false) : null,
        child: AnimatedScale(
          scale: down ? .97 : 1,
          duration: ms(down ? 100 : 340),
          curve: down ? Curves.easeOutCubic : Curves.easeOutQuint,
          child: RepaintBoundary(child: widget.builder(h)),
        ),
      ),
    );
  }
}

