Offset snapOffset(BuildContext c, Offset o) {
  final r = MediaQuery.maybeDevicePixelRatioOf(c) ?? 1.0;
  return Offset((o.dx * r).roundToDouble() / r, (o.dy * r).roundToDouble() / r);
}

class FadeIn extends StatefulWidget {
  final Widget child;
  final int delay;
  final double dy;
  const FadeIn({super.key, required this.child, this.delay = 0, this.dy = .06});
  @override
  State<FadeIn> createState() => _FadeInState();
}

class _FadeInState extends State<FadeIn> {
  static final _seen = <Key>{};
  bool shown = false;
  Timer? _t;

  @override
  void initState() {
    super.initState();
    final k = widget.key;
    if (Pal.reduceMotion.value || (k != null && _seen.contains(k))) {
      shown = true;
      return;
    }
    _t = Timer(Duration(milliseconds: 16 + widget.delay), () {
      if (!mounted) return;
      setState(() => shown = true);
      if (k != null) _seen.add(k);
    });
  }

  @override
  void dispose() {
    _t?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return TweenAnimationBuilder<double>(
      tween: Tween(begin: shown ? 1.0 : 0.0, end: shown ? 1.0 : 0.0),
      duration: ms(560),
      curve: Curves.easeOutCubic,
      builder: (context, v, child) => Opacity(
        opacity: v,
        child: Transform.translate(
          offset: snapOffset(context, Offset(0, (1 - v) * math.min(24.0, widget.dy * 300))),
          child: child,
        ),
      ),
      child: widget.child,
    );
  }
}

class Glide extends AnimatedWidget {
  final Offset from;
  final Widget child;
  const Glide({super.key, required Animation<double> anim, required this.from, required this.child}) : super(listenable: anim);

  @override
  Widget build(BuildContext context) {
    final v = (listenable as Animation<double>).value;
    return Transform.translate(offset: snapOffset(context, from * (1 - v)), child: child);
  }
}

