class Seg extends StatelessWidget {
  final List<String> items;
  final int sel;
  final ValueChanged<int> on;
  final double? width;
  const Seg({super.key, required this.items, required this.sel, required this.on, this.width});

  static double wOf(String s) => s.length * 7.4 + 26;

  @override
  Widget build(BuildContext context) {
    final ws = width != null ? List.filled(items.length, (width! - 8) / items.length) : items.map(wOf).toList();
    final s = math.min(math.max(sel, 0), items.length - 1);
    var left = 0.0;
    for (var i = 0; i < s; i++) {
      left += ws[i];
    }
    return Container(
      padding: const EdgeInsets.all(3),
      decoration: BoxDecoration(
        color: Colors.white.withValues(alpha: .04),
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: Pal.stroke),
      ),
      child: SizedBox(
        height: 32,
        width: ws.fold<double>(0, (a, b) => a + b),
        child: Stack(children: [
          AnimatedPositioned(
            duration: ms(360),
            curve: Curves.easeOutCubic,
            left: left,
            top: 0,
            bottom: 0,
            width: ws[s],
            child: Container(
              decoration: BoxDecoration(
                gradient: Pal.grad,
                borderRadius: BorderRadius.circular(9),
                boxShadow: [BoxShadow(color: Pal.a.withValues(alpha: .3), blurRadius: 12)],
              ),
            ),
          ),
          Row(children: [
            for (var i = 0; i < items.length; i++)
              Hover(
                onTap: () => on(i),
                builder: (h) => SizedBox(
                  width: ws[i],
                  child: Center(
                    child: AnimatedDefaultTextStyle(
                      duration: ms(220),
                      style: t(12.5, w: FontWeight.w600, c: i == s ? Pal.ink : (h ? Pal.text : Pal.sub)),
                      child: Text(items[i]),
                    ),
                  ),
                ),
              ),
          ]),
        ]),
      ),
    );
  }
}

