      this.autofocus = false,
      this.clearable = true});
  @override
  State<Field> createState() => _FieldState();
}

class _FieldState extends State<Field> {
  TextEditingController? _own;
  TextEditingController get _c => widget.c ?? (_own ??= TextEditingController());

  @override
  void initState() {
    super.initState();
    _c.addListener(_changed);
  }

  @override
  void didUpdateWidget(Field old) {
    super.didUpdateWidget(old);
    if (old.c != widget.c) {
      (old.c ?? _own)?.removeListener(_changed);
      _c.addListener(_changed);
    }
  }

  void _changed() => WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) setState(() {});
      });

  @override
  void dispose() {
    _c.removeListener(_changed);
    _own?.dispose();
    super.dispose();
  }

  Widget _clearBtn() => ClearX(onTap: () {
        _c.clear();
        widget.onChanged?.call('');
        widget.focus?.requestFocus();
      });

  @override
  Widget build(BuildContext context) => SizedBox(
        width: widget.width,
        height: 42,
        child: TextField(
          controller: _c,
          focusNode: widget.focus,
          autofocus: widget.autofocus,
          onChanged: widget.onChanged,
          onSubmitted: widget.onSubmit,
          cursorColor: Pal.a,
          style: widget.mono ? t(13, f: 'Consolas') : t(13.5),
          decoration: InputDecoration(
            isDense: true,
            hintText: widget.hint,
            hintStyle: widget.mono ? t(13, c: Pal.dim, f: 'Consolas') : t(13.5, c: Pal.dim),
            prefixIcon: widget.icon == null ? null : Icon(widget.icon, size: 18, color: Pal.dim),
            suffixIcon: !widget.clearable || _c.text.isEmpty ? null : _clearBtn(),
            suffixIconConstraints: const BoxConstraints(minWidth: 38, minHeight: 38),
            filled: true,
            fillColor: Colors.white.withValues(alpha: .04),
            contentPadding: const EdgeInsets.symmetric(horizontal: 14, vertical: 13),
            enabledBorder: OutlineInputBorder(
                borderRadius: BorderRadius.circular(12), borderSide: const BorderSide(color: Pal.stroke)),
            focusedBorder: OutlineInputBorder(
                borderRadius: BorderRadius.circular(12), borderSide: BorderSide(color: Pal.a.withValues(alpha: .6))),
          ),
        ),
      );
}

