}

class _PulseDotState extends State<PulseDot> with SingleTickerProviderStateMixin {
  late final AnimationController c =
      AnimationController(vsync: this, duration: const Duration(milliseconds: 1500))..repeat();
  @override
  void dispose() {
    c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => SizedBox(
        width: widget.size * 3,
        height: widget.size * 3,
        child: RepaintBoundary(
          child: AnimatedBuilder(
            animation: c,
            builder: (_, __) {
              final v = Curves.easeOut.transform(c.value);
              return Stack(alignment: Alignment.center, children: [
                Container(
                  width: widget.size * (1 + 2 * v),
                  height: widget.size * (1 + 2 * v),
                  decoration:
                      BoxDecoration(shape: BoxShape.circle, color: widget.color.withValues(alpha: (1 - v) * .5)),
                ),
                Container(
                    width: widget.size,
                    height: widget.size,
                    decoration: BoxDecoration(shape: BoxShape.circle, color: widget.color)),
              ]);
            },
          ),
        ),
      );
}

