class NetImg extends StatelessWidget {
  final String url;
  final String? fallback;
  final BoxFit fit;
  final int? cacheWidth;
  const NetImg(this.url, {super.key, this.fallback, this.fit = BoxFit.cover, this.cacheWidth});
  @override
  Widget build(BuildContext context) => Container(
        color: Pal.card2,
        child: Image.network(
          url,
          fit: fit,
          width: double.infinity,
          height: double.infinity,
          cacheWidth: cacheWidth,
          gaplessPlayback: true,
          frameBuilder: (_, child, frame, sync) => sync
              ? child
              : AnimatedOpacity(
                  opacity: frame == null ? 0 : 1, duration: ms(450), curve: Curves.easeOut, child: child),
          errorBuilder: (_, __, ___) => fallback != null
              ? NetImg(fallback!, fit: fit, cacheWidth: cacheWidth)
              : const Center(child: Icon(Icons.image_not_supported_rounded, color: Pal.dim)),
        ),
      );
}

Future<T?> _sheet<T>(BuildContext c, Widget Function(BuildContext) body, {double width = 440}) =>
    showGeneralDialog<T>(
      context: c,
      barrierDismissible: true,
      barrierLabel: 'close',
      barrierColor: Colors.black.withValues(alpha: .55),
      transitionDuration: ms(280),
      transitionBuilder: (_, a, __, child) {
        final cv = CurvedAnimation(parent: a, curve: Curves.easeOutCubic, reverseCurve: Curves.easeInCubic);
        return FadeTransition(
          opacity: cv,
          child: Glide(anim: cv, from: const Offset(0, 18), child: child),
        );
      },
      pageBuilder: (ctx, _, __) => Center(
        child: Material(
          color: Colors.transparent,
          child: Container(
            width: width,
            padding: const EdgeInsets.all(26),
            decoration: BoxDecoration(
              color: Pal.card,
              borderRadius: BorderRadius.circular(22),
              border: Border.all(color: Pal.stroke),
              boxShadow: const [BoxShadow(color: Color(0x80000000), blurRadius: 60, offset: Offset(0, 20))],
            ),
            child: body(ctx),
          ),
        ),
      ),
    );

Future<bool> confirm(BuildContext c, String title, String body,
    {String action = 'Confirm', bool danger = false}) async {
  final r = await _sheet<bool>(
    c,
    (ctx) => Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [
      Text(title, style: t(20, w: FontWeight.w700, display: true)),
      const SizedBox(height: 8),
      Text(body, style: t(13.5, c: Pal.sub, h: 1.5)),
      const SizedBox(height: 24),
      Row(children: [
        const Spacer(),
        Btn(label: 'Cancel', onTap: () => Navigator.pop(ctx, false)),
        const SizedBox(width: 10),
        Btn(label: action, primary: !danger, danger: danger, onTap: () => Navigator.pop(ctx, true)),
      ]),
    ]),
  );
  return r ?? false;
}

