Future<void> leaveTo(BuildContext c, String url, String site) async {
  if (Prefs.data['skipLeave'] == true) {
    await openUrl(url);
    return;
  }
  var dontAsk = false;
  final go = await _sheet<bool>(
    c,
    (ctx) => StatefulBuilder(
      builder: (ctx, setS) => Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: [
          const Logo(size: 34),
          const SizedBox(width: 10),
          const Icon(Icons.arrow_forward_rounded, color: Pal.dim, size: 18),
          const SizedBox(width: 10),
          Container(
            width: 34,
            height: 34,
            decoration:
                BoxDecoration(color: Colors.white.withValues(alpha: .06), borderRadius: BorderRadius.circular(10)),
            child: const Icon(Icons.public_rounded, color: Pal.sub, size: 18),
          ),
        ]),
        const SizedBox(height: 18),
        Text('You’re about to leave Lightcat', style: t(20, w: FontWeight.w700, display: true)),
        const SizedBox(height: 8),
        Text('This opens $site in your browser. Their own terms and prices apply there.',
            style: t(13.5, c: Pal.sub, h: 1.5)),
        const SizedBox(height: 18),
        Row(children: [
          CheckMark(v: dontAsk, on: (v) => setS(() => dontAsk = v)),
          const SizedBox(width: 10),
          Text('Don’t ask me again', style: t(13.5)),
        ]),
        const SizedBox(height: 22),
        Row(children: [
          const Spacer(),
          Btn(label: 'Back', onTap: () => Navigator.pop(ctx, false)),
          const SizedBox(width: 10),
          Btn(label: 'Open $site', icon: Icons.open_in_new_rounded, primary: true, onTap: () => Navigator.pop(ctx, true)),
        ]),
      ]),
    ),
  );
  if (go == true) {
    if (dontAsk) await Prefs.set('skipLeave', true);
    await openUrl(url);
  }
}

class FogCard extends StatelessWidget {
