Future<void> sideloadFiles(BuildContext c, List<String> paths) async {
  if (paths.isEmpty) return;
  if (!await SideloadNotice.show(c) || !c.mounted) return;
  InstallQueue.i.add(paths, (m) => toast(c, m, icon: Icons.info_rounded, color: Pal.warn));
}

class SideloadNotice {
  static bool _showing = false;

  static Future<bool> show(BuildContext context) async {
    if (Prefs.data['sideloadWarned'] == true) return true;
    if (_showing) return false;
    _showing = true;
    var agreed = false;
    var typed = '';
    final ctl = TextEditingController();
    final ok = await showGeneralDialog<bool>(
          context: context,
          barrierDismissible: false,
          barrierLabel: 'sideload',
          barrierColor: Colors.transparent,
          transitionDuration: ms(560),
          pageBuilder: (ctx, anim, _) => FogCard(
            anim: anim,
            child: StatefulBuilder(
              builder: (ctx, setS) {
                final done = agreed && typed.trim().toUpperCase() == 'ACCEPT';
                void accept() {
                  Prefs.set('sideloadWarned', true);
                  Navigator.pop(ctx, true);
                }

                return Column(mainAxisSize: MainAxisSize.min, children: [
                  const IconTile(size: 46, child: Icon(Icons.warning_amber_rounded, color: Pal.warn, size: 24)),
                  const SizedBox(height: 16),
                  Text('Before you sideload', textAlign: TextAlign.center, style: t(20, w: FontWeight.w800, display: true)),
                  const SizedBox(height: 10),
                  Text('Pirated games are illegal and can get your Meta account banned. Lightcat is built around freedom and won’t block what you install, so keeping your account safe is up to you. Only install apps that are “fan made”, alpha or beta.',
                      textAlign: TextAlign.center, style: t(13.5, c: Pal.sub, h: 1.5)),
                  const SizedBox(height: 22),
                  Hover(
                    onTap: () => setS(() => agreed = !agreed),
                    builder: (h) => Row(mainAxisSize: MainAxisSize.min, children: [
                      CheckMark(v: agreed, on: (v) => setS(() => agreed = v)),
                      const SizedBox(width: 12),
                      Text('I understand', style: t(14.5, w: FontWeight.w600)),
                    ]),
                  ),
                  AnimatedSize(
                    duration: ms(420),
                    curve: Curves.easeOutCubic,
                    child: AnimatedSwitcher(
                      duration: ms(380),
                      switchInCurve: Curves.easeOutCubic,
                      transitionBuilder: (c, a) => FadeTransition(
                        opacity: a,
                        child: Glide(anim: a, from: const Offset(0, 10), child: c),
                      ),
                      child: agreed
                          ? Padding(
                              key: const ValueKey('type'),
                              padding: const EdgeInsets.only(top: 18),
                              child: Column(children: [
                                Text('To confirm, type ACCEPT below', style: t(13, c: Pal.sub)),
                                const SizedBox(height: 10),
                                Field(
                                  c: ctl,
                                  width: 220,
                                  hint: 'ACCEPT',
                                  mono: true,
                                  autofocus: true,
                                  onChanged: (v) => setS(() => typed = v),
                                  onSubmit: (_) {
                                    if (done) accept();
                                  },
                                ),
                              ]),
                            )
                          : const SizedBox(key: ValueKey('none'), width: double.infinity),
                    ),
                  ),
                  const SizedBox(height: 22),
                  Row(mainAxisAlignment: MainAxisAlignment.center, children: [
                    Btn(
                      label: 'Not now',
                      onTap: () {
                        Navigator.pop(ctx, false);
                        navTo.value = 0;
                      },
                    ),
                    const SizedBox(width: 10),
                    AnimatedOpacity(
                      opacity: done ? 1 : .4,
                      duration: ms(250),
                      child: IgnorePointer(
                        ignoring: !done,
                        child: Btn(label: 'Accept', icon: Icons.check_rounded, primary: true, onTap: accept),
                      ),
                    ),
                  ]),
                ]);
              },
            ),
          ),
        ) ??
        false;
    _showing = false;
    Future.delayed(const Duration(seconds: 1), ctl.dispose);
    return ok;
  }
}

