class IconTile extends StatelessWidget {
  final Widget child;
  final double size;
  const IconTile({super.key, required this.child, this.size = 42});

  @override
  Widget build(BuildContext context) => TweenAnimationBuilder<double>(
        tween: Tween<double>(begin: 0, end: 1),
        duration: ms(620),
        curve: Curves.easeOutBack,
        builder: (_, v, c) => Transform.scale(scale: .6 + .4 * v, child: Opacity(opacity: v.clamp(0.0, 1.0), child: c)),
        child: Container(
          width: size,
          height: size,
          alignment: Alignment.center,
          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(size * .3),
            gradient: LinearGradient(
              begin: Alignment.topLeft,
              end: Alignment.bottomRight,
              colors: [Pal.a.withValues(alpha: .26), Pal.b.withValues(alpha: .12)],
            ),
            border: Border.all(color: Pal.a.withValues(alpha: .3)),
          ),
          child: child,
        ),
      );
}

