class HeadsetPainter extends CustomPainter {
  final Color a, b;
  HeadsetPainter(this.a, this.b);

  @override
  void paint(Canvas canvas, Size size) {
    final w = size.width, h = size.height;
    final strap = Paint()
      ..color = const Color(0xFF2A3042)
      ..style = PaintingStyle.stroke
      ..strokeWidth = h * .09
      ..strokeCap = StrokeCap.round;
    canvas.drawPath(
        Path()
          ..moveTo(w * .07, h * .46)
          ..quadraticBezierTo(w * .5, -h * .28, w * .93, h * .46),
        strap);
    final body = RRect.fromRectAndRadius(Rect.fromLTWH(w * .06, h * .2, w * .88, h * .6), Radius.circular(h * .26));
    canvas.drawRRect(
        body,
        Paint()
          ..shader = const LinearGradient(
            begin: Alignment.topCenter,
            end: Alignment.bottomCenter,
            colors: [Color(0xFF30364A), Color(0xFF151925)],
          ).createShader(body.outerRect));
    final visor = RRect.fromRectAndRadius(Rect.fromLTWH(w * .11, h * .28, w * .78, h * .44), Radius.circular(h * .19));
    canvas.drawRRect(visor, Paint()..shader = LinearGradient(colors: [a, b]).createShader(visor.outerRect));
    canvas.drawRRect(
        visor,
        Paint()
          ..shader = LinearGradient(
            begin: Alignment.topLeft,
            end: Alignment.bottomRight,
            colors: [Colors.white.withValues(alpha: .45), Colors.white.withValues(alpha: 0)],
            stops: const [0, .5],
          ).createShader(visor.outerRect));
    final dot = Paint()..color = const Color(0xCC0A0C13);
    for (final x in [.27, .5, .73]) {
      canvas.drawCircle(Offset(w * x, h * .5), h * .045, dot);
    }
  }

  @override
  bool shouldRepaint(HeadsetPainter o) => o.a != a || o.b != b;
}

class RingsPainter extends CustomPainter {
  final double v;
  final Color color;
  RingsPainter(this.v, this.color);

  @override
  void paint(Canvas canvas, Size size) {
    final ctr = size.center(Offset.zero);
    final maxR = size.shortestSide / 2;
    canvas.drawCircle(
        ctr,
        maxR * .6,
        Paint()
          ..shader = RadialGradient(colors: [color.withValues(alpha: .2), color.withValues(alpha: 0)])
              .createShader(Rect.fromCircle(center: ctr, radius: maxR * .6)));
    for (var i = 0; i < 3; i++) {
      final p = (v + i / 3) % 1.0;
      canvas.drawCircle(
          ctr,
          maxR * (.38 + p * .62),
          Paint()
            ..style = PaintingStyle.stroke
            ..strokeWidth = 1.4
            ..color = color.withValues(alpha: (1 - p) * .45));
    }
  }

  @override
  bool shouldRepaint(RingsPainter o) => o.v != v || o.color != color;
}

class ArcPainter extends CustomPainter {
  final double p;
  final List<Color> colors;
  final double stroke;
  ArcPainter(this.p, this.colors, this.stroke);

  @override
  void paint(Canvas canvas, Size size) {
    final rect = (Offset.zero & size).deflate(stroke / 2);
    canvas.drawArc(
        rect,
        0,
        math.pi * 2,
        false,
        Paint()
          ..style = PaintingStyle.stroke
          ..strokeWidth = stroke
          ..color = Colors.white.withValues(alpha: .07));
    if (p <= 0) return;
    final loop = colors.length > 1 ? [...colors, colors.first] : colors;
    final stops = colors.length > 1 ? [for (var i = 0; i < colors.length; i++) i / (colors.length - 1) * .9, 1.0] : null;
    canvas.drawArc(
        rect,
        -math.pi / 2,
        math.pi * 2 * cl(p, 0, 1),
        false,
        Paint()
          ..style = PaintingStyle.stroke
          ..strokeWidth = stroke
          ..strokeCap = StrokeCap.round
          ..shader = SweepGradient(colors: loop, stops: stops, transform: const GradientRotation(-math.pi / 2)).createShader(rect));
  }

  @override
  bool shouldRepaint(ArcPainter o) => o.p != p || o.colors != colors;
}

class DashPainter extends CustomPainter {
  final Color color;
  final double phase, radius;
  DashPainter(this.color, this.phase, this.radius);

  @override
  void paint(Canvas canvas, Size size) {
    final path = Path()..addRRect(RRect.fromRectAndRadius(Offset.zero & size, Radius.circular(radius)));
    final paint = Paint()
      ..color = color
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.6;
    for (final m in path.computeMetrics()) {
      final n = math.max(1, (m.length / 14).round());
      final period = m.length / n;
      final dash = period * 8 / 14;
      final shift = phase % period;
      for (var i = 0; i < n; i++) {
        final s = i * period + shift;
        final e = s + dash;
        if (e <= m.length) {
          canvas.drawPath(m.extractPath(s, e), paint);
        } else {
          canvas.drawPath(m.extractPath(s, m.length), paint);
          canvas.drawPath(m.extractPath(0, e - m.length), paint);
        }
      }
    }
  }

  @override
  bool shouldRepaint(DashPainter o) => o.phase != phase || o.color != color;
}

