    final close = kind == 3;
    return Hover(
      onTap: onTap,
      builder: (h) => Padding(
        padding: const EdgeInsets.symmetric(horizontal: 3),
        child: AnimatedContainer(
          duration: ms(220),
          curve: Curves.easeOutCubic,
          width: 36,
          height: 28,
          decoration: BoxDecoration(
            color: h ? (close ? const Color(0xFFE5484D).withValues(alpha: .7) : Colors.white.withValues(alpha: .09)) : Colors.white.withValues(alpha: 0),
            borderRadius: BorderRadius.circular(10),
          ),
