            const SizedBox(height: 24),
            FadeIn(
              delay: 120,
              child: Text('What should we call you?', style: t(30, w: FontWeight.w800, ls: -.8, display: true)),
            ),
            const SizedBox(height: 8),
            FadeIn(delay: 200, child: Text('Lightcat will greet you with it.', style: t(14.5, c: Pal.sub))),
            const SizedBox(height: 28),
