class _TermsScreenState extends State<TermsScreen> {
  bool agreed = false;
  String typed = '';
  final ctl = TextEditingController();

  @override
  void dispose() {
    ctl.dispose();
    super.dispose();
  }

  bool get confirmed => agreed && typed.trim().toUpperCase() == 'ACCEPT';

  void _setAgreed(bool v) => setState(() {
        agreed = v;
        if (!v) {
          typed = '';
          ctl.clear();
        }
      });

