class RevealScreen extends StatefulWidget {
  final DeviceInfo info;
  final VoidCallback onContinue;
  const RevealScreen({super.key, required this.info, required this.onContinue});
  @override
  State<RevealScreen> createState() => _RevealScreenState();
}

class _RevealScreenState extends State<RevealScreen> with SingleTickerProviderStateMixin {
  late final AnimationController c = AnimationController(vsync: this, duration: const Duration(milliseconds: 1900));

  @override
  void initState() {
    super.initState();
    if (Pal.reduceMotion.value) {
      c.value = 1;
    } else {
      Future.delayed(const Duration(milliseconds: 450), () {
        if (mounted) c.forward();
      });
    }
  }

  @override
  void dispose() {
    c.dispose();
    super.dispose();
  }

  Widget _in(double a, double b, Widget child, {double dy = 18, bool scale = false}) => AnimatedBuilder(
        animation: c,
        child: child,
        builder: (_, ch) {
          final v = Curves.easeOutCubic.transform(cl((c.value - a) / (b - a), 0, 1));
          final q = v > 0 && v < 1 ? FilterQuality.medium : null;
          return Opacity(
            opacity: v,
            child: Transform.translate(
              offset: snapOffset(context, Offset(0, (1 - v) * dy)),
              child: scale ? Transform.scale(scale: .82 + .18 * v, filterQuality: q, child: ch) : ch,
            ),
          );
        },
      );

  @override
  Widget build(BuildContext context) {
    final d = widget.info;
    return ClipRect(
      child: BackdropFilter(
        filter: ui.ImageFilter.blur(sigmaX: 16, sigmaY: 16),
        child: Container(
          decoration: BoxDecoration(
            gradient: RadialGradient(
              center: const Alignment(0, -.4),
              radius: 1.2,
              colors: [Pal.a.withValues(alpha: .16), Pal.bg.withValues(alpha: .78)],
            ),
          ),
          child: Center(
            child: SingleChildScrollView(
              padding: const EdgeInsets.only(top: 46, bottom: 24),
              child: Column(mainAxisSize: MainAxisSize.min, children: [
                _in(
                  0,
                  .42,
                  Container(
                    decoration: BoxDecoration(
                      borderRadius: BorderRadius.circular(80),
                      boxShadow: [BoxShadow(color: Pal.a.withValues(alpha: .22), blurRadius: 90, spreadRadius: 6)],
                    ),
                    child: SizedBox(
                        width: 260, height: 160, child: DeviceArt(model: d.model, width: 260, height: 160)),
                  ),
                  dy: 0,
                  scale: true,
                ),
                const SizedBox(height: 24),
                _in(
                  .22,
                  .56,
                  Row(mainAxisSize: MainAxisSize.min, children: [
                    const PulseDot(color: Pal.good, size: 7),
                    const SizedBox(width: 4),
                    Text('Connected', style: t(13.5, w: FontWeight.w600, c: Pal.good)),
                  ]),
                ),
                const SizedBox(height: 6),
                _in(
                  .26,
                  .62,
                  ShaderMask(
                    shaderCallback: (r) => LinearGradient(colors: [Colors.white, Pal.a]).createShader(r),
                    child: Text(d.name,
                        style: t(56, w: FontWeight.w800, ls: -1.8, c: Colors.white, display: true, h: 1.1)),
                  ),
                ),
                const SizedBox(height: 30),
                _in(
                  .42,
                  .82,
                  Row(mainAxisSize: MainAxisSize.min, children: [
                    BatteryRing(d: d, size: 150),
                    const SizedBox(width: 40),
                    Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min, children: [
                      InfoLine(Icons.bolt_rounded, 'Power', d.powerText, color: d.slow ? Pal.warn : null),
                      const SizedBox(height: 16),
                      InfoLine(Icons.sd_storage_rounded, 'Storage',
                          '${d.freeGb.toStringAsFixed(1)} GB free of ${d.totalGb.toStringAsFixed(0)} GB',
                          color: d.freeGb < 120 ? storageColor(d.freeGb) : null),
                      const SizedBox(height: 16),
                      InfoLine(d.wifi ? Icons.wifi_rounded : (d.slowUsb ? Icons.warning_amber_rounded : Icons.usb_rounded),
                          'Connection',
