                ),
              ]),
            ),
          ),
        ),
      ),
    );
  }
}

const _nav = <(IconData, String)>[
  (Icons.home_rounded, 'Home'),
  (Icons.download_rounded, 'Sideload'),
  (Icons.storefront_rounded, 'Store'),
  (Icons.video_library_rounded, 'Library'),
  (Icons.apps_rounded, 'Apps'),
  (Icons.folder_rounded, 'Files'),
  (Icons.tune_rounded, 'Device settings'),
  (Icons.cast_rounded, 'Cast'),
  (Icons.terminal_rounded, 'Console'),
  (Icons.settings_rounded, 'Settings'),
];

const needsHeadset = {1, 4, 5, 6, 7, 8};

class Shell extends StatefulWidget {
  const Shell({super.key});
  @override
  State<Shell> createState() => _ShellState();
}

class _ShellState extends State<Shell> {
  int idx = 0;
  final _visited = <int>{0};

  @override
  void initState() {
    super.initState();
    storeSearch.addListener(_onSearch);
    navTo.addListener(_onNav);
    HardwareKeyboard.instance.addHandler(_keys);
  }

  @override
  void dispose() {
    storeSearch.removeListener(_onSearch);
    navTo.removeListener(_onNav);
    HardwareKeyboard.instance.removeHandler(_keys);
    super.dispose();
  }

  bool _keys(KeyEvent e) {
    if (e is KeyUpEvent) return false;
    final typing = FocusManager.instance.primaryFocus?.context?.findAncestorWidgetOfExactType<EditableText>() != null;
    if (typing) return false;
    final k = e.logicalKey;
    final page = (context.size?.height ?? 700) * .8;
    if (k == LogicalKeyboardKey.arrowDown) return _SmoothScrollState.keyScroll(90);
    if (k == LogicalKeyboardKey.arrowUp) return _SmoothScrollState.keyScroll(-90);
    if (k == LogicalKeyboardKey.pageDown) return _SmoothScrollState.keyScroll(page);
    if (k == LogicalKeyboardKey.pageUp) return _SmoothScrollState.keyScroll(-page);
    if (k == LogicalKeyboardKey.end) return _SmoothScrollState.keyScroll(0, toEnd: true);
    if (k == LogicalKeyboardKey.home) return _SmoothScrollState.keyScroll(0, toStart: true);
    return false;
  }

  void _onSearch() {
    if (storeSearch.value != null) _go(2);
  }

  bool dropping = false;

  Future<void> _dropAll(List<String> paths) async {
    if (paths.isEmpty) return;
    if (!await SideloadNotice.show(context) || !mounted) return;
    _go(1);
    InstallQueue.i.add(paths, (m) => toast(context, m, icon: Icons.info_rounded, color: Pal.warn));
  }

  void _onNav() {
    final i = navTo.value;
    if (i == null) return;
    navTo.value = null;
    _go(i);
  }

  void _go(int i) {
    if (i == idx) return;
    setState(() {
      idx = i;
      _visited.add(i);
    });
    if (i == 1) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted && idx == 1) SideloadNotice.show(context);
      });
    }
  }

  Widget _page(int i) => switch (i) {
        0 => HomePage(go: _go),
        1 => const SideloadPage(),
        2 => const StorePage(),
        3 => const LibraryPage(),
        4 => const AppsPage(),
        5 => const FilesPage(),
        6 => const TweaksPage(),
        7 => const CastPage(),
        8 => const ConsolePage(),
        _ => const SettingsPage(),
      };

  @override
  Widget build(BuildContext context) {
    return DropTarget(
      onDragEntered: (_) {
        if (idx == 1 || idx == 5) setState(() => dropping = true);
      },
      onDragExited: (_) => setState(() => dropping = false),
      onDragDone: (d) {
        setState(() => dropping = false);
        final paths = d.files.map((f) => f.path).toList();
        if (idx == 1) _dropAll(paths);
        if (idx == 5) filesDrop.value = paths;
      },
      child: Stack(fit: StackFit.expand, children: [
        Row(children: [
      Sidebar(idx: idx, onTap: _go),
      Expanded(
        child: Container(
          margin: const EdgeInsets.fromLTRB(0, 4, 12, 12),
          decoration: BoxDecoration(
            color: Pal.panel.withValues(alpha: .94),
            borderRadius: BorderRadius.circular(24),
            border: Border.all(color: Pal.stroke),
          ),
          clipBehavior: Clip.antiAlias,
          child: Stack(fit: StackFit.expand, children: [
            for (final i in _visited)
              PageLayer(
                key: ValueKey(i),
                active: i == idx,
                child: !needsHeadset.contains(i)
                    ? _page(i)
                    : ListenableBuilder(
                        listenable: Device.i,
                        builder: (_, __) {
                          final d = Device.i.info;
                          return AnimatedSwitcher(
                            duration: ms(380),
                            child: d == null
                                ? const Disconnected(key: ValueKey('off'))
                                : KeyedSubtree(key: ValueKey('on${d.id}'), child: _page(i)),
                          );
                        },
                      ),
              ),
          ]),
        ),
      ),
    ]),
        Positioned.fill(
          child: IgnorePointer(
            child: idx == 5
                ? DropFog(
                    on: dropping,
                    icon: Icons.upload_rounded,
                    title: 'Drop to copy to your Quest',
                    sub: 'Any file or folder goes into ${_FilesPageState.cwd == '/sdcard' ? 'internal storage' : _FilesPageState.cwd.split('/').last}',
                  )
                : DropFog(on: dropping),
          ),
        ),
      ]),
    );
  }
}

class DropFog extends StatelessWidget {
  final bool on;
  final IconData icon;
  final String title, sub;
  const DropFog({
    super.key,
    required this.on,
    this.icon = Icons.download_rounded,
    this.title = 'Drop to install on your Quest',
    this.sub = 'APK, OBB or a whole game folder',
  });

  @override
  Widget build(BuildContext context) => TweenAnimationBuilder<double>(
        tween: Tween(end: on ? 1.0 : 0.0),
        duration: ms(320),
        curve: Curves.easeOutCubic,
        builder: (context, v, _) {
          if (v < .001) return const SizedBox.shrink();
          return Stack(fit: StackFit.expand, children: [
            BackdropFilter(
              filter: ui.ImageFilter.blur(sigmaX: 14 * v, sigmaY: 14 * v),
              child: ColoredBox(color: Colors.black.withValues(alpha: .55 * v)),
            ),
            Center(
              child: Opacity(
                opacity: v,
                child: Transform.translate(
                  offset: snapOffset(context, Offset(0, (1 - v) * 16)),
                  child: Column(mainAxisSize: MainAxisSize.min, children: [
                    Container(
                      width: 84,
                      height: 84,
                      decoration: BoxDecoration(
                        gradient: Pal.grad,
                        borderRadius: BorderRadius.circular(26),
                        boxShadow: [BoxShadow(color: Pal.a.withValues(alpha: .45), blurRadius: 40)],
                      ),
                      child: Icon(icon, color: Pal.ink, size: 40),
                    ),
                    const SizedBox(height: 22),
                    Text(title, style: t(24, w: FontWeight.w800, display: true)),
                    const SizedBox(height: 8),
                    Text(sub, style: t(14, c: Pal.sub)),
                  ]),
                ),
              ),
            ),
          ]);
        },
      );
}

class PageLayer extends StatefulWidget {
  final bool active;
  final Widget child;
  const PageLayer({super.key, required this.active, required this.child});
  @override
  State<PageLayer> createState() => _PageLayerState();
}

class _PageLayerState extends State<PageLayer> with SingleTickerProviderStateMixin {
  late final AnimationController c = AnimationController(vsync: this, duration: ms(380));
  late final CurvedAnimation a = CurvedAnimation(parent: c, curve: Curves.easeOutCubic);

  @override
  void initState() {
    super.initState();
    if (widget.active) c.forward();
  }

  @override
  void didUpdateWidget(PageLayer old) {
    super.didUpdateWidget(old);
    if (widget.active && !old.active) {
      c.duration = ms(380);
      c.forward(from: 0);
    }
  }

  @override
  void dispose() {
    a.dispose();
    c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => Offstage(
        offstage: !widget.active,
        child: TickerMode(
          enabled: widget.active,
          child: FadeTransition(
            opacity: a,
            child: RepaintBoundary(child: widget.child),
          ),
        ),
      );
}

