const _greyMatrix = ColorFilter.matrix(<double>[
  0.2126, 0.7152, 0.0722, 0, 0, //
  0.2126, 0.7152, 0.0722, 0, 0, //
  0.2126, 0.7152, 0.0722, 0, 0, //
  0, 0, 0, 1, 0,
]);

Widget greyed(Widget w, bool grey, {double fade = .45}) => grey
    ? Opacity(opacity: fade, child: ColorFiltered(colorFilter: _greyMatrix, child: w))
    : w;

String usbText(DeviceInfo d) {
  if (d.wifi) return 'Connected wirelessly';
  final base = 'Connected over ${d.usb ?? 'USB'}';
  return switch (d.usbLevel) {
    2 => '$base · very weak cable',
    1 => '$base · weak cable',
    _ => base,
  };
}

Color usbColor(DeviceInfo d) => switch (d.usbLevel) { 2 => Pal.bad, 1 => Pal.warn, _ => Pal.good };

class SerialRow extends StatefulWidget {
  final String serial;
  const SerialRow({super.key, required this.serial});
  @override
  State<SerialRow> createState() => _SerialRowState();
}

class _SerialRowState extends State<SerialRow> {
  bool shown = false;
  Timer? _t;

  @override
  void initState() {
    super.initState();
    appVisible.addListener(_vis);
  }

  void _vis() {
    if (!appVisible.value && shown) setState(() => shown = false);
  }

  void _toggle() {
    _t?.cancel();
    setState(() => shown = !shown);
    if (shown) {
      _t = Timer(const Duration(seconds: 30), () {
        if (mounted) setState(() => shown = false);
      });
    }
  }

  @override
  void dispose() {
    appVisible.removeListener(_vis);
    _t?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => Row(children: [
        Text('Serial', style: t(12.5, c: Pal.sub)),
        const SizedBox(width: 10),
        shown
            ? Text(widget.serial, style: t(12.5, w: FontWeight.w600, f: 'Consolas'))
            : Text('*************', style: t(12.5, w: FontWeight.w600, c: Pal.dim, f: 'Consolas')),
        const SizedBox(width: 10),
        Hover(
          onTap: _toggle,
          builder: (h) => AnimatedContainer(
            duration: ms(160),
            padding: const EdgeInsets.symmetric(horizontal: 9, vertical: 4),
            decoration: BoxDecoration(
              color: Colors.white.withValues(alpha: h ? .12 : .06),
              borderRadius: BorderRadius.circular(8),
            ),
            child: Row(mainAxisSize: MainAxisSize.min, children: [
              Icon(shown ? Icons.visibility_off_rounded : Icons.visibility_rounded, size: 13, color: Pal.sub),
              const SizedBox(width: 5),
              Text(shown ? 'Hide' : 'Show', style: t(11.5, w: FontWeight.w600, c: Pal.sub)),
            ]),
          ),
        ),
      ]);
}

class PadsRow extends StatelessWidget {
  final String model;
  final int? left, right;
  final bool leftOn, rightOn, rechargeable, offline;
  const PadsRow(
      {super.key,
      required this.model,
      this.left,
      this.right,
      this.leftOn = true,
      this.rightOn = true,
      this.rechargeable = false,
      this.offline = false});

  Widget _pad(String label, int? v, bool isLeft, bool on) {
    final live = on && !offline;
    final val = v ?? 0;
    final col = live ? batteryColor(val) : Pal.dim;
    return Row(mainAxisSize: MainAxisSize.min, children: [
      AnimatedSwitcher(
        duration: ms(400),
        child: KeyedSubtree(
          key: ValueKey(live),
          child: greyed(DeviceArt(model: controllerKey(model, isLeft), width: 46, height: 62), !live),
        ),
      ),
      const SizedBox(width: 12),
      Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min, children: [
        Text(label, style: t(12, c: Pal.sub)),
        const SizedBox(height: 2),
        AnimatedDefaultTextStyle(
          duration: ms(500),
          style: t(20, w: FontWeight.w800, display: true, c: col),
          child: Text(offline ? '—' : '$val%'),
        ),
        const SizedBox(height: 6),
        SizedBox(
            width: 110,
            child: Bar(value: live ? val / 100 : 0, h: 5, colors: live ? batteryGrad(val) : [Pal.dim, Pal.dim])),
        if (!live && !offline) ...[
          const SizedBox(height: 4),
          Text('Not connected', style: t(11, c: Pal.dim)),
        ],
      ]),
    ]);
  }

  @override
  Widget build(BuildContext context) {
    final low = !offline && ((leftOn && (left ?? 100) <= 20) || (rightOn && (right ?? 100) <= 20));
    return Row(mainAxisSize: MainAxisSize.min, children: [
      _pad('Left controller', left, true, leftOn),
      const SizedBox(width: 40),
      _pad('Right controller', right, false, rightOn),
      if (low) ...[
        const SizedBox(width: 30),
        Tag(rechargeable ? 'Charge the controllers' : 'Change the controller battery', c: Pal.bad),
      ],
    ]);
  }
}

