class DevicesList extends StatelessWidget {
  const DevicesList({super.key});

  @override
  Widget build(BuildContext context) => ListenableBuilder(
        listenable: Listenable.merge([Devices.i, Device.i]),
        builder: (ctx, _) {
          final all = Devices.i.all;
          if (all.isEmpty) return const SizedBox.shrink();
          final d = Device.i;
          final keys = all.keys.toList();
          final ids = [...keys.where(d.isLive), ...keys.where((k) => !d.isLive(k))];
          return Padding(
            padding: const EdgeInsets.only(bottom: 28),
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Text('Your devices', style: t(17, w: FontWeight.w700, display: true)),
              const SizedBox(height: 14),
              Wrap(spacing: 14, runSpacing: 14, children: [
                for (var k = 0; k < ids.length; k++)
                  FadeIn(
                    key: ValueKey(ids[k]),
                    delay: k * 50,
                    child: _card(ctx, ids[k], Map<String, dynamic>.from(all[ids[k]] as Map), d.isLive(ids[k]), ids[k] == d.selectedId),
                  ),
              ]),
            ]),
          );
        },
      );

  Widget _card(BuildContext ctx, String id, Map<String, dynamic> m, bool live, bool sel) {
    DeviceInfo? inf;
    for (final x in Device.i.live.values) {
      if (x.id == id) inf = x;
    }
    final bat = inf?.battery ?? (m['battery'] as num?)?.toInt() ?? 0;
    final model = '${m['model'] ?? ''}';
    return Hover(
      onTap: () async {
        final dv = Device.i;
        if (live || !kDemo) {
          dv.select(id);
        } else {
          await dv.plugDemo(id);
          if (ctx.mounted) toast(ctx, '${m['name']} connected (demo)', icon: Icons.usb_rounded);
        }
      },
      builder: (h) => AnimatedContainer(
        duration: ms(200),
        curve: Curves.easeOutCubic,
        width: 300,
        padding: const EdgeInsets.all(16),
        decoration: BoxDecoration(
          color: h ? Pal.card2 : Pal.card,
          borderRadius: BorderRadius.circular(18),
          border: Border.all(
              color: sel ? Pal.a.withValues(alpha: .7) : (live ? Pal.good.withValues(alpha: .35) : Pal.stroke),
              width: sel ? 1.6 : 1),
        ),
        child: Stack(clipBehavior: Clip.none, children: [
          Row(children: [
          Stack(clipBehavior: Clip.none, children: [
          AnimatedOpacity(
            opacity: live ? 1 : .55,
            duration: ms(400),
            child: ColorFiltered(
              colorFilter: live
                  ? const ColorFilter.mode(Colors.transparent, BlendMode.dst)
                  : const ColorFilter.matrix(<double>[
                      .33, .33, .33, 0, 0, //
                      .33, .33, .33, 0, 0,
                      .33, .33, .33, 0, 0,
                      0, 0, 0, 1, 0,
                    ]),
              child: DeviceArt(model: model, width: 84, height: 56),
            ),
          ),
          ]),
          const SizedBox(width: 14),
          Expanded(
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Text('${m['name']}', style: t(14.5, w: FontWeight.w700), overflow: TextOverflow.ellipsis),
              const SizedBox(height: 3),
              Row(children: [
                Container(
                  width: 7,
                  height: 7,
                  decoration: BoxDecoration(shape: BoxShape.circle, color: live ? Pal.good : Pal.dim),
                ),
                const SizedBox(width: 6),
                Flexible(
                  child: Text(
                      live
                          ? (sel ? 'Connected · showing' : 'Connected · tap to show')
                          : (kDemo ? 'Not connected · tap to connect' : 'Not connected, seen ${agoText((m['seen'] as num?)?.toInt() ?? 0)}'),
                      style: t(12, c: live ? Pal.good : Pal.sub),
                      overflow: TextOverflow.ellipsis),
                ),
              ]),
              const SizedBox(height: 6),
              Row(children: [
                if (live && (inf?.charging ?? false)) ...[
                  Icon(Icons.bolt_rounded, size: 14, color: batteryColor(bat)),
                  const SizedBox(width: 2),
                ],
                Text(live ? 'Battery $bat%' : 'Last battery $bat%',
                    style: t(12, w: FontWeight.w600, c: batteryColor(bat))),
              ]),
            ]),
          ),
          if (live ? kDemo : true)
            IgnorePointer(
              ignoring: !h,
              child: AnimatedOpacity(
                opacity: h ? 1 : 0,
                duration: ms(220),
                child: live
                    ? IconBtn(
                        icon: Icons.power_off_rounded,
                        tip: 'Unplug (demo)',
                        danger: true,
                        onTap: () => Device.i.unplugDemo(id),
                      )
                    : IconBtn(
                        icon: Icons.delete_rounded,
                        tip: 'Remove device',
                        danger: true,
                        onTap: () async {
                          if (await confirm(ctx, 'Remove ${m['name']}?',
                              'It disappears from this list until you plug it in again.',
                              action: 'Remove', danger: true)) {
                            await Devices.i.forget(id);
                          }
                        },
                      ),
              ),
            ),
        ]),
          Positioned(
            left: -8,
            top: -7,
            child: IgnorePointer(child: MetaMark(on: live && !(inf?.asleep ?? false), h: 14)),
          ),
        ]),
      ),
    );
  }
}

