class SideloadPage extends StatefulWidget {
  const SideloadPage({super.key});
  @override
  State<SideloadPage> createState() => _SideloadPageState();
}

class _SideloadPageState extends State<SideloadPage> with SingleTickerProviderStateMixin {
  bool drag = false, hover = false;
  late final AnimationController dash = AnimationController(vsync: this, duration: const Duration(milliseconds: 900));

  @override
  void dispose() {
    dash.dispose();
    super.dispose();
  }

  void _anim() {
    if ((drag || hover) && !Pal.reduceMotion.value) {
      if (!dash.isAnimating) dash.repeat();
    } else {
      dash.stop();
    }
  }

  Future<void> _add(List<String> paths) async {
    if (paths.isEmpty) return;
    if (!await SideloadNotice.show(context) || !mounted) return;
    InstallQueue.i.add(paths, (m) => toast(context, m, icon: Icons.info_rounded, color: Pal.warn));
  }

  @override
  Widget build(BuildContext context) {
    final lit = drag || hover;
    return PageFrame(
      title: 'Sideload',
      subtitle: 'Put any app on your Quest. No store approval, no restrictions.',
      actions: [
        Btn(label: 'Choose folder', icon: Icons.folder_open_rounded, onTap: () async => _add(await Pick.folder())),
        const SizedBox(width: 10),
        Btn(label: 'Browse files', icon: Icons.add_rounded, primary: true, onTap: () async => _add(await Pick.files())),
      ],
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        MouseRegion(
            cursor: SystemMouseCursors.click,
            onEnter: (_) {
              setState(() => hover = true);
              _anim();
            },
            onExit: (_) {
              setState(() => hover = false);
              _anim();
            },
            child: GestureDetector(
              onTap: () async => _add(await Pick.files()),
              child: AnimatedContainer(
                duration: ms(320),
                curve: Curves.easeOutCubic,
                height: 260,
                decoration: BoxDecoration(
                  borderRadius: BorderRadius.circular(24),
                  gradient: RadialGradient(
                    radius: 1.1,
                    colors: [Pal.a.withValues(alpha: drag ? .18 : (hover ? .09 : .045)), Pal.a.withValues(alpha: 0)],
                  ),
                ),
                child: TweenAnimationBuilder<double>(
                  tween: Tween(end: lit ? 1 : 0),
                  duration: ms(520),
                  curve: Curves.easeOutCubic,
                  builder: (_, g, child) => AnimatedBuilder(
                    animation: dash,
                    builder: (_, child) => CustomPaint(
                      painter: DashPainter(
                          Color.lerp(Colors.white.withValues(alpha: .14), Pal.a.withValues(alpha: .85), g)!,
                          dash.value * 14,
                          24),
                      child: child,
                    ),
                    child: child,
                  ),
                  child: Center(
                    child: Column(mainAxisSize: MainAxisSize.min, children: [
                      AnimatedScale(
                        scale: drag ? 1.14 : (hover ? 1.05 : 1),
                        duration: ms(320),
                        curve: Curves.easeOutBack,
                        child: Container(
                          width: 66,
                          height: 66,
                          decoration: BoxDecoration(
                            gradient: Pal.grad,
                            borderRadius: BorderRadius.circular(20),
                            boxShadow: [BoxShadow(color: Pal.a.withValues(alpha: lit ? .45 : .25), blurRadius: 30)],
                          ),
                          child: const Icon(Icons.download_rounded, color: Pal.ink, size: 32),
                        ),
                      ),
                      const SizedBox(height: 20),
                      AnimatedSwitcher(
                        duration: ms(220),
                        child: Text(drag ? 'Let go to install' : 'Download your APK apps without restrictions',
                            key: ValueKey(drag), style: t(22, w: FontWeight.w700, display: true, ls: -.3)),
                      ),
                      const SizedBox(height: 8),
                      Text('Drop APK files, OBB data or a whole game folder here, or click to browse.',
                          style: t(13.5, c: Pal.sub)),
                      const SizedBox(height: 16),
                      const Row(mainAxisSize: MainAxisSize.min, children: [
                        Tag('APK'),
                        SizedBox(width: 8),
                        Tag('OBB'),
                        SizedBox(width: 8),
                        Tag('Folder'),
                      ]),
                    ]),
                  ),
                ),
              ),
            ),
          ),
        const SizedBox(height: 30),
        ListenableBuilder(
          listenable: InstallQueue.i,
          builder: (_, __) {
            final jobs = InstallQueue.i.jobs;
            return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Row(children: [
                Text('Install queue', style: t(17, w: FontWeight.w700, display: true)),
                const SizedBox(width: 10),
                if (jobs.isNotEmpty) Tag('${jobs.length}'),
                const Spacer(),
                if (jobs.any((j) => j.state == 'done' || j.state == 'failed'))
                  Btn(label: 'Clear finished', icon: Icons.done_all_rounded, onTap: InstallQueue.i.clearFinished),
              ]),
              const SizedBox(height: 14),
              AnimatedSize(
                duration: ms(320),
                curve: Curves.easeOutCubic,
                alignment: Alignment.topCenter,
                child: jobs.isEmpty
                    ? Panel(
                        pad: const EdgeInsets.all(28),
                        child: Row(children: [
                          const Icon(Icons.inbox_rounded, color: Pal.dim, size: 26),
                          const SizedBox(width: 16),
                          Expanded(
                            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                              Text('Nothing installing yet', style: t(14.5, w: FontWeight.w600)),
                              const SizedBox(height: 3),
                              Text(
                                  'Anything you drop shows up here with live progress. Installs keep running while you browse other pages.',
                                  style: t(12.5, c: Pal.sub)),
                            ]),
                          ),
                        ]),
                      )
                    : Column(children: [for (final j in jobs) JobTile(key: ObjectKey(j), j: j)]),
              ),
            ]);
          },
        ),
      ]),
    );
  }
}

class JobTile extends StatelessWidget {
  final Job j;
  const JobTile({super.key, required this.j});

  @override
  Widget build(BuildContext context) {
    final icon = switch (j.kind) {
      'APK' => Icons.android_rounded,
      'OBB' => Icons.inventory_2_rounded,
      _ => Icons.folder_rounded,
    };
    final Widget status = switch (j.state) {
      'working' => SizedBox(
          width: 160,
          child: j.progress == null
              ? ClipRRect(
                  borderRadius: BorderRadius.circular(4),
                  child: LinearProgressIndicator(
                      minHeight: 5, color: Pal.a, backgroundColor: Colors.white.withValues(alpha: .07)),
                )
              : TweenAnimationBuilder<double>(
                  tween: Tween(end: j.progress!),
                  duration: ms(450),
                  curve: Curves.easeOutCubic,
                  builder: (_, p, __) => Row(children: [
                    Expanded(
                      child: ClipRRect(
                        borderRadius: BorderRadius.circular(4),
                        child: LinearProgressIndicator(
                            value: p, minHeight: 5, color: Pal.a, backgroundColor: Colors.white.withValues(alpha: .07)),
                      ),
                    ),
                    const SizedBox(width: 10),
                    SizedBox(
                      width: 40,
                      child: Text('${(p * 100).round()}%',
                          textAlign: TextAlign.right,
                          style: t(12.5, w: FontWeight.w700, c: Pal.text)
                              .copyWith(fontFeatures: const [ui.FontFeature.tabularFigures()])),
                    ),
                  ]),
                ),
        ),
      'done' => const Icon(Icons.check_circle_rounded, color: Pal.good, size: 22),
      'failed' => const Icon(Icons.error_rounded, color: Pal.bad, size: 22),
      _ => Text('Queued', style: t(12, c: Pal.dim)),
    };
    return TweenAnimationBuilder<double>(
      tween: Tween(begin: 0, end: 1),
      duration: ms(420),
      curve: Curves.easeOutCubic,
      builder: (_, v, child) =>
          Opacity(opacity: v, child: child),
      child: Padding(
        padding: const EdgeInsets.only(bottom: 10),
        child: Panel(
          pad: const EdgeInsets.symmetric(horizontal: 18, vertical: 14),
          r: 16,
          border: j.state == 'failed' ? Pal.bad.withValues(alpha: .25) : null,
          child: Row(children: [
            Container(
              width: 40,
              height: 40,
              decoration:
                  BoxDecoration(color: Pal.a.withValues(alpha: .12), borderRadius: BorderRadius.circular(12)),
              child: Icon(icon, color: Pal.a, size: 20),
            ),
            const SizedBox(width: 14),
            Expanded(
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text(j.name, style: t(14, w: FontWeight.w600), overflow: TextOverflow.ellipsis),
                const SizedBox(height: 3),
                AnimatedSwitcher(
                  duration: ms(250),
                  child: Text(j.note,
                      key: ValueKey(j.note),
                      style: t(12.5, c: j.state == 'failed' ? Pal.bad : Pal.sub),
                      maxLines: 2,
                      overflow: TextOverflow.ellipsis),
                ),
              ]),
            ),
            const SizedBox(width: 14),
            Tag(j.kind, c: Pal.sub),
            const SizedBox(width: 16),
            AnimatedSwitcher(
              duration: ms(300),
              transitionBuilder: (c, a) => ScaleTransition(scale: a, child: FadeTransition(opacity: a, child: c)),
              child: KeyedSubtree(key: ValueKey(j.state), child: status),
            ),
          ]),
        ),
      ),
    );
  }
}

