double steamScore(SteamGame g) {
  if (g.totalReviews <= 0 || g.positivePct < 0) return -1;
  final n = g.totalReviews.toDouble();
  final p = g.positivePct / 100;
  const z = 1.96;
  return (p + z * z / (2 * n) - z * math.sqrt((p * (1 - p) + z * z / (4 * n)) / n)) / (1 + z * z / n);
}

class SteamReview {
  final bool up;
  final String text, id;
  final double hours;
  final int helpful, ts;
  SteamReview(this.up, this.text, this.hours, this.helpful, this.ts, {this.id = ''});
}

class ReviewPage {
  final List<SteamReview> list;
  final String? next;
  final int raw;
  ReviewPage(this.list, this.next, this.raw);
}

class SteamGame {
  final int id;
  String name;
  String? img;
  String? price;
  String? oldPrice;
  int priceCents = -1;
  int discount = 0;
  bool free = false;
  String? reviewDesc;
  int positivePct = -1;
  int totalReviews = 0;

  bool detailsLoaded = false;
  String short = '';
  String about = '';
  List<(String, String)> shots = [];
  List<(String, String)> reqMin = [], reqRec = [];
  List<SteamReview>? reviews;
  String release = '';
  bool comingSoon = false;
  List<String> devs = [], pubs = [], genres = [], platforms = [];
  bool vr = true;

  SteamGame(this.id, this.name);

  String get header => img ?? 'https://cdn.cloudflare.steamstatic.com/steam/apps/$id/header.jpg';
  String get hero => img != null && img!.contains('/header.jpg')
      ? img!.replaceAll('/header.jpg', '/library_hero.jpg')
      : 'https://cdn.cloudflare.steamstatic.com/steam/apps/$id/library_hero.jpg';
  String get url => 'https://store.steampowered.com/app/$id';
  String get priceLabel => free ? 'Free' : (price ?? (comingSoon ? 'Soon' : '—'));
}

String fmtCount(int n) {
  if (n >= 1000000) return '${(n / 1000000).toStringAsFixed(1)}M';
  if (n >= 1000) return '${(n / 1000).toStringAsFixed(1)}K';
  return '$n';
}

Color reviewColor(String? d) {
  if (d == null) return Pal.sub;
  final s = d.toLowerCase();
  if (s.contains('negative')) return s.contains('mostly') ? const Color(0xFFD08A4C) : const Color(0xFFE0614A);
  if (s.contains('mixed')) return const Color(0xFFC9A86A);
  if (s.contains('positive')) return Pal.steamBlue;
  return Pal.sub;
}

String _unesc(String s) => s
    .replaceAll('&lt;', '<')
    .replaceAll('&gt;', '>')
    .replaceAll('&quot;', '"')
    .replaceAll('&#39;', "'")
    .replaceAll('&amp;', '&');

class SteamStore extends ChangeNotifier {
  static final SteamStore i = SteamStore._();
  SteamStore._();

  static const sortNames = ['Most popular', 'Top rated', 'New releases', 'Name', 'Lowest price', 'Highest price'];

  final cache = <int, SteamGame>{};
  final top = <SteamGame>[];
  List<SteamGame>? results;
  String term = '';
  int sort = 0;
  bool loading = false, failed = false, searching = false;
  int _q = 0;

  final fresh = <SteamGame>[];
  DateTime? _freshAt;
  Timer? _freshTimer;

  static DateTime? _released(String text) {
    const months = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'];
    final s = text.trim();
    final a = RegExp(r'^(\d{1,2})\s+([A-Za-z]{3})\w*,?\s+(\d{4})$').firstMatch(s);
    final b = RegExp(r'^([A-Za-z]{3})\w*\s+(\d{1,2}),?\s+(\d{4})$').firstMatch(s);
    int day, month, year;
    if (a != null) {
      day = int.parse(a.group(1)!);
      month = months.indexOf(a.group(2)!.toLowerCase()) + 1;
      year = int.parse(a.group(3)!);
    } else if (b != null) {
      month = months.indexOf(b.group(1)!.toLowerCase()) + 1;
      day = int.parse(b.group(2)!);
      year = int.parse(b.group(3)!);
    } else {
      return null;
    }
    return month < 1 ? null : DateTime(year, month, day);
  }

  Future<void> loadFresh() async {
    _freshTimer ??= Timer.periodic(const Duration(hours: 2), (_) => loadFresh());
    final at = _freshAt;
    if (at != null && DateTime.now().difference(at) < const Duration(minutes: 30)) return;
    _freshAt = DateTime.now();
    final list = await _fetch(0, 100, '', 'Released_DESC');
    if (list == null) {
      _freshAt = null;
      return;
    }
    final now = DateTime.now();
    final out = <SteamGame>[];
    for (final g in list) {
      final d = _released(g.release);
      if (d == null || d.isAfter(now) || now.difference(d).inDays > 90) continue;
      if (g.totalReviews >= 20 && g.positivePct < 50) continue;
      out.add(g);
    }
    fresh
      ..clear()
      ..addAll(out.take(60));
    final seen = Prefs.data['freshSeen'];
    if (seen is List) {
      final added = fresh.where((g) => !seen.contains(g.id)).toList();
      if (added.isNotEmpty) {
        Notes.i.push(added.length == 1 ? 'New VR game on Steam' : '${added.length} new VR games on Steam',
            added.take(2).map((g) => g.name).join(', ') + (added.length > 2 ? ' and more' : ''),
            icon: Icons.sports_esports_rounded, color: Pal.good);
      }
    }
    final all = <int>{...(seen is List ? seen.whereType<num>().map((e) => e.toInt()) : const <int>[]), ...fresh.map((g) => g.id)}.toList();
    Prefs.set('freshSeen', all.length > 80 ? all.sublist(all.length - 80) : all);
    _notify();
  }

  SteamGame game(int id, String name) => cache.putIfAbsent(id, () => SteamGame(id, name));

  void _notify() => scheduleMicrotask(notifyListeners);

  List<SteamGame> get items {
    if (sort == 2 && results == null) return [...fresh];
    final x = [...(results ?? top)];
    switch (sort) {
      case 1:
        x.sort((a, b) => steamScore(b).compareTo(steamScore(a)));
      case 2:
        DateTime day(SteamGame g) => _released(g.release) ?? DateTime(1970);
        x.sort((a, b) => day(b).compareTo(day(a)));
      case 3:
        x.sort((a, b) => a.name.toLowerCase().compareTo(b.name.toLowerCase()));
      case 4:
      case 5:
        int p(SteamGame g) => g.free ? 0 : (g.priceCents < 0 ? 1 << 30 : g.priceCents);
        x.sort((a, b) => sort == 4 ? p(a).compareTo(p(b)) : p(b).compareTo(p(a)));
      default:
        x.sort((a, b) => b.totalReviews.compareTo(a.totalReviews));
    }
    return x;
  }

  Future<void> start() async {
    loadFresh();
    if (top.isNotEmpty || loading) return;
    final saved = Prefs.data['steamTop'];
    if (saved is List && saved.isNotEmpty) {
      for (final m in saved) {
        if (m is Map) top.add(_unpack(m));
      }
      _notify();
      await _loadTop(quiet: true);
      return;
    }
    await _loadTop();
  }

  static Map<String, dynamic> _pack(SteamGame g) => {
        'id': g.id,
        'n': g.name,
        'p': g.price,
        'op': g.oldPrice,
        'pc': g.priceCents,
        'd': g.discount,
        'f': g.free,
        'rd': g.reviewDesc,
        'pp': g.positivePct,
        'tr': g.totalReviews,
        'rel': g.release,
      };

  SteamGame _unpack(Map m) {
    final g = game((m['id'] as num).toInt(), '${m['n'] ?? ''}');
    g.price = m['p'] as String?;
    g.oldPrice = m['op'] as String?;
    g.priceCents = (m['pc'] as num?)?.toInt() ?? -1;
    g.discount = (m['d'] as num?)?.toInt() ?? 0;
    g.free = m['f'] == true;
    g.reviewDesc = m['rd'] as String?;
    g.positivePct = (m['pp'] as num?)?.toInt() ?? -1;
    g.totalReviews = (m['tr'] as num?)?.toInt() ?? 0;
    g.release = '${m['rel'] ?? ''}';
    return g;
  }

  Future<void> retry() async {
    top.clear();
    await _loadTop();
  }

  Future<void> _loadTop({bool quiet = false}) async {
    loading = !quiet;
    failed = false;
    _notify();
    final pages = <List<SteamGame>?>[];
    pages.addAll(await Future.wait([_fetch(0, 100, '', '_ASC'), _fetch(100, 100, '', '_ASC')]));
    pages.addAll(await Future.wait([_fetch(200, 100, '', '_ASC'), _fetch(0, 100, '', 'Reviews_DESC')]));
    final seen = <int>{};
    final all = <SteamGame>[];
    for (final p in pages) {
      for (final g in p ?? const <SteamGame>[]) {
        if (seen.add(g.id)) all.add(g);
      }
    }
    if (all.isEmpty) {
      if (top.isEmpty) await _fallback();
    } else {
      all.retainWhere((g) => g.totalReviews >= 1500 && g.positivePct >= 70);
      all.sort((a, b) => b.totalReviews.compareTo(a.totalReviews));
      top
        ..clear()
        ..addAll(all.take(100));
      Prefs.set('steamTop', [for (final g in top) _pack(g)]);
    }
    loading = false;
    failed = top.isEmpty;
    _notify();
  }

  List<SteamGame> local(String q) {
    final n = q.toLowerCase().trim();
    if (n.isEmpty) return [];
    final hits = top.where((g) => g.name.toLowerCase().contains(n)).toList();
    hits.sort((a, b) {
      final sa = a.name.toLowerCase().startsWith(n) ? 0 : 1;
      final sb = b.name.toLowerCase().startsWith(n) ? 0 : 1;
      return sa != sb ? sa - sb : b.totalReviews.compareTo(a.totalReviews);
    });
    return hits;
  }

  Future<void> search(String q) async {
    term = q.trim();
    final my = ++_q;
    if (term.isEmpty) {
      results = null;
      searching = false;
      _notify();
      return;
    }
    results = local(term);
    searching = true;
    _notify();
    final remote = await _fetch(0, 50, term, '_ASC');
    if (my != _q) return;
    searching = false;
    if (remote != null) {
      final seen = results!.map((g) => g.id).toSet();
      for (final g in remote) {
        if (g.totalReviews >= 100 && seen.add(g.id)) results!.add(g);
      }
    }
    _notify();
  }

  Future<List<SteamGame>> suggest(String q) async {
    final loc = local(q);
    if (loc.length >= 6) return loc.take(6).toList();
    final r = await _fetch(0, 15, q, '_ASC') ?? const <SteamGame>[];
    final seen = loc.map((g) => g.id).toSet();
    return [...loc, ...r.where((g) => g.totalReviews >= 100 && seen.add(g.id))].take(6).toList();
  }

  void setSort(int s) {
    sort = s;
    if (s == 2) loadFresh();
    _notify();
  }

  Future<List<SteamGame>?> _fetch(int start, int count, String term, String sortKey) async {
    final q = term.isEmpty ? '' : '&term=${Uri.encodeQueryComponent(term)}';
    final j = await Net.json('https://store.steampowered.com/search/results/?query&start=$start&count=$count'
        '&infinite=1&category1=998&vrsupport=401&cc=us&l=english&sort_by=$sortKey$q');
    if (j is! Map || j['results_html'] is! String) return null;
    return _parse(j['results_html'] as String);
  }

  List<SteamGame> _parse(String html) {
    final out = <SteamGame>[];
    for (final row in html.split('<a href="https://store.steampowered.com/app/').skip(1)) {
      final id = int.tryParse(RegExp(r'^(\d+)').firstMatch(row)?.group(1) ?? '');
      if (id == null) continue;
      final title = _unesc(RegExp(r'<span class="title">(.*?)</span>', dotAll: true).firstMatch(row)?.group(1) ?? '');
      final g = game(id, title);
      if (title.isNotEmpty) g.name = title;

      final tip = RegExp(r'data-tooltip-html="([^"]*)"').firstMatch(row)?.group(1);
      if (tip != null) {
        final txt = _unesc(tip);
        g.reviewDesc = txt.split(RegExp(r'<br\s*/?>')).first.trim();
        final m = RegExp(r'(\d+)% of the ([\d,]+)').firstMatch(txt);
        if (m != null) {
          g.positivePct = int.parse(m.group(1)!);
          g.totalReviews = int.parse(m.group(2)!.replaceAll(',', ''));
        }
      } else {
        g.reviewDesc ??= 'No reviews yet';
      }

      final cents = RegExp(r'data-price-final="(\d+)"').firstMatch(row)?.group(1);
      final fin = RegExp(r'class="discount_final_price[^"]*">(.*?)</div>', dotAll: true).firstMatch(row)?.group(1);
      final orig = RegExp(r'class="discount_original_price">(.*?)</div>', dotAll: true).firstMatch(row)?.group(1);
      final pct = RegExp(r'class="discount_pct">-?(\d+)%').firstMatch(row)?.group(1);
      if (cents != null) g.priceCents = int.parse(cents);
      final finText = fin == null ? '' : stripHtml(fin).trim();
      if (finText.toLowerCase().contains('free') || (cents != null && g.priceCents == 0 && finText.isEmpty)) {
        g.free = true;
        g.priceCents = 0;
      } else if (finText.isNotEmpty) {
        g.price = finText;
        g.free = false;
      }
      g.oldPrice = orig == null ? null : stripHtml(orig).trim();
      if (g.oldPrice != null && g.oldPrice!.isEmpty) g.oldPrice = null;
      g.discount = pct == null ? 0 : int.parse(pct);

      final rel = RegExp(r'search_released[^"]*">(.*?)</div>', dotAll: true).firstMatch(row)?.group(1)?.trim();
      if (rel != null && rel.isNotEmpty && g.release.isEmpty) g.release = rel;
      out.add(g);
    }
    return out;
  }

  Future<void> _fallback() async {
    final list = [for (final f in _fallbackVr) game(f.$1, f.$2)];
    final ids = list.map((g) => g.id).join(',');
    final j = await Net.json('https://store.steampowered.com/api/appdetails?appids=$ids&filters=price_overview&cc=us');
    if (j is! Map) return;
    for (final g in list) {
      final e = j['${g.id}'];
      if (e is! Map || e['success'] != true) continue;
      final d = e['data'];
      if (d is Map && d['price_overview'] is Map) {
        _applyPrice(g, d['price_overview'] as Map);
      } else {
        g.free = true;
        g.priceCents = 0;
      }
    }
    await Future.wait(list.map(reviews));
    top
      ..clear()
      ..addAll(list);
  }

  static void _applyPrice(SteamGame g, Map p) {
    g.price = p['final_formatted'] as String?;
    g.priceCents = (p['final'] as num?)?.toInt() ?? -1;
    g.discount = (p['discount_percent'] as num?)?.toInt() ?? 0;
    final old = p['initial_formatted'] as String?;
    g.oldPrice = (old == null || old.isEmpty) ? null : old;
    g.free = false;
  }

  Future<void> reviews(SteamGame g) async {
    final j = await Net.json('https://store.steampowered.com/appreviews/${g.id}?json=1&language=all&num_per_page=0');
    if (j is! Map) return;
    final q = j['query_summary'];
    if (q is! Map) return;
    final tot = (q['total_reviews'] as num?)?.toInt() ?? 0;
    final pos = (q['total_positive'] as num?)?.toInt() ?? 0;
    g.reviewDesc = tot == 0 ? 'No reviews yet' : (q['review_score_desc'] as String?);
    g.totalReviews = tot;
    g.positivePct = tot > 0 ? (pos * 100 / tot).round() : -1;
  }

  Future<ReviewPage?> reviewPage(SteamGame g,
      {String cursor = '*', String type = 'all', bool recent = false, int? minH, int? maxH, int per = 40}) async {
    Object? j;
    for (var attempt = 0; attempt < 3; attempt++) {
      j = await Net.json('https://store.steampowered.com/appreviews/${g.id}?json=1'
          '&filter=${recent ? 'recent' : 'all'}&language=all&num_per_page=$per&purchase_type=all'
          '&review_type=$type&filter_offtopic_activity=0&cursor=${Uri.encodeQueryComponent(cursor)}'
          '${minH == null ? '' : '&playtime_filter_min=$minH'}${maxH == null ? '' : '&playtime_filter_max=$maxH'}');
      if (j is Map && j['reviews'] is List) break;
      await Future.delayed(Duration(milliseconds: 700 * (attempt + 1)));
    }
    if (j is! Map || j['reviews'] is! List) return null;
    final rawList = j['reviews'] as List;
    final out = <SteamReview>[];
    for (final r in rawList) {
      if (r is! Map) continue;
      final text = '${r['review'] ?? ''}'.trim();
      if (text.isEmpty) continue;
      final au = r['author'];
      final mins = ((au is Map ? au['playtime_forever'] : 0) as num? ?? 0).toDouble();
      out.add(SteamReview(
        r['voted_up'] == true,
        text.length > 2400 ? '${text.substring(0, 2400)}…' : text,
        mins / 60,
        (r['votes_up'] as num?)?.toInt() ?? 0,
        (r['timestamp_created'] as num?)?.toInt() ?? 0,
        id: '${r['recommendationid'] ?? ''}',
      ));
    }
    final next = j['cursor'];
    return ReviewPage(out, next is String && next.isNotEmpty ? next : null, rawList.length);
  }

  static String _plain(String h) => h
      .replaceAll(RegExp(r'<br\s*/?>', caseSensitive: false), '\n')
      .replaceAll(RegExp(r'<[^>]+>'), '')
      .replaceAll('&nbsp;', ' ')
      .replaceAll('&amp;', '&')
      .replaceAll('&quot;', '"')
      .replaceAll('&#39;', "'")
      .replaceAll('&lt;', '<')
      .replaceAll('&gt;', '>')
      .trim();

  static List<(String, String)> _reqRows(Object? html) {
    if (html is! String || html.trim().isEmpty) return const [];
    final out = <(String, String)>[];
    final lis = RegExp(r'<li[^>]*>([\s\S]*?)</li>', caseSensitive: false).allMatches(html);
    if (lis.isNotEmpty) {
      for (final m in lis) {
        final raw = m.group(1)!;
        final strong = RegExp(r'<strong>([\s\S]*?)</strong>', caseSensitive: false).firstMatch(raw);
        final label = strong == null ? '' : _plain(strong.group(1)!).replaceAll(RegExp(r':\s*$'), '').trim();
        final value = _plain(strong == null ? raw : raw.replaceFirst(strong.group(0)!, ''));
        if (strong != null && label.isNotEmpty && value.isNotEmpty) {
          out.add((label, value));
        } else {
          final plain = _plain(raw);
          if (plain.isNotEmpty) out.add(('Note', plain));
        }
      }
    } else {
      final text = html.replaceFirst(RegExp(r'<strong>\s*(minimum|recommended):?\s*</strong>', caseSensitive: false), '');
      for (final line in _plain(text).split('\n')) {
        final l = line.trim();
        final i = l.indexOf(':');
        if (i > 0 && i < 22 && i < l.length - 1) {
          out.add((l.substring(0, i).trim(), l.substring(i + 1).trim()));
        } else if (l.isNotEmpty) {
          out.add(('Note', l));
        }
      }
    }
    return out;
  }

  Future<void> details(SteamGame g) async {
    if (g.detailsLoaded) return;
    final j = await Net.json('https://store.steampowered.com/api/appdetails?appids=${g.id}&cc=us&l=english');
    final e = j is Map ? j['${g.id}'] : null;
    if (e is! Map || e['success'] != true || e['data'] is! Map) return;
    final d = e['data'] as Map;
    g.name = '${d['name'] ?? g.name}';
    final hi = d['header_image'];
    if (hi is String && hi.isNotEmpty) g.img = hi.split('?').first;
    g.short = stripHtml('${d['short_description'] ?? ''}');
    g.about = stripHtml('${d['about_the_game'] ?? d['detailed_description'] ?? ''}');
    g.shots = [
      for (final s in (d['screenshots'] as List? ?? const []))
        if (s is Map) ('${s['path_thumbnail']}', '${s['path_full']}')
    ];
    final pcr = d['pc_requirements'];
    if (pcr is Map) {
      g.reqMin = _reqRows(pcr['minimum']);
      g.reqRec = _reqRows(pcr['recommended']);
    }
    final rd = d['release_date'];
    if (rd is Map) {
      g.release = '${rd['date'] ?? ''}';
      g.comingSoon = rd['coming_soon'] == true;
    }
    g.devs = [for (final x in (d['developers'] as List? ?? const [])) '$x'];
    g.pubs = [for (final x in (d['publishers'] as List? ?? const [])) '$x'];
    g.genres = [
      for (final x in (d['genres'] as List? ?? const []))
        if (x is Map) '${x['description']}'
    ];
    final pl = d['platforms'];
    if (pl is Map) {
      g.platforms = [
        if (pl['windows'] == true) 'Windows',
        if (pl['mac'] == true) 'macOS',
        if (pl['linux'] == true) 'Linux',
      ];
    }
    g.vr = (d['categories'] as List? ?? const [])
        .any((c) => c is Map && '${c['description']}'.toLowerCase().contains('vr'));
    if (d['is_free'] == true) {
      g.free = true;
      g.priceCents = 0;
    } else if (d['price_overview'] is Map) {
      _applyPrice(g, d['price_overview'] as Map);
    }
    g.detailsLoaded = true;
    if (g.reviewDesc == null || g.positivePct < 0) await reviews(g);
    _notify();
  }
}

class SteamImg extends StatefulWidget {
  final SteamGame g;
  final bool hero;
  final int cacheWidth;
  const SteamImg({super.key, required this.g, this.hero = false, this.cacheWidth = 600});
  @override
  State<SteamImg> createState() => _SteamImgState();
}

class _SteamImgState extends State<SteamImg> {
  int step = 0;
  bool asked = false, handling = false;

  List<String> get urls => {
        if (widget.hero) widget.g.hero,
        widget.g.header,
        'https://cdn.cloudflare.steamstatic.com/steam/apps/${widget.g.id}/header.jpg',
        'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/${widget.g.id}/header.jpg',
      }.toList();

  void _failed() {
    if (handling) return;
    handling = true;
    WidgetsBinding.instance.addPostFrameCallback((_) async {
      if (!mounted) return;
      if (!asked) {
        asked = true;
        final u = await steamHeader(widget.g.id);
        if (!mounted) return;
        if (u != widget.g.img) {
          widget.g.img = u;
          setState(() {
            step = 0;
            handling = false;
          });
          return;
        }
      }
      setState(() {
        step++;
        handling = false;
      });
    });
  }

  @override
  Widget build(BuildContext context) {
    final list = urls;
    if (step >= list.length) {
      final pal = _avatarPals[widget.g.id % _avatarPals.length];
      return DecoratedBox(
        decoration: BoxDecoration(gradient: LinearGradient(colors: pal, begin: Alignment.topLeft, end: Alignment.bottomRight)),
        child: Center(
          child: Padding(
            padding: const EdgeInsets.all(12),
            child: Text(widget.g.name,
                textAlign: TextAlign.center,
                maxLines: 2,
                style: t(16, w: FontWeight.w800, c: Colors.white, display: true)),
          ),
        ),
      );
    }
    return Container(
      color: Pal.card2,
      child: Image.network(
        list[step],
        key: ValueKey(list[step]),
        fit: BoxFit.cover,
        width: double.infinity,
        height: double.infinity,
        cacheWidth: widget.cacheWidth,
        gaplessPlayback: true,
        frameBuilder: (_, child, frame, sync) => sync
            ? child
            : AnimatedOpacity(opacity: frame == null ? 0 : 1, duration: ms(450), curve: Curves.easeOut, child: child),
        errorBuilder: (_, __, ___) {
          _failed();
          return const SizedBox.expand();
        },
      ),
    );
  }
}

class GameSearch extends StatefulWidget {
  final String hint;
  final double? width;
  final double panelWidth;
  final TextEditingController? controller;
  final ValueChanged<String>? onChanged, onSubmit;
  final ValueChanged<SteamGame> onPick;
  const GameSearch(
      {super.key,
      required this.hint,
      required this.onPick,
      this.width,
      this.panelWidth = 440,
      this.controller,
      this.onChanged,
      this.onSubmit});
  @override
  State<GameSearch> createState() => _GameSearchState();
}

class _GameSearchState extends State<GameSearch> {
  final link = LayerLink();
  final portal = OverlayPortalController();
  final focus = FocusNode();
  final group = Object();
  late final TextEditingController ctl = widget.controller ?? TextEditingController();
  List<SteamGame> hits = [];
  bool busy = false;
  String query = '';
  Timer? _deb;
  int _q = 0;

  @override
  void initState() {
    super.initState();
    focus.addListener(_refocus);
  }

  void _refocus() {
    if (focus.hasFocus) _reopen();
  }

  void _reopen() {
    if (ctl.text.trim().isEmpty) return;
    if (hits.isEmpty) {
      _changed(ctl.text);
    } else {
      portal.show();
    }
  }

  @override
  void dispose() {
    _deb?.cancel();
    focus.removeListener(_refocus);
    focus.dispose();
    if (widget.controller == null) ctl.dispose();
    super.dispose();
  }

  void _changed(String v) {
    widget.onChanged?.call(v);
    _deb?.cancel();
    final q = v.trim();
    query = q;
    if (q.isEmpty) {
      setState(() {
        hits = [];
        busy = false;
      });
      portal.hide();
      return;
    }
    setState(() {
      busy = true;
      hits = SteamStore.i.local(q).take(6).toList();
    });
    portal.show();
    final my = ++_q;
    _deb = Timer(const Duration(milliseconds: 300), () async {
      final r = await SteamStore.i.suggest(q);
      if (!mounted || my != _q) return;
      setState(() {
        hits = r;
        busy = false;
      });
    });
  }

  void _pick(SteamGame g) {
    portal.hide();
    focus.unfocus();
    widget.onPick(g);
  }

  void _submit(String v) {
    portal.hide();
    if (v.trim().isNotEmpty) widget.onSubmit?.call(v.trim());
  }

  @override
  Widget build(BuildContext context) => TapRegion(
        groupId: group,
        onTapOutside: (_) => portal.hide(),
        child: OverlayPortal(
          controller: portal,
          overlayChildBuilder: (_) => Positioned(
            width: widget.panelWidth,
            child: CompositedTransformFollower(
              link: link,
              showWhenUnlinked: false,
              offset: const Offset(0, 50),
              child: TapRegion(
                groupId: group,
                child: FadeIn(
                  dy: -.02,
                  child: Material(
                    color: Colors.transparent,
                    child: Container(
                      padding: const EdgeInsets.all(8),
                      decoration: BoxDecoration(
                        color: Pal.card2,
                        borderRadius: BorderRadius.circular(18),
                        border: Border.all(color: Pal.stroke),
                        boxShadow: const [BoxShadow(color: Color(0x99000000), blurRadius: 50, offset: Offset(0, 18))],
                      ),
                      child: AnimatedSize(
                        duration: ms(260),
                        curve: Curves.easeOutCubic,
                        alignment: Alignment.topCenter,
                        child: Column(mainAxisSize: MainAxisSize.min, children: [
                          if (hits.isEmpty)
                            Padding(
                              padding: const EdgeInsets.all(16),
                              child: Row(children: [
                                if (busy)
                                  SizedBox(
                                      width: 16, height: 16, child: CircularProgressIndicator(strokeWidth: 2, color: Pal.a))
                                else
                                  const Icon(Icons.search_off_rounded, size: 18, color: Pal.dim),
                                const SizedBox(width: 12),
                                Text(busy ? 'Searching Steam VR…' : 'No VR games match “$query”',
                                    style: t(13.5, c: Pal.sub)),
                              ]),
                            ),
                          for (var k = 0; k < hits.length; k++)
                            FadeIn(
                              key: ValueKey(hits[k].id),
                              delay: k * 35,
                              child: Hover(
                                onTap: () => _pick(hits[k]),
                                builder: (h) => AnimatedContainer(
                                  duration: ms(200),
                                  curve: Curves.easeOutCubic,
                                  padding: const EdgeInsets.all(8),
                                  decoration: BoxDecoration(
                                    color: h ? Colors.white.withValues(alpha: .07) : Colors.transparent,
                                    borderRadius: BorderRadius.circular(12),
                                  ),
                                  child: Row(children: [
                                    ClipRRect(
                                      borderRadius: BorderRadius.circular(8),
                                      child: SizedBox(width: 92, height: 43, child: SteamImg(g: hits[k], cacheWidth: 200)),
                                    ),
                                    const SizedBox(width: 12),
                                    Expanded(
                                      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                                        Text(hits[k].name,
                                            style: t(13.5, w: FontWeight.w700), maxLines: 1, overflow: TextOverflow.ellipsis),
                                        const SizedBox(height: 2),
                                        Text(hits[k].reviewDesc ?? '',
                                            style: t(11.5, w: FontWeight.w600, c: reviewColor(hits[k].reviewDesc)),
                                            maxLines: 1,
                                            overflow: TextOverflow.ellipsis),
                                      ]),
                                    ),
                                    const SizedBox(width: 8),
                                    PricePill(g: hits[k], hot: h),
                                  ]),
                                ),
                              ),
                            ),
                          if (query.isNotEmpty && widget.onSubmit != null) ...[
                            Container(height: 1, margin: const EdgeInsets.symmetric(vertical: 6), color: Pal.stroke),
                            Hover(
                              onTap: () => _submit(query),
                              builder: (h) => AnimatedContainer(
                                duration: ms(200),
                                padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
                                decoration: BoxDecoration(
                                  color: h ? Pal.a.withValues(alpha: .12) : Colors.transparent,
                                  borderRadius: BorderRadius.circular(12),
                                ),
                                child: Row(children: [
                                  AnimIcon(Icons.manage_search_rounded, size: 18, color: h ? Pal.a : Pal.sub),
                                  const SizedBox(width: 10),
                                  Expanded(
                                    child: Text('See all results for “$query”',
                                        style: t(13, w: FontWeight.w600, c: h ? Pal.a : Pal.text),
                                        overflow: TextOverflow.ellipsis),
                                  ),
                                  AnimatedSlide(
                                    offset: Offset(h ? .3 : 0, 0),
                                    duration: ms(220),
                                    child: AnimIcon(Icons.arrow_forward_rounded, size: 16, color: h ? Pal.a : Pal.dim),
                                  ),
                                ]),
                              ),
                            ),
                          ],
                        ]),
                      ),
                    ),
                  ),
                ),
              ),
            ),
          ),
          child: CompositedTransformTarget(
            link: link,
            child: Listener(
              onPointerDown: (_) => _reopen(),
              child: Field(
                c: ctl,
                focus: focus,
                width: widget.width,
                hint: widget.hint,
                icon: Icons.search_rounded,
                onChanged: _changed,
                onSubmit: _submit,
              ),
            ),
          ),
        ),
      );
}

class StoreSwitch extends StatelessWidget {
  final int sel;
  final ValueChanged<int> on;
  const StoreSwitch({super.key, required this.sel, required this.on});
  static const _w = [118.0, 148.0];

  Widget _item(int i, String label, Uint8List logo, double lh, {bool tint = true}) {
    final active = sel == i;
    final col = active ? Pal.ink : Pal.text;
    return Hover(
      onTap: () => on(i),
      builder: (h) {
        final lit = h && !active;
        return SizedBox(
          width: _w[i],
          height: 40,
          child: Stack(alignment: Alignment.center, children: [
            AnimatedContainer(
              duration: ms(150),
              curve: Curves.easeOutCubic,
              margin: EdgeInsets.all(lit ? 0 : 6),
              decoration: BoxDecoration(
                color: Colors.white.withValues(alpha: lit ? .13 : 0),
                borderRadius: BorderRadius.circular(12),
              ),
            ),
            AnimatedSlide(
              duration: ms(150),
              curve: Curves.easeOutCubic,
              offset: Offset(0, lit ? -.06 : 0),
              child: Row(mainAxisAlignment: MainAxisAlignment.center, children: [
                AnimatedScale(
                  duration: ms(190),
                  curve: Curves.easeOutBack,
                  scale: lit ? 1.2 : 1,
                  child: TweenAnimationBuilder<Color?>(
                    tween: ColorTween(end: lit ? Colors.white : col),
                    duration: ms(150),
                    builder: (_, c, __) => Image.memory(logo,
                        height: lh,
                        cacheHeight: 48,
                        isAntiAlias: true,
                        color: tint ? c : null,
                        colorBlendMode: tint ? BlendMode.srcIn : null,
                        filterQuality: FilterQuality.high),
                  ),
                ),
                const SizedBox(width: 9),
                AnimatedDefaultTextStyle(
                  duration: ms(150),
                  style: t(13.5, w: FontWeight.w700, c: lit ? Colors.white : col),
                  child: Text(label),
                ),
              ]),
            ),
          ]),
        );
      },
    );
  }

  @override
  Widget build(BuildContext context) => Container(
        padding: const EdgeInsets.all(4),
        decoration: BoxDecoration(
          color: Colors.white.withValues(alpha: .06),
          borderRadius: BorderRadius.circular(16),
          border: Border.all(color: Pal.stroke),
        ),
        child: SizedBox(
          width: _w[0] + _w[1],
          height: 40,
          child: Stack(children: [
            AnimatedPositioned(
              duration: ms(210),
              curve: Curves.easeOutCubic,
              left: sel == 0 ? 0 : _w[0],
              width: _w[sel],
              top: 0,
              bottom: 0,
              child: Container(
                decoration: BoxDecoration(
                  borderRadius: BorderRadius.circular(12),
                  gradient: LinearGradient(colors: [Pal.a, Pal.b]),
                  boxShadow: [BoxShadow(color: Pal.a.withValues(alpha: .3), blurRadius: 10)],
                ),
              ),
            ),
            Row(children: [_item(0, 'Steam', steamLogoBytes, 15), _item(1, 'Meta Quest', metaLogoBytes, 12, tint: false)]),
          ]),
        ),
      );
}

class StorePage extends StatefulWidget {
  const StorePage({super.key});
  @override
  State<StorePage> createState() => _StorePageState();
}

class _StorePageState extends State<StorePage> {
  ScrollController? _sc;
  static int tab = 0;
  static SteamGame? open;

  final ctl = TextEditingController(text: SteamStore.i.term);
  Timer? _deb;

  @override
  void initState() {
    super.initState();
    SteamStore.i.addListener(_on);
    storeSearch.addListener(_fromSidebar);
    SteamStore.i.start();
    WidgetsBinding.instance.addPostFrameCallback((_) => _fromSidebar());
  }

  void _on() {
    if (mounted) setState(() {});
  }

  void _fromSidebar() {
    final r = storeSearch.value;
    if (r == null || !mounted) return;
    storeSearch.value = null;
    if (r.game != null) {
      setState(() {
        tab = 0;
        open = r.game;
      });
      return;
    }
    ctl.text = r.q;
    setState(() {
      tab = 0;
      open = null;
    });
    SteamStore.i.search(r.q);
  }

  @override
  void dispose() {
    SteamStore.i.removeListener(_on);
    storeSearch.removeListener(_fromSidebar);
    _deb?.cancel();
    ctl.dispose();
    super.dispose();
  }

  void _typed(String v) {
    _deb?.cancel();
    _deb = Timer(const Duration(milliseconds: 350), () => SteamStore.i.search(v));
  }

  @override
  Widget build(BuildContext context) {
    return AnimatedSwitcher(
      duration: ms(460),
      reverseDuration: ms(160),
      switchInCurve: Curves.easeOutCubic,
      switchOutCurve: Curves.easeIn,
      layoutBuilder: (cur, prev) => Stack(fit: StackFit.expand, children: [...prev, if (cur != null) cur]),
      transitionBuilder: (c, a) => FadeTransition(
        opacity: a,
        child: Glide(anim: a, from: const Offset(30, 0), child: c),
      ),
      child: open != null
          ? SteamDetail(key: ValueKey(open!.id), g: open!, onBack: () => setState(() => open = null))
          : KeyedSubtree(key: const ValueKey('grid'), child: _browse()),
    );
  }

  void _setTab(int i) {
    final c = _sc;
    if (c != null && c.hasClients) c.jumpTo(0);
    setState(() => tab = i);
  }

  Widget _storeHead() => Row(crossAxisAlignment: CrossAxisAlignment.end, children: [
              Expanded(
                child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  AnimatedSwitcher(
                    duration: ms(300),
                    switchInCurve: const Interval(.5, 1, curve: Curves.easeOut),
                    switchOutCurve: const Interval(.5, 1, curve: Curves.easeIn),
                    layoutBuilder: (cur, prev) => Stack(alignment: Alignment.centerLeft, children: [...prev, if (cur != null) cur]),
                    transitionBuilder: (c, a) => FadeTransition(opacity: a, child: c),
                    child: Row(
                      key: ValueKey(tab),
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        IconTile(
                          child: Image.memory(tab == 0 ? steamLogoBytes : metaLogoBytes,
                              height: tab == 0 ? 21 : 16,
                              cacheHeight: 64,
                              isAntiAlias: true,
                              color: tab == 0 ? Colors.white : null,
                              colorBlendMode: tab == 0 ? BlendMode.srcIn : null,
                              filterQuality: FilterQuality.high),
                        ),
                        const SizedBox(width: 16),
                        Text(tab == 0 ? 'Steam' : 'Meta Quest',
                            style: t(32, w: FontWeight.w700, ls: -.8, display: true, h: 1.1)),
                      ],
                    ),
                  ),
                  const SizedBox(height: 7),
                  Text('The VR games everyone is playing, straight from Steam and Meta.', style: t(14, c: Pal.sub)),
                ]),
              ),
              StoreSwitch(sel: tab, on: _setTab),
            ]);

  Widget _browse() => Padding(
        padding: const EdgeInsets.fromLTRB(36, 0, 26, 0),
        child: LayoutBuilder(
          builder: (context, cons) => SmoothScroll(
            builder: (c, p) {
              _sc = c;
              return CustomScrollView(
                cacheExtent: 1400,
                controller: c,
                physics: p,
                slivers: [
                  const SliverToBoxAdapter(child: SizedBox(height: 30)),
                  SliverToBoxAdapter(child: Padding(padding: const EdgeInsets.only(right: 10), child: _storeHead())),
                  const SliverToBoxAdapter(child: SizedBox(height: 22)),
                  if (tab == 1) const MetaList() else _steam(cons.maxWidth),
                ],
              );
            },
          ),
        ),
      );

  Widget _steam(double full) {
    final st = SteamStore.i;
    final list = st.items;
    final searching = st.results != null;
      final width = full - 10;
      final cols = math.max(2, (width / 280).floor());
      final cw = (width - (cols - 1) * 16) / cols;
      final ch = cw * 215 / 460 + 112;
      return SliverMainAxisGroup(slivers: [
        SliverToBoxAdapter(
          child: Padding(
        padding: const EdgeInsets.only(right: 10),
        child: Row(children: [
          Expanded(
            child: GameSearch(
              controller: ctl,
              hint: 'Search VR games on Steam',
              onChanged: _typed,
              onSubmit: (q) => st.search(q),
              onPick: (g) => setState(() => open = g),
            ),
          ),
          const SizedBox(width: 10),
          SortMenu(sel: st.sort, names: SteamStore.sortNames, on: st.setSort),
        ]),
      ),
        ),
        const SliverToBoxAdapter(child: SizedBox(height: 20)),
            SliverToBoxAdapter(
              child: AnimatedSize(
                duration: ms(420),
                curve: Curves.easeOutCubic,
                alignment: Alignment.topCenter,
                child: !searching && st.sort != 2 && st.top.isNotEmpty
                    ? Padding(
                        padding: const EdgeInsets.only(bottom: 26, right: 10),
                        child: FadeIn(
                          child: FeaturedSteam(g: st.top.first, onOpen: () => setState(() => open = st.top.first)),
                        ),
                      )
                    : const SizedBox(width: double.infinity),
              ),
            ),
            SliverToBoxAdapter(
              child: Padding(
                padding: const EdgeInsets.only(bottom: 14, right: 10),
                child: Row(children: [
                  AnimatedSwitcher(
                    duration: ms(260),
                    child: Text(searching ? 'Results for “${st.term}”' : (st.sort == 2 ? 'New VR releases' : 'Top VR games on Steam'),
                        key: ValueKey(searching ? st.term : '${st.sort == 2}'), style: t(17, w: FontWeight.w700, display: true)),
                  ),
                  const SizedBox(width: 10),
                  AnimatedSwitcher(
                    duration: ms(300),
                    child: list.isNotEmpty
                        ? Tag('${list.length} games', key: ValueKey(list.length), c: Pal.sub)
                        : const SizedBox.shrink(),
                  ),
                  const SizedBox(width: 10),
                  AnimatedOpacity(
                    opacity: st.loading || st.searching ? 1 : 0,
                    duration: ms(250),
                    child: SizedBox(width: 14, height: 14, child: CircularProgressIndicator(strokeWidth: 2, color: Pal.a)),
                  ),
                ]),
              ),
            ),
            if (st.failed && !st.loading)
              SliverToBoxAdapter(
                child: Padding(
                  padding: const EdgeInsets.only(right: 10),
                  child: FadeIn(
                    child: Panel(
                      child: Row(children: [
                        const Icon(Icons.wifi_off_rounded, color: Pal.warn),
                        const SizedBox(width: 14),
                        Expanded(child: Text('Couldn’t reach Steam. Check your internet connection.', style: t(14))),
                        Btn(label: 'Try again', icon: Icons.refresh_rounded, onTap: st.retry),
                      ]),
                    ),
                  ),
                ),
              )
            else if (list.isEmpty && !st.loading && !st.searching)
              SliverToBoxAdapter(
                child: Padding(
                  padding: const EdgeInsets.symmetric(vertical: 50),
                  child: Center(
                      child: Text(st.sort == 2 && !searching ? 'No new VR releases found yet.' : 'No VR games match “${st.term}”.',
                          style: t(14, c: Pal.sub))),
                ),
              )
            else
              SliverPadding(
                padding: const EdgeInsets.only(right: 10, bottom: 30),
                sliver: SliverGrid(
                  gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
                    crossAxisCount: cols,
                    mainAxisSpacing: 16,
                    crossAxisSpacing: 16,
                    mainAxisExtent: ch,
                  ),
                  delegate: SliverChildBuilderDelegate(
                    (_, i) => FadeIn(
                      key: ValueKey(list[i].id),
                      delay: (i % cols) * 45,
                      child: SteamCard(g: list[i], onOpen: () => setState(() => open = list[i])),
                    ),
                    childCount: list.length,
                  ),
                ),
              ),
                ]);
  }
}

