            child: Row(mainAxisSize: MainAxisSize.min, children: [
              const Icon(Icons.sort_rounded, size: 18, color: Pal.sub),
              const SizedBox(width: 8),
              AnimatedSwitcher(
                duration: ms(220),
                child: Text(names[sel], key: ValueKey(sel), style: t(13.5, w: FontWeight.w600)),
