class MetaArt {
  static final _mem = <String, String?>{};
  static final _busy = <String, Future<String?>>{};
  static int _running = 0;
  static final _wait = <Completer<void>>[];

  static Map get _saved => (Prefs.data['metaArt5'] as Map?) ?? const {};
  static bool known(String name) => _mem.containsKey(name) || _saved.containsKey(name);

  static String? cached(String name) {
    if (_mem.containsKey(name)) return _mem[name];
    final v = _saved[name];
    if (v is String) return _mem[name] = v.isEmpty ? null : v;
    return null;
  }

  static Future<String?> load(String name) => _busy.putIfAbsent(name, () async {
        if (_running < 3) {
          _running++;
        } else {
          final c = Completer<void>();
          _wait.add(c);
          await c.future;
        }
        try {
          final url = await metaArtFor(name);
          if (url != null) {
            final m = Map<String, dynamic>.from(_saved);
            m[name] = url;
            await Prefs.set('metaArt5', m);
          }
          return _mem[name] = url;
        } finally {
          if (_wait.isNotEmpty) {
            _wait.removeAt(0).complete();
          } else {
            _running--;
          }
        }
      });
}

