class MetaLink {
  static final _busy = <String, Future<String?>>{};

  static Future<String?> resolve(String name) {
    final saved = (Prefs.data['metaUrls'] as Map?)?[name];
    if (saved is String && saved.isNotEmpty) return Future.value(saved);
    final id = _metaIds[name];
    if (id != null) return Future.value('https://www.meta.com/experiences/$id/');
    return _busy.putIfAbsent(name, () => _find(name).whenComplete(() => _busy.remove(name)));
  }

  static Future<String?> _find(String name) async {
    String norm(String s) => s.toLowerCase().replaceAll(RegExp(r'[^a-z0-9]'), '');
    final want = norm(name);
    final c = HttpClient()..connectionTimeout = const Duration(seconds: 8);
    try {
      for (final q in ['"$name" Quest site:meta.com/experiences', '$name Quest VR Games Meta']) {
        try {
          final req = await c.getUrl(Uri.parse('https://html.duckduckgo.com/html/?q=${Uri.encodeQueryComponent(q)}'));
          req.headers.set('User-Agent',
              'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36');
          final res = await req.close().timeout(const Duration(seconds: 12));
          if (res.statusCode != 200) {
            await res.drain<void>();
            continue;
          }
          final body = await res.transform(utf8.decoder).join();
          for (final m in RegExp(r'uddg=([^&<>\s]+)').allMatches(body)) {
            final u = Uri.decodeComponent(m.group(1)!).split('"').first;
            final mm = RegExp(r'^https://www\.meta\.com/experiences/([a-z0-9-]+)/(\d{6,})').firstMatch(u);
            if (mm == null) continue;
            final slug = norm(mm.group(1)!);
            if (slug != want && slug != '${want}vr') continue;
            final url = 'https://www.meta.com/experiences/${mm.group(1)}/${mm.group(2)}/';
            final saved = Map<String, dynamic>.from((Prefs.data['metaUrls'] as Map?) ?? {});
            saved[name] = url;
            await Prefs.set('metaUrls', saved);
            return url;
          }
        } catch (_) {}
      }
    } finally {
      c.close(force: true);
    }
    return null;
  }
}

