class SystemReqs extends StatelessWidget {
  final SteamGame g;
  const SystemReqs({super.key, required this.g});

  static IconData _icon(String label) {
    final k = label.toLowerCase();
    if (k.startsWith('os')) return Icons.window_rounded;
    if (k.contains('processor') || k.contains('cpu')) return Icons.memory_rounded;
    if (k.contains('memory') || k.contains('ram')) return Icons.developer_board_rounded;
    if (k.contains('graphics') || k.contains('video') || k.contains('gpu')) return Icons.videocam_rounded;
    if (k.contains('directx')) return Icons.layers_rounded;
    if (k.contains('storage') || k.contains('hard') || k.contains('disk')) return Icons.storage_rounded;
    if (k.contains('vr')) return Icons.vrpano_rounded;
    if (k.contains('network') || k.contains('internet')) return Icons.wifi_rounded;
    if (k.contains('sound') || k.contains('audio')) return Icons.volume_up_rounded;
    return Icons.info_outline_rounded;
  }

  Widget _row((String, String) r, Color c, bool last) => Container(
        padding: const EdgeInsets.symmetric(vertical: 11),
        decoration: BoxDecoration(
          border: last ? null : Border(bottom: BorderSide(color: Colors.white.withValues(alpha: .06))),
        ),
        child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Icon(_icon(r.$1), size: 17, color: c.withValues(alpha: .9)),
          const SizedBox(width: 12),
          SizedBox(width: 104, child: Text(r.$1.toUpperCase(), style: t(10.5, w: FontWeight.w800, c: Pal.dim, ls: .8))),
          Expanded(child: Text(r.$2, style: t(13.5, w: FontWeight.w600, h: 1.35))),
        ]),
      );

  Widget _col(String title, String sub, Color c, IconData icon, List<(String, String)> rows) {
    final specs = [
      for (final r in rows)
        if (r.$1 != 'Note') r
    ];
    final notes = [
      for (final r in rows)
        if (r.$1 == 'Note') r.$2
    ];
    return Container(
      padding: const EdgeInsets.fromLTRB(20, 18, 20, 12),
      decoration: BoxDecoration(
        gradient: LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: [c.withValues(alpha: .13), Colors.white.withValues(alpha: .03)],
        ),
        borderRadius: BorderRadius.circular(22),
        border: Border.all(color: c.withValues(alpha: .28)),
      ),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: [
          Container(
            width: 36,
            height: 36,
            decoration: BoxDecoration(color: c.withValues(alpha: .18), borderRadius: BorderRadius.circular(12)),
            child: Icon(icon, size: 19, color: c),
          ),
          const SizedBox(width: 12),
          Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text(title, style: t(16, w: FontWeight.w800, display: true)),
            Text(sub, style: t(12, c: Pal.sub)),
          ]),
        ]),
        const SizedBox(height: 12),
        for (var i = 0; i < specs.length; i++)
          FadeIn(
            key: ValueKey('req${g.id}$title$i'),
            delay: i * 40,
            child: _row(specs[i], c, i == specs.length - 1 && notes.isEmpty),
          ),
        for (final n in notes)
          Padding(padding: const EdgeInsets.symmetric(vertical: 6), child: Text(n, style: t(12, c: Pal.dim, h: 1.4))),
      ]),
    );
  }

  @override
  Widget build(BuildContext context) => Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: [
          Icon(Icons.settings_suggest_rounded, size: 21, color: Pal.a),
          const SizedBox(width: 10),
          Text('System requirements', style: t(19, w: FontWeight.w700, display: true)),
        ]),
        const SizedBox(height: 4),
        Text('What a Windows PC needs to run this game.', style: t(13, c: Pal.sub)),
        const SizedBox(height: 14),
        LayoutBuilder(builder: (_, box) {
          final min = g.reqMin.isEmpty ? null : _col('Minimum', 'Runs the game', Pal.steamBlue, Icons.speed_rounded, g.reqMin);
          final rec = g.reqRec.isEmpty ? null : _col('Recommended', 'Runs it smoothly', Pal.good, Icons.auto_awesome_rounded, g.reqRec);
          if (min != null && rec != null && box.maxWidth > 720) {
            return Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Expanded(child: min),
              const SizedBox(width: 16),
              Expanded(child: rec),
            ]);
          }
          return Column(children: [
            if (min != null) min,
            if (min != null && rec != null) const SizedBox(height: 14),
            if (rec != null) rec,
          ]);
        }),
      ]);
}

class ReviewsSection extends StatefulWidget {
  final SteamGame g;
  const ReviewsSection({super.key, required this.g});
  @override
  State<ReviewsSection> createState() => _ReviewsSectionState();
}

class _ReviewsSectionState extends State<ReviewsSection> {
  static const _types = ['all', 'positive', 'negative'];
  static const _maxHours = 200.0;
  static final _tok = RegExp(
      r'\[url=([^\]\s]+)\]([\s\S]*?)\[/url\]|\[url\]([\s\S]*?)\[/url\]|(https?://[^\s\[\]<>"]+)',
      caseSensitive: false);
  static final _img = RegExp(r'\[img\][\s\S]*?\[/img\]', caseSensitive: false);
  static final _tag = RegExp(
      r'\[/?(?:b|i|u|s|h1|h2|h3|code|quote|spoiler|noparse|list|olist|table|tr|td|th|strike|url|previewyoutube)(?:=[^\]]*)?\]',
      caseSensitive: false);

  final items = <SteamReview>[];
  final _seen = <String>{};
  final open = <SteamReview>{};
  final _spans = <SteamReview, List<InlineSpan>>{};
  final _recs = <TapGestureRecognizer>[];
  final _end = GlobalKey();
  ScrollPosition? _pos;
  String cursor = '*';
  bool loading = false, failed = false, exhausted = false, expanded = false;
  int type = 0, sort = 0, pre = 0, _gen = 0, _auto = 0, _pages = 0, _retries = 0;
  bool _serverFilter = true, _waiting = false, _paused = false;
  int _until = 40;
  String? _why;
  RangeValues hours = const RangeValues(0, _maxHours);

  @override
  void initState() {
    super.initState();
    _load();
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    final p = Scrollable.maybeOf(context)?.position;
    if (p != _pos) {
      _pos?.removeListener(_onScroll);
      _pos = p;
      _pos?.addListener(_onScroll);
    }
  }

  @override
  void dispose() {
    _pos?.removeListener(_onScroll);
    for (final r in _recs) {
      r.dispose();
    }
    super.dispose();
  }

  void _reset() {
    _gen++;
    items.clear();
    _seen.clear();
    cursor = '*';
    exhausted = false;
    failed = false;
    loading = false;
    expanded = false;
    _auto = 0;
    _pages = 0;
    _retries = 0;
    _serverFilter = true;
    _waiting = false;
    _paused = false;
    _until = 40;
  }

  Future<void> _load() async {
    if (loading || exhausted) return;
    final gen = _gen;
    _waiting = false;
    setState(() {
      loading = true;
      failed = false;
    });
    Net.lastError = null;
    Future<ReviewPage?> fetch(bool server) => SteamStore.i.reviewPage(widget.g,
        cursor: cursor,
        type: _types[type],
        recent: sort != 0,
        per: sort == 2 ? 100 : 40,
        minH: server && hours.start >= 1 ? hours.start.round() : null,
        maxH: server && hours.end < _maxHours ? hours.end.round() : null);
    final useServer = _serverFilter && (hours.start >= 1 || hours.end < _maxHours);
    var got = await fetch(useServer);
    if (!mounted || gen != _gen) return;
    if (useServer && got != null && got.raw == 0 && cursor == '*') {
      _serverFilter = false;
      got = await fetch(false);
      if (!mounted || gen != _gen) return;
    }
    final r = got;
    if (r == null && _retries < 3) {
      _retries++;
      await Future.delayed(Duration(seconds: 3 * _retries + 1));
      if (!mounted || gen != _gen) return;
      setState(() => loading = false);
      _load();
      return;
    }
    setState(() {
      loading = false;
      if (r == null) {
        failed = true;
        _why = Net.lastError;
        return;
      }
      _retries = 0;
      for (final v in r.list) {
        if (v.id.isEmpty || _seen.add(v.id)) items.add(v);
      }
      _pages++;
      if (r.raw == 0 || r.next == null || r.next == cursor) {
        exhausted = true;
      } else {
        cursor = r.next!;
      }
      if (sort == 2 && _pages >= _until) _paused = true;
    });
    _afterLoad();
  }

  void _afterLoad() {
    if (!mounted) return;
    if (!exhausted && !failed && !loading) {
      final need = (sort == 2 && !_paused) || (_visible.length < 4 && _auto < 8);
      if (need) {
        if (sort != 2) _auto++;
        _waiting = true;
        Future.delayed(ms(350), () {
          if (!mounted) return;
          if (sort == 2 && _paused) {
            setState(() => _waiting = false);
            return;
          }
          _load();
        });
        return;
      }
    }
    WidgetsBinding.instance.addPostFrameCallback((_) => _onScroll());
  }

  void _onScroll() {
    if (!mounted || !expanded || loading || exhausted || failed || sort == 2) return;
    final box = _end.currentContext?.findRenderObject();
    if (box is! RenderBox || !box.attached) return;
    final y = box.localToGlobal(Offset.zero).dy;
    if (y < MediaQuery.sizeOf(context).height + 500) _load();
  }

  List<SteamReview> get _visible {
    final x = [
      for (final r in items)
        if (r.hours >= hours.start && (hours.end >= _maxHours || r.hours <= hours.end)) r
    ];
    if (sort == 1) x.sort((a, b) => b.ts.compareTo(a.ts));
    if (sort == 2) x.sort((a, b) => a.ts.compareTo(b.ts));
    return x;
  }

  static String _clean(String s) => s
      .replaceAll(_img, '')
      .replaceAll('[*]', '• ')
      .replaceAll(RegExp(r'\[hr\]', caseSensitive: false), '\n')
      .replaceAll(_tag, '');

  List<InlineSpan> _rich(SteamReview r) => _spans.putIfAbsent(r, () {
        final link = t(13.5, c: Pal.a, h: 1.5)
            .copyWith(decoration: TextDecoration.underline, decorationColor: Pal.a.withValues(alpha: .5));
        final out = <InlineSpan>[];
        final src = r.text;
        var at = 0;
        for (final m in _tok.allMatches(src)) {
          if (m.start > at) out.add(TextSpan(text: _clean(src.substring(at, m.start))));
          var url = (m.group(1) ?? m.group(3) ?? m.group(4) ?? '').trim();
          var label = m.group(2) ?? m.group(3) ?? m.group(4) ?? url;
          var tail = '';
          if (m.group(4) != null) {
            while (url.isNotEmpty && '.,;:!?)'.contains(url[url.length - 1])) {
              tail = url[url.length - 1] + tail;
              url = url.substring(0, url.length - 1);
            }
            label = url;
          }
          label = _clean(label).trim();
          if (label.isEmpty) label = url;
          if (RegExp(r'^https?://', caseSensitive: false).hasMatch(url)) {
            final rec = TapGestureRecognizer()..onTap = () => LinkGuard.open(context, url);
            _recs.add(rec);
            out.add(TextSpan(text: label, style: link, recognizer: rec, mouseCursor: SystemMouseCursors.click));
          } else {
            out.add(TextSpan(text: label));
          }
          if (tail.isNotEmpty) out.add(TextSpan(text: tail));
          at = m.end;
        }
        if (at < src.length) out.add(TextSpan(text: _clean(src.substring(at))));
        return out;
      });

  String _date(int ts) {
    if (ts <= 0) return '';
    final d = DateTime.fromMillisecondsSinceEpoch(ts * 1000);
    const m = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    return '${m[d.month - 1]} ${d.day}, ${d.year}';
  }

  Widget _card(SteamReview r) {
    final long = r.text.length > 360;
    final isOpen = open.contains(r);
    final c = r.up ? Pal.good : Pal.bad;
    return Panel(
      pad: const EdgeInsets.all(18),
      child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Container(
          width: 38,
          height: 38,
          decoration: BoxDecoration(color: c.withValues(alpha: .15), borderRadius: BorderRadius.circular(12)),
          child: Icon(r.up ? Icons.thumb_up_alt_rounded : Icons.thumb_down_alt_rounded, color: c, size: 19),
        ),
        const SizedBox(width: 14),
        Expanded(
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Row(children: [
              Text(r.up ? 'Recommended' : 'Not recommended', style: t(13.5, w: FontWeight.w700, c: c)),
              const Spacer(),
              Text(_date(r.ts), style: t(12, c: Pal.dim)),
            ]),
            const SizedBox(height: 3),
            Text('${r.hours.toStringAsFixed(1)} h on record${r.helpful > 0 ? ' · ${r.helpful} found this helpful' : ''}',
                style: t(12, c: Pal.sub)),
            const SizedBox(height: 10),
            AnimatedSize(
              duration: ms(260),
              curve: Curves.easeOutCubic,
              alignment: Alignment.topLeft,
              child: Text.rich(
                TextSpan(style: t(13.5, h: 1.5), children: _rich(r)),
                maxLines: isOpen ? null : 6,
                overflow: isOpen ? TextOverflow.visible : TextOverflow.ellipsis,
              ),
            ),
            if (long) ...[
              const SizedBox(height: 8),
              Hover(
                onTap: () => _readAll(r),
                builder: (h) => Text('Read more', style: t(12.5, w: FontWeight.w700, c: h ? Pal.a : Pal.sub)),
              ),
            ],
          ]),
        ),
      ]),
    );
  }

  Widget _group(String label, Widget child) => Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Text(label, style: t(12, w: FontWeight.w700, c: Pal.sub, ls: .4)),
        const SizedBox(height: 8),
        child,
      ]);

  Widget _filters() {
    return Panel(
      pad: const EdgeInsets.all(18),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Wrap(spacing: 28, runSpacing: 14, children: [
          _group(
            'Reviews',
            Seg(
              items: const ['All', 'Positive', 'Negative'],
              sel: type,
              on: (i) {
                if (i == type) return;
                setState(() {
                  type = i;
                  _reset();
                });
                _load();
              },
            ),
          ),
          _group(
            'Sort by',
            Seg(
              items: const ['Most helpful', 'Newest', 'Oldest'],
              sel: sort,
              on: (i) {
                if (i == sort) return;
                setState(() {
                  sort = i;
                  _reset();
                });
                _load();
              },
            ),
          ),
        ]),
        const SizedBox(height: 16),
        _group(
          'Playtime',
          Seg(
            items: const ['No minimum', 'Over 1 hour', 'Over 10 hours'],
            sel: pre,
            on: (i) {
              final lowest = const [0.0, 1.0, 10.0][i];
              setState(() {
                pre = i;
                hours = RangeValues(lowest, math.max(lowest, hours.end));
                _reset();
              });
              _load();
            },
          ),
        ),
        const SizedBox(height: 10),
        _HoursSlider(
          value: hours,
          max: _maxHours,
          onCommit: (v) {
            setState(() {
              hours = v;
              pre = v.start >= 10 ? 2 : (v.start >= 1 ? 1 : 0);
              _reset();
            });
            _load();
          },
        ),
      ]),
    );
  }

  Widget _note(Widget lead, String text, {Widget? action}) => Panel(
        child: Row(children: [
          lead,
          const SizedBox(width: 12),
          Expanded(child: Text(text, style: t(13.5, c: Pal.sub))),
          if (action != null) action,
        ]),
      );

  Widget get _spinner => const SizedBox(width: 18, height: 18, child: CircularProgressIndicator(strokeWidth: 2));

  Widget _teaser(SteamReview r) => Stack(alignment: Alignment.bottomCenter, children: [
        ClipRect(
          child: SizedBox(
            height: 175,
            child: ShaderMask(
              blendMode: BlendMode.dstIn,
              shaderCallback: (b) => const LinearGradient(
                begin: Alignment.topCenter,
                end: Alignment.bottomCenter,
                colors: [Colors.white, Colors.white, Colors.transparent],
                stops: [0, .3, 1],
              ).createShader(b),
              child: IgnorePointer(
                child: OverflowBox(alignment: Alignment.topCenter, minHeight: 0, maxHeight: 700, child: _card(r)),
              ),
            ),
          ),
        ),
        Padding(
          padding: const EdgeInsets.only(bottom: 8),
          child: Btn(
            label: 'Show more reviews',
            icon: Icons.expand_more_rounded,
            primary: true,
            onTap: () => setState(() => expanded = true),
          ),
        ),
      ]);

  Widget _tail() => SizedBox(
        key: _end,
        height: 84,
        child: Center(
          child: loading
              ? TweenAnimationBuilder<double>(
                  tween: Tween<double>(begin: 0, end: 1),
                  duration: ms(350),
                  curve: Curves.easeOutCubic,
                  builder: (_, v, child) => Opacity(opacity: v, child: child),
                  child: SizedBox(width: 28, height: 28, child: CircularProgressIndicator(strokeWidth: 2.8, color: Pal.a)),
                )
              : failed
                  ? Btn(
                      label: 'Couldn’t load more · Try again',
                      onTap: () {
                        _auto = 0;
                        _load();
                      })
                  : exhausted
                      ? Text('That’s every review Steam shared', style: t(12.5, c: Pal.dim))
                      : const SizedBox.shrink(),
        ),
      );

  Widget _body() {
    final v = _visible;
    if (items.isEmpty && loading) return _note(_spinner, 'Loading reviews from Steam…');
    if (sort == 2 && !_paused && !exhausted && !failed && (loading || _waiting)) {
      return _note(_spinner, 'Going back in time… reached ${_oldestText()}, ${items.length} reviews checked.',
          action: Btn(label: 'Show now', onTap: () => setState(() => _paused = true)));
    }
    if (items.isEmpty && failed) {
      return _note(const Icon(Icons.forum_outlined, color: Pal.dim, size: 20),
          'Couldn’t load reviews right now${_why == null ? '' : ' ($_why)'}.',
          action: Btn(
              label: 'Try again',
              onTap: () {
                _auto = 0;
                _retries = 0;
                _load();
              }));
    }
    if (v.isEmpty) {
      if (loading || _waiting) return _note(_spinner, 'Looking for reviews that match…');
      if (!exhausted && !failed) {
        return _note(const Icon(Icons.search_rounded, color: Pal.dim, size: 20),
            'No match in the ${items.length} reviews checked so far.',
            action: Btn(
                label: 'Search more',
                onTap: () {
                  _auto = 0;
                  _load();
                }));
      }
      return _note(const Icon(Icons.filter_alt_off_outlined, color: Pal.dim, size: 20), 'No reviews match these filters.');
    }
    final shown = expanded ? v : v.take(3).toList();
    return Column(children: [
      for (var i = 0; i < shown.length; i++)
        FadeIn(
          key: ValueKey('rev${widget.g.id}:${shown[i].id.isEmpty ? shown[i].text.hashCode : shown[i].id}'),
          child: Padding(padding: const EdgeInsets.only(bottom: 12), child: _card(shown[i])),
        ),
      if (!expanded && v.length > 3) _teaser(v[3]),
      if (expanded) _tail(),
      if (sort == 2 && !exhausted && !loading && !_waiting) _older(),
    ]);
  }

  void _readAll(SteamReview r) {
    final c = r.up ? Pal.good : Pal.bad;
    showGeneralDialog<void>(
      context: context,
      barrierDismissible: true,
      barrierLabel: 'review',
      barrierColor: Colors.transparent,
      transitionDuration: ms(420),
      pageBuilder: (ctx, anim, _) => FogCard(
        anim: anim,
        width: 640,
        onClose: () => Navigator.pop(ctx),
        child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [
          Row(children: [
            Icon(r.up ? Icons.thumb_up_alt_rounded : Icons.thumb_down_alt_rounded, color: c, size: 20),
            const SizedBox(width: 10),
            Text(r.up ? 'Recommended' : 'Not recommended', style: t(15, w: FontWeight.w700, c: c)),
            const Spacer(),
            Text(_date(r.ts), style: t(12.5, c: Pal.dim)),
          ]),
          const SizedBox(height: 4),
          Text('${r.hours.toStringAsFixed(1)} h on record${r.helpful > 0 ? ' · ${r.helpful} found this helpful' : ''}',
              style: t(12.5, c: Pal.sub)),
          const SizedBox(height: 16),
          ConstrainedBox(
            constraints: BoxConstraints(maxHeight: MediaQuery.sizeOf(ctx).height * .55),
            child: SingleChildScrollView(
              child: Text.rich(TextSpan(style: t(14, h: 1.6), children: _rich(r))),
            ),
          ),
          const SizedBox(height: 18),
          Align(alignment: Alignment.centerRight, child: Btn(label: 'Close', onTap: () => Navigator.pop(ctx))),
        ]),
      ),
    );
  }

  String _oldestText() {
    if (items.isEmpty) return 'the start';
    var first = items.first.ts;
    for (final r in items) {
      if (r.ts < first) first = r.ts;
    }
    return _date(first);
  }

  Widget _older() => Padding(
        padding: const EdgeInsets.only(top: 4),
        child: _note(const Icon(Icons.history_rounded, color: Pal.dim, size: 20),
            'Reached ${_oldestText()}. Steam can’t sort oldest first, so this walks back through the reviews.',
            action: Btn(
                label: 'Go further back',
                onTap: () {
                  _until = _pages + 40;
                  _paused = false;
                  _load();
                })),
      );

  @override
  Widget build(BuildContext context) => Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: [
          Image.memory(steamLogoBytes,
              height: 14,
              cacheHeight: 48,
              isAntiAlias: true,
              color: Colors.white,
              colorBlendMode: BlendMode.srcIn,
              filterQuality: FilterQuality.high),
          const SizedBox(width: 10),
          Text('What Steam players say', style: t(19, w: FontWeight.w700, display: true)),
        ]),
        const SizedBox(height: 14),
        _filters(),
        const SizedBox(height: 14),
        AnimatedSize(duration: ms(380), curve: Curves.easeOutCubic, alignment: Alignment.topCenter, child: _body()),
      ]);
}

