class LibGame {
  final String path;
  String name;
  String? icon;
  String? cover;
  int lastPlayed;
  LibGame(this.path, this.name, {this.icon, this.cover, this.lastPlayed = 0});

  factory LibGame.from(Map<String, dynamic> m) => LibGame('${m['path']}', '${m['name']}',
      icon: m['icon'] as String?, cover: m['cover'] as String?, lastPlayed: (m['last'] as num?)?.toInt() ?? 0);

  Map<String, dynamic> toMap() => {'path': path, 'name': name, 'icon': icon, 'cover': cover, 'last': lastPlayed};

  String? get fallbackCover {
    final m = RegExp(r'/apps/(\d+)/').firstMatch(cover ?? '');
    return m == null ? null : 'https://cdn.cloudflare.steamstatic.com/steam/apps/${m.group(1)}/header.jpg';
  }

  String get playedText {
    if (lastPlayed == 0) return 'Not played yet';
    final d = DateTime.now().difference(DateTime.fromMillisecondsSinceEpoch(lastPlayed));
    if (d.inMinutes < 2) return 'Played just now';
    if (d.inHours < 1) return 'Played ${d.inMinutes} min ago';
    if (d.inDays < 1) return 'Played ${d.inHours} h ago';
    if (d.inDays == 1) return 'Played yesterday';
    return 'Played ${d.inDays} days ago';
  }
}

String prettyName(String raw) => raw
    .replaceAll(RegExp(r'[_\-.]+'), ' ')
    .replaceAllMapped(RegExp(r'(?<=[a-z0-9])(?=[A-Z])'), (_) => ' ')
    .replaceAll(RegExp(r'\s+'), ' ')
    .trim();

final _headerCache = <int, String>{};

Future<String> steamHeader(int id) async {
  final hit = _headerCache[id];
  if (hit != null) return hit;
  final j = await Net.json('https://store.steampowered.com/api/appdetails?appids=$id&filters=basic');
  final e = j is Map ? j['$id'] : null;
  final hi = (e is Map && e['data'] is Map) ? (e['data'] as Map)['header_image'] : null;
  final url = (hi is String && hi.isNotEmpty)
      ? hi.split('?').first
      : 'https://cdn.cloudflare.steamstatic.com/steam/apps/$id/header.jpg';
  return _headerCache[id] = url;
}

const _metaSteamIds = <String, int>{
  'Blade & Sorcery: Nomad': 629730,
};

Future<String?> metaArtFor(String name) async {
  final fixed = _metaSteamIds[name];
  if (fixed != null) return steamHeader(fixed);
  String strip(String s) {
    var x = s.toLowerCase().replaceAll(RegExp(r'[^a-z0-9]'), '');
    var again = true;
    while (again) {
      again = false;
      for (final suf in const ['vr', 'beta', 'demo', 'playtest', 'earlyaccess', 'definitiveedition', 'championshipedition']) {
        if (x.length > suf.length + 2 && x.endsWith(suf)) {
          x = x.substring(0, x.length - suf.length);
          again = true;
        }
      }
    }
    return x;
  }

  final variants = <String>{
    name,
    name.replaceAll(RegExp(r'\bvr\b', caseSensitive: false), '').trim(),
    name.replaceAll(RegExp(r':?\s*Nomad$'), '').trim(),
  }..removeWhere((e) => e.isEmpty);
  for (final q in variants) {
    final j = await Net.json(
        'https://store.steampowered.com/api/storesearch/?term=${Uri.encodeQueryComponent(q)}&l=english&cc=US');
    if (j is! Map || j['items'] is! List) continue;
    final want = strip(q);
    for (final it in j['items'] as List) {
      if (it is! Map || strip('${it['name']}') != want) continue;
      final id = (it['id'] as num?)?.toInt();
      if (id != null) return steamHeader(id);
    }
  }
  return null;
}

Future<String?> steamCover(String name) async {
  final q = name.replaceAll(RegExp(r'\b(vr|win64|shipping|launcher)\b', caseSensitive: false), '').trim();
  if (q.isEmpty) return null;
  final j = await Net.json(
      'https://store.steampowered.com/api/storesearch/?term=${Uri.encodeQueryComponent(q)}&l=english&cc=US');
  if (j is! Map || j['items'] is! List) return null;
  String norm(String s) => s.toLowerCase().replaceAll(RegExp(r'[^a-z0-9]'), '');
  final nq = norm(q);
  for (final it in j['items'] as List) {
    if (it is! Map) continue;
    final n = norm('${it['name']}');
    if (n.isEmpty || nq.isEmpty) continue;
    if (n.contains(nq) || nq.contains(n)) {
      final id = (it['id'] as num?)?.toInt();
      if (id == null) continue;
      return steamHeader(id);
    }
  }
  return null;
}

class Library extends ChangeNotifier {
  static final Library i = Library._();
  Library._() {
    games.addAll(Prefs.library.map(LibGame.from));
    Future.microtask(() async {
      for (final g in games) {
        final c = await steamCover(g.name);
        if (c != null && c != g.cover) {
          g.cover = c;
          notifyListeners();
        }
      }
      await _save();
    });
  }

  final games = <LibGame>[];

  Future<void> _save() => Prefs.saveLibrary([for (final g in games) g.toMap()]);

  Future<void> add(List<String> paths, void Function(String) warn) async {
    for (final p in paths) {
      if (!p.toLowerCase().endsWith('.exe')) {
        warn('${baseName(p)} isn’t an .exe file, so it was skipped.');
        continue;
      }
      if (games.any((g) => g.path.toLowerCase() == p.toLowerCase())) {
        warn('${baseName(p)} is already in your library.');
        continue;
      }
      final file = baseName(p);
      var name = prettyName(file.substring(0, file.length - 4));
      final folder = prettyName(baseName(File(p).parent.path));
      if (name.length <= 3 || RegExp(r'^(game|launcher|start|play)$', caseSensitive: false).hasMatch(name)) {
        name = folder;
      }
      final g = LibGame(p, name);
      games.insert(0, g);
      notifyListeners();
      await _save();
      _enrich(g);
    }
  }

  Future<void> _enrich(LibGame g) async {
    final out = '${Prefs.dir}\\icons\\lib_${g.path.toLowerCase().hashCode.abs()}.png';
    try {
      await Directory('${Prefs.dir}\\icons').create(recursive: true);
      String esc(String s) => s.replaceAll("'", "''");
      await Process.run('powershell', [
        '-NoProfile',
        '-Command',
        "Add-Type -AssemblyName System.Drawing; \$i = [System.Drawing.Icon]::ExtractAssociatedIcon('${esc(g.path)}'); if (\$i) { \$i.ToBitmap().Save('${esc(out)}', [System.Drawing.Imaging.ImageFormat]::Png) }"
      ]);
      if (await File(out).exists()) g.icon = out;
    } catch (_) {}
    notifyListeners();
    g.cover = await steamCover(g.name);
    notifyListeners();
    await _save();
  }

  Future<void> remove(LibGame g) async {
    games.remove(g);
    notifyListeners();
    await _save();
  }

  Future<void> rename(LibGame g, String name) async {
    g.name = name;
    notifyListeners();
    await _save();
    g.cover = await steamCover(name) ?? g.cover;
    notifyListeners();
    await _save();
  }

  Future<bool> play(LibGame g) async {
    if (!await File(g.path).exists()) return false;
    try {
      await Process.start(g.path, const [], workingDirectory: File(g.path).parent.path, mode: ProcessStartMode.detached);
      g.lastPlayed = DateTime.now().millisecondsSinceEpoch;
      notifyListeners();
      await _save();
      return true;
    } catch (_) {
      return false;
    }
  }
}

