class AppEntry {
  final String pkg, ver, installer;
  AppEntry(this.pkg, this.ver, this.installer);

  bool get system => pkg.startsWith('com.oculus.') || pkg.startsWith('com.meta.') || pkg.startsWith('com.facebook.');
  bool get sideloaded =>
      installer.isEmpty || installer == 'null' || installer == 'com.android.shell' || installer.contains('packageinstaller');

  String get title {
    final l = IconStore.i.label(pkg);
    if (l != null && l.isNotEmpty) return l;
    final parts = pkg.split('.');
    var last = parts.last;
    if (last.length <= 2 && parts.length > 1) last = parts[parts.length - 2];
    final p = prettyName(last);
    return p.isEmpty ? pkg : p[0].toUpperCase() + p.substring(1);
  }
}

class XAttr {
  final String name;
  final int resId, type, data;
  final String? raw;
  XAttr(this.name, this.resId, this.type, this.data, this.raw);
}

class ApkRes {
  static int _u16(ByteData b, int o) => b.getUint16(o, Endian.little);
  static int _u32(ByteData b, int o) => b.getUint32(o, Endian.little);

  static List<String> pool(Uint8List d, ByteData b, int o) {
    final hs = _u16(b, o + 2);
    final count = _u32(b, o + 8);
    final flags = _u32(b, o + 16);
    final start = _u32(b, o + 20);
    final isUtf8 = flags & 0x100 != 0;
    final out = <String>[];
    for (var i = 0; i < count; i++) {
      try {
        var p = o + start + _u32(b, o + hs + i * 4);
        if (isUtf8) {
          if (d[p] & 0x80 != 0) p++;
          p++;
          var len = d[p];
          p++;
          if (len & 0x80 != 0) {
            len = ((len & 0x7f) << 8) | d[p];
            p++;
          }
          out.add(utf8.decode(Uint8List.sublistView(d, p, p + len), allowMalformed: true));
        } else {
          var len = _u16(b, p);
          p += 2;
          if (len & 0x8000 != 0) {
            len = ((len & 0x7fff) << 16) | _u16(b, p);
            p += 2;
          }
          out.add(String.fromCharCodes([for (var k = 0; k < len; k++) _u16(b, p + k * 2)]));
        }
      } catch (_) {
        out.add('');
      }
    }
    return out;
  }

  static void walkXml(Uint8List d, void Function(String el, List<XAttr> attrs) fn) {
    final b = ByteData.sublistView(d);
    if (d.length < 8) return;
    var strings = <String>[];
    var ids = <int>[];
    var o = 8;
    while (o + 8 <= d.length) {
      final type = _u16(b, o);
      final size = _u32(b, o + 4);
      if (size < 8) break;
      if (type == 0x0001) {
        strings = pool(d, b, o);
      } else if (type == 0x0180) {
        ids = [for (var p = o + 8; p + 4 <= o + size; p += 4) _u32(b, p)];
      } else if (type == 0x0102) {
        final nameIdx = _u32(b, o + 20);
        final aStart = _u16(b, o + 24), aSize = _u16(b, o + 26), aCount = _u16(b, o + 28);
        final attrs = <XAttr>[];
        for (var k = 0; k < aCount; k++) {
          final p = o + 16 + aStart + k * aSize;
          final n = _u32(b, p + 4);
          final rawIdx = _u32(b, p + 8);
          attrs.add(XAttr(
            n < strings.length ? strings[n] : '',
            n < ids.length ? ids[n] : 0,
            d[p + 15],
            _u32(b, p + 16),
            rawIdx < strings.length ? strings[rawIdx] : null,
          ));
        }
        fn(nameIdx < strings.length ? strings[nameIdx] : '', attrs);
      }
      o += size;
    }
  }
}

class Arsc {
  final Uint8List d;
  late final ByteData b = ByteData.sublistView(d);
  List<String> strings = [];
  final _types = <int, List<int>>{};

  Arsc(this.d) {
    var o = ApkRes._u16(b, 2);
    while (o + 8 <= d.length) {
      final type = ApkRes._u16(b, o), size = ApkRes._u32(b, o + 4);
      if (size < 8) break;
      if (type == 0x0001 && strings.isEmpty) {
        strings = ApkRes.pool(d, b, o);
      } else if (type == 0x0200) {
        var c = o + ApkRes._u16(b, o + 2);
        while (c + 8 <= o + size) {
          final ct = ApkRes._u16(b, c), cs = ApkRes._u32(b, c + 4);
          if (cs < 8) break;
          if (ct == 0x0201) _types.putIfAbsent(d[c + 8], () => []).add(c);
          c += cs;
        }
      }
      o += size;
    }
  }

  List<(int, int, int, int)> values(int resId) {
    final out = <(int, int, int, int)>[];
    final entry = resId & 0xffff;
    for (final c in _types[(resId >> 16) & 0xff] ?? const <int>[]) {
      try {
        final hs = ApkRes._u16(b, c + 2);
        final flags = d[c + 9];
        final count = ApkRes._u32(b, c + 12);
        final start = ApkRes._u32(b, c + 16);
        final density = ApkRes._u16(b, c + 20 + 14);
        final lang = ApkRes._u16(b, c + 20 + 8);
        int off = -1;
        if (flags & 0x01 != 0) {
          for (var k = 0; k < count; k++) {
            if (ApkRes._u16(b, c + hs + k * 4) == entry) {
              off = ApkRes._u16(b, c + hs + k * 4 + 2) * 4;
              break;
            }
          }
        } else if (flags & 0x02 != 0) {
          if (entry >= count) continue;
          final v = ApkRes._u16(b, c + hs + entry * 2);
          if (v != 0xffff) off = v * 4;
        } else {
          if (entry >= count) continue;
          final v = ApkRes._u32(b, c + hs + entry * 4);
          if (v != 0xffffffff) off = v;
        }
        if (off < 0) continue;
        final e = c + start + off;
        final eFlags = ApkRes._u16(b, e + 2);
        if (eFlags & 0x08 != 0) {
          out.add((density, lang, eFlags >> 8, ApkRes._u32(b, e + 4)));
        } else if (eFlags & 0x01 == 0) {
          final v = e + ApkRes._u16(b, e);
          out.add((density, lang, d[v + 3], ApkRes._u32(b, v + 4)));
        }
      } catch (_) {}
    }
    return out;
  }

  String? text(int resId, [int depth = 0]) {
    if (depth > 5) return null;
    final vals = values(resId)..sort((x, y) => (x.$2 == 0 ? 0 : 1).compareTo(y.$2 == 0 ? 0 : 1));
    for (final v in vals) {
      if (v.$3 == 0x03 && v.$4 < strings.length) return strings[v.$4];
      if (v.$3 == 0x01) {
        final t = text(v.$4, depth + 1);
        if (t != null) return t;
      }
    }
    return null;
  }

  static int _rank(int den) => den == 0xffff ? 1 : (den == 0xfffe ? 0 : (den == 0 ? 160 : den));

  String? file(int resId, [int depth = 0]) {
    if (depth > 6) return null;
    String? raster, xml;
    var best = -1;
    for (final v in values(resId)) {
      String? p;
      if (v.$3 == 0x03 && v.$4 < strings.length) {
        p = strings[v.$4];
      } else if (v.$3 == 0x01 && v.$4 != 0) {
        p = file(v.$4, depth + 1);
      }
      if (p == null) continue;
      final pl = p.toLowerCase();
      if (pl.endsWith('.png') || pl.endsWith('.webp') || pl.endsWith('.jpg')) {
        final r = _rank(v.$1);
        if (r > best) {
          best = r;
          raster = p;
        }
      } else if (pl.endsWith('.xml')) {
        xml ??= p;
      }
    }
    return raster ?? xml;
  }

  int? color(int resId, [int depth = 0]) {
    if (depth > 5) return null;
    for (final v in values(resId)) {
      if (v.$3 >= 0x1c && v.$3 <= 0x1f) return v.$4;
      if (v.$3 == 0x01) {
        final c = color(v.$4, depth + 1);
        if (c != null) return c;
      }
    }
    return null;
  }
}

class IconStore extends ChangeNotifier {
  static final IconStore i = IconStore._();
  IconStore._();

  static const _key = 'appIcons4';
  final _state = <String, String>{};
  final _queue = <AppEntry>[];
  int _running = 0;

  String get _dir => '${Prefs.dir}\\icons';

  String? label(String pkg) =>
      (kDemo ? Demo.labels[pkg] : null) ?? (Prefs.data['appLabels'] as Map?)?[pkg] as String?;

  String? lookup(AppEntry a) {
    final s = _state[a.pkg];
    if (s != null) return (s == 'none' || s == 'busy') ? null : s;
    final saved = (Prefs.data[_key] as Map?)?[a.pkg];
    if (saved is String && saved.isNotEmpty && _stillThere(saved)) return _state[a.pkg] = saved;
    if (saved == 'none') {
      _state[a.pkg] = 'none';
      return null;
    }
    _state[a.pkg] = 'busy';
    _queue.add(a);
    _pump();
    return null;
  }

  bool _stillThere(String v) {
    if (v.startsWith('url:')) return true;
    if (v.startsWith('file:')) return File(v.substring(5)).existsSync();
    if (v.startsWith('ad:')) return File(v.substring(3).split('|').first).existsSync();
    return false;
  }

  void _pump() {
    while (_running < 2 && _queue.isNotEmpty) {
      final a = _queue.removeAt(0);
      _running++;
      _fetch(a).whenComplete(() {
        _running--;
        notifyListeners();
        _pump();
      });
    }
  }

  Future<void> _fetch(AppEntry a) async {
    String? v;
    try {
      v = await _fromApk(a.pkg);
    } catch (_) {}
    if (v == null) {
      final url = await steamCover(a.title);
      if (url != null) v = 'url:$url';
    }
    _state[a.pkg] = v ?? 'none';
    final m = Map<String, dynamic>.from((Prefs.data[_key] as Map?) ?? {});
    m[a.pkg] = v ?? 'none';
    await Prefs.set(_key, m);
  }

  Future<String?> _fromApk(String pkg) async {
    final paths = (await Adb.shell('pm path $pkg')).split('\n').map((e) => e.trim()).where((e) => e.startsWith('package:'));
    if (paths.isEmpty) return null;
    final apk = paths.firstWhere((p) => p.endsWith('base.apk'), orElse: () => paths.first).substring(8);
    final man = await Adb.bytes(['exec-out', 'unzip', '-p', apk, 'AndroidManifest.xml']);
    final res = await Adb.bytes(['exec-out', 'unzip', '-p', apk, 'resources.arsc']);
    if (man == null || res == null || man.length < 8 || res.length < 12) return null;

    int? iconId, labelId;
    String? labelRaw;
    ApkRes.walkXml(Uint8List.fromList(man), (el, attrs) {
      if (el != 'application') return;
      for (final at in attrs) {
        if (at.resId == 0x01010002 || (at.name == 'icon' && iconId == null)) {
          if (at.type == 0x01) iconId = at.data;
        }
        if (at.resId == 0x01010001 || at.name == 'label') {
          if (at.type == 0x01) {
            labelId = at.data;
          } else if (at.raw != null) {
            labelRaw = at.raw;
          }
        }
      }
    });
    final arsc = Arsc(Uint8List.fromList(res));

    final name = labelRaw ?? (labelId == null ? null : arsc.text(labelId!));
    if (name != null && name.trim().isNotEmpty) {
      final m = Map<String, dynamic>.from((Prefs.data['appLabels'] as Map?) ?? {});
      m[pkg] = name.trim();
      await Prefs.set('appLabels', m);
      notifyListeners();
    }

    if (iconId == null) return null;
    final path = arsc.file(iconId!);
    if (path == null) return null;
    await Directory(_dir).create(recursive: true);

    Future<String?> pull(String entry, String suffix) async {
      final bytes = await Adb.bytes(['exec-out', 'unzip', '-p', apk, entry]);
      if (bytes == null || bytes.length < 16) return null;
      final f = File('$_dir\\$pkg.$suffix');
      await f.writeAsBytes(bytes);
      return f.path;
    }

    if (!path.toLowerCase().endsWith('.xml')) {
      final f = await pull(path, 'icon');
      return f == null ? null : 'file:$f';
    }

    final xml = await Adb.bytes(['exec-out', 'unzip', '-p', apk, path]);
    if (xml == null) return null;
    int? fgId, bgId, bgColor;
    ApkRes.walkXml(Uint8List.fromList(xml), (el, attrs) {
      for (final at in attrs) {
        if (at.resId != 0x01010199 && at.name != 'drawable') continue;
        if (el == 'foreground' && at.type == 0x01) fgId = at.data;
        if (el == 'background') {
          if (at.type == 0x01) bgId = at.data;
          if (at.type >= 0x1c && at.type <= 0x1f) bgColor = at.data;
        }
      }
    });
    final fgPath = fgId == null ? null : arsc.file(fgId!);
    if (fgPath == null || fgPath.toLowerCase().endsWith('.xml')) return null;
    final fg = await pull(fgPath, 'fg');
    if (fg == null) return null;
    String bg = '';
    if (bgId != null) {
      bgColor ??= arsc.color(bgId!);
      final bp = arsc.file(bgId!);
      if (bp != null && !bp.toLowerCase().endsWith('.xml')) bg = await pull(bp, 'bg') ?? '';
    }
    return 'ad:$fg|$bg|${bgColor ?? 0xFFFFFFFF}';
  }
}

class AppIcon extends StatelessWidget {
  final AppEntry app;
  final double size;
  const AppIcon({super.key, required this.app, this.size = 46});

  @override
  Widget build(BuildContext context) => ListenableBuilder(
        listenable: IconStore.i,
        builder: (_, __) {
          final src = IconStore.i.lookup(app);
          final pal = _avatarPals[app.pkg.hashCode.abs() % _avatarPals.length];
          final Widget letter = DecoratedBox(
            decoration: BoxDecoration(
                gradient: LinearGradient(colors: pal, begin: Alignment.topLeft, end: Alignment.bottomRight)),
            child: Center(
                child: Text(app.title[0].toUpperCase(), style: t(size * .38, w: FontWeight.w800, c: Colors.white))),
          );
          Widget img = letter;
          if (src != null && src.startsWith('ad:')) {
            final p = src.substring(3).split('|');
            final col = Color(int.tryParse(p.length > 2 ? p[2] : '') ?? 0xFFFFFFFF);
            img = Stack(fit: StackFit.expand, children: [
              ColoredBox(color: col.withAlpha(255)),
              if (p.length > 1 && p[1].isNotEmpty)
                Image.file(File(p[1]), fit: BoxFit.cover, filterQuality: FilterQuality.high, errorBuilder: (_, __, ___) => const SizedBox()),
              Transform.scale(
                scale: 1.5,
                child: Image.file(File(p[0]),
                    fit: BoxFit.cover, filterQuality: FilterQuality.high, errorBuilder: (_, __, ___) => letter),
              ),
            ]);
          } else if (src != null && src.startsWith('file:')) {
            img = Image.file(File(src.substring(5)),
                fit: BoxFit.cover,
                gaplessPlayback: true,
                filterQuality: FilterQuality.high,
                errorBuilder: (_, __, ___) => letter);
          } else if (src != null && src.startsWith('url:')) {
            img = Image.network(src.substring(4),
                fit: BoxFit.cover, cacheWidth: 300, gaplessPlayback: true, errorBuilder: (_, __, ___) => letter);
          }
          return ClipRRect(
            borderRadius: BorderRadius.circular(size * .26),
            child: SizedBox(
              width: size,
              height: size,
              child: AnimatedSwitcher(duration: ms(450), child: KeyedSubtree(key: ValueKey(src), child: img)),
            ),
          );
        },
      );
}

class AppsPage extends StatefulWidget {
  const AppsPage({super.key});
  @override
  State<AppsPage> createState() => _AppsPageState();
}

class _AppsPageState extends State<AppsPage> {
  static List<AppEntry> cache = [];
  static bool loaded = false;
  static String? loadedFor;
  static int filter = 0;
  bool loading = false;
  String q = '';

  static const filters = ['Games & apps', 'Sideloaded', 'From the store', 'Meta system'];

  int _seen = 0;

  void _queue() {
    if (InstallQueue.i.finished == _seen) return;
    _seen = InstallQueue.i.finished;
    if (mounted && !loading) _load();
  }

  @override
  void initState() {
    super.initState();
    _seen = InstallQueue.i.finished;
    InstallQueue.i.addListener(_queue);
    IconStore.i.addListener(_names);
    if (!loaded || loadedFor != Device.i.info?.id) {
      cache = [];
      loaded = false;
      _load();
    }
  }

  void _names() {
    if (mounted) setState(() {});
  }

  @override
  void dispose() {
    InstallQueue.i.removeListener(_queue);
    IconStore.i.removeListener(_names);
    super.dispose();
  }

  Future<void> _load() async {
    setState(() => loading = true);
    loadedFor = Device.i.info?.id;
    final out = await Adb.shell('pm list packages -3 -i --show-versioncode');
    final list = <AppEntry>[];
    for (final l in out.split('\n')) {
      final pkg = RegExp(r'package:(\S+)').firstMatch(l)?.group(1);
      if (pkg == null) continue;
      list.add(AppEntry(pkg, RegExp(r'versionCode:(\d+)').firstMatch(l)?.group(1) ?? '',
          RegExp(r'installer=(\S+)').firstMatch(l)?.group(1) ?? ''));
    }
    list.sort((a, b) => a.title.toLowerCase().compareTo(b.title.toLowerCase()));
    cache = list;
    loaded = true;
    if (mounted) setState(() => loading = false);
  }

  bool _match(AppEntry a) => switch (filter) {
        1 => a.sideloaded && !a.system,
        2 => !a.sideloaded && !a.system,
        3 => a.system,
        _ => !a.system,
      };

  @override
  Widget build(BuildContext context) {
    final ql = q.toLowerCase();
    final list = cache
        .where(_match)
        .where((a) => ql.isEmpty || a.pkg.toLowerCase().contains(ql) || a.title.toLowerCase().contains(ql))
        .toList();
    int count(int f) {
      final keep = filter;
      filter = f;
      final n = cache.where(_match).length;
      filter = keep;
      return n;
    }

    return PageFrame(
      title: 'Apps',
      subtitle: loaded ? '${cache.where((a) => !a.system).length} games and apps on this headset.' : 'Reading your headset…',
      actions: [
        Field(width: 260, hint: 'Search apps', icon: Icons.search_rounded, onChanged: (v) => setState(() => q = v)),
        const SizedBox(width: 10),
        IconBtn(icon: Icons.refresh_rounded, tip: 'Refresh', onTap: _load),
      ],
      slivers: [
        SliverToBoxAdapter(
          child: Padding(
            padding: const EdgeInsets.only(bottom: 16),
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Wrap(spacing: 8, runSpacing: 8, children: [
          for (var f = 0; f < filters.length; f++)
            Chip2(
              label: loaded ? '${filters[f]}  ${count(f)}' : filters[f],
              selected: filter == f,
              onTap: () => setState(() => filter = f),
            ),
        ]),
            ]),
          ),
        ),
        if (loading && cache.isEmpty)
          SliverToBoxAdapter(
            child: Padding(
              padding: const EdgeInsets.symmetric(vertical: 70),
              child: Center(child: CircularProgressIndicator(color: Pal.a, strokeWidth: 2.4)),
            ),
          )
        else if (list.isEmpty)
          SliverToBoxAdapter(
            child: Padding(
              padding: const EdgeInsets.symmetric(vertical: 70),
              child: Center(
                  child: Text(q.isEmpty ? 'Nothing here yet.' : 'No apps match “$q”.', style: t(14, c: Pal.sub))),
            ),
          )
        else
          SliverList(
            delegate: SliverChildBuilderDelegate(
              (_, i) => FadeIn(
                key: ValueKey(list[i].pkg),
                delay: math.min(i, 10) * 30,
                child: AppRow(app: list[i], onRemoved: _load),
              ),
              childCount: list.length,
            ),
          ),
      ],
    );
  }
}

const _avatarPals = <List<Color>>[
  [Color(0xFF6366F1), Color(0xFFEC4899)],
  [Color(0xFF10B981), Color(0xFF3B82F6)],
  [Color(0xFFF59E0B), Color(0xFFEF4444)],
  [Color(0xFF8B5CF6), Color(0xFF22D3EE)],
  [Color(0xFF14B8A6), Color(0xFF84CC16)],
  [Color(0xFFF43F5E), Color(0xFFFB923C)],
];

class AppRow extends StatelessWidget {
  final AppEntry app;
  final VoidCallback onRemoved;
  const AppRow({super.key, required this.app, required this.onRemoved});

  Future<void> _launch(BuildContext c) async {
    await Adb.shell('monkey -p ${app.pkg} -c android.intent.category.LAUNCHER 1');
    toast(c, 'Opened ${app.title} in your headset', icon: Icons.play_circle_rounded);
  }

  Future<void> _stop(BuildContext c) async {
    await Adb.shell('am force-stop ${app.pkg}');
    toast(c, 'Closed ${app.title}', icon: Icons.stop_circle_rounded);
  }

  Future<void> _backup(BuildContext c) async {
    final out = await Adb.shell('pm path ${app.pkg}');
    final first = out.split('\n').map((e) => e.trim()).firstWhere((e) => e.startsWith('package:'), orElse: () => '');
    if (first.isEmpty) {
      toast(c, 'Couldn’t find the APK for ${app.title}', icon: Icons.error_rounded, color: Pal.bad);
      return;
    }
    toast(c, 'Saving ${app.title}…', icon: Icons.downloading_rounded);
    final dest = '$downloadsDir\\${app.pkg}.apk';
    final r = await Adb.run(['pull', first.substring(8), dest], timeout: const Duration(minutes: 15));
    final ok = r.contains('pulled');
    toast(c, ok ? 'Saved to Downloads as ${app.pkg}.apk' : r,
        icon: ok ? Icons.check_circle_rounded : Icons.error_rounded, color: ok ? null : Pal.bad);
  }

  Future<void> _uninstall(BuildContext c) async {
    if (!await confirm(c, 'Uninstall ${app.title}?', 'This removes the app and its data from your headset.',
        action: 'Uninstall', danger: true)) {
      return;
    }
    final r = await Adb.run(['uninstall', app.pkg], timeout: const Duration(minutes: 2));
    final ok = r.contains('Success');
    toast(c, ok ? 'Uninstalled ${app.title}' : r,
        icon: ok ? Icons.check_circle_rounded : Icons.error_rounded, color: ok ? null : Pal.bad);
    onRemoved();
  }

  @override
  Widget build(BuildContext context) {
    return Hover(
      builder: (h) => AnimatedContainer(
        duration: ms(240),
        curve: Curves.easeOutCubic,
        margin: const EdgeInsets.only(bottom: 6),
        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
        decoration: BoxDecoration(
          color: h ? Pal.card2 : Pal.card,
          borderRadius: BorderRadius.circular(16),
          border: Border.all(color: h ? Pal.a.withValues(alpha: .22) : Pal.stroke),
        ),
        child: Row(children: [
          AnimatedScale(scale: h ? 1.06 : 1, duration: ms(260), curve: Curves.easeOutCubic, child: AppIcon(app: app)),
          const SizedBox(width: 14),
          Expanded(
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Row(children: [
                Flexible(child: Text(app.title, style: t(14.5, w: FontWeight.w600), overflow: TextOverflow.ellipsis)),
                if (app.sideloaded && !app.system) ...[
                  const SizedBox(width: 8),
                  const Tag('Sideloaded', c: Pal.good),
                ],
              ]),
              const SizedBox(height: 2),
              Text(app.pkg, style: t(12, c: Pal.sub), overflow: TextOverflow.ellipsis),
            ]),
          ),
          if (app.ver.isNotEmpty) Tag('v${app.ver}', c: Pal.sub),
          const SizedBox(width: 14),
          IgnorePointer(
            ignoring: !h,
            child: AnimatedOpacity(
              opacity: h ? 1 : 0,
              duration: ms(240),
              child: AnimatedSlide(
                offset: Offset(h ? 0 : .08, 0),
                duration: ms(280),
                curve: Curves.easeOutCubic,
                child: Row(children: [
                  IconBtn(icon: Icons.play_arrow_rounded, tip: 'Open in headset', onTap: () => _launch(context)),
                  const SizedBox(width: 6),
                  IconBtn(icon: Icons.stop_rounded, tip: 'Close app', onTap: () => _stop(context)),
                  const SizedBox(width: 6),
                  IconBtn(icon: Icons.save_alt_rounded, tip: 'Save APK to PC', onTap: () => _backup(context)),
                  const SizedBox(width: 6),
                  IconBtn(icon: Icons.delete_rounded, tip: 'Uninstall', danger: true, onTap: () => _uninstall(context)),
                ]),
              ),
            ),
          ),
        ]),
      ),
    );
  }
}

class Stars extends StatefulWidget {
  final int value;
  final ValueChanged<int>? on;
