  State<Stars> createState() => _StarsState();
}

class _StarsState extends State<Stars> {
  int hover = 0;
  @override
  Widget build(BuildContext context) {
    final shown = hover > 0 ? hover : widget.value;
    return Row(mainAxisSize: MainAxisSize.min, children: [
      for (var i = 0; i < 5; i++)
        MouseRegion(
          cursor: widget.on == null ? MouseCursor.defer : SystemMouseCursors.click,
          onEnter: (_) {
            if (widget.on != null) setState(() => hover = i + 1);
          },
          onExit: (_) => setState(() => hover = 0),
          child: GestureDetector(
            onTap: widget.on == null ? null : () => widget.on!(i + 1),
            child: AnimatedScale(
              scale: hover == i + 1 ? 1.22 : 1,
              duration: ms(220),
              curve: Curves.easeOutBack,
              child: Padding(
                padding: const EdgeInsets.symmetric(horizontal: 2),
                child: AnimIcon(i < shown ? Icons.star_rounded : Icons.star_outline_rounded,
                    size: widget.size, color: i < shown ? Pal.gold : Pal.dim),
              ),
            ),
          ),
        ),
    ]);
  }
}

class _HoursSlider extends StatefulWidget {
  final RangeValues value;
  final double max;
  final ValueChanged<RangeValues> onCommit;
  const _HoursSlider({required this.value, required this.max, required this.onCommit});
  @override
  State<_HoursSlider> createState() => _HoursSliderState();
}

class _HoursSliderState extends State<_HoursSlider> {
  RangeValues? _drag;

  @override
  Widget build(BuildContext context) {
    final v = _drag ?? widget.value;
    final lo = v.start <= 0 ? 'No minimum' : '${v.start.round()} h';
    final hi = v.end >= widget.max ? 'No maximum' : '${v.end.round()} h';
    return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      Text('$lo to $hi', style: t(12.5, c: Pal.sub)),
      SliderTheme(
        data: SliderTheme.of(context).copyWith(
          trackHeight: 4,
          activeTrackColor: Pal.a,
          inactiveTrackColor: Colors.white.withValues(alpha: .12),
          thumbColor: Colors.white,
          overlayColor: Pal.a.withValues(alpha: .16),
          rangeThumbShape: const RoundRangeSliderThumbShape(enabledThumbRadius: 8, elevation: 0, pressedElevation: 0),
        ),
        child: RangeSlider(
          values: v,
          min: 0,
          max: widget.max,
          divisions: 200,
          onChanged: (x) => setState(() => _drag = x),
          onChangeEnd: (x) {
            setState(() => _drag = null);
            widget.onCommit(x);
          },
        ),
      ),
    ]);
  }
}

