class _SteamDetailState extends State<SteamDetail> {
  final shot = ValueNotifier<int>(0);
  bool more = false;
  final dlKey = GlobalKey();
  final revKey = GlobalKey();
  final galKey = GlobalKey();

  @override
  void initState() {
    super.initState();
    SteamStore.i.addListener(_on);
    SteamStore.i.details(widget.g);
    _restart();
  }

  void _on() {
    if (mounted) setState(() {});
  }

  @override
  void dispose() {
    _auto?.cancel();
    shot.dispose();
    SteamStore.i.removeListener(_on);
    super.dispose();
  }

  Timer? _auto;

  void _restart() {
    _auto?.cancel();
    _auto = Timer.periodic(const Duration(seconds: 3), (_) {
      if (!mounted) return;
      final box = galKey.currentContext?.findRenderObject();
      if (box is RenderBox && box.attached) {
        final y = box.localToGlobal(Offset.zero).dy;
        if (y + box.size.height < 0 || y > MediaQuery.sizeOf(context).height) return;
      }
      final n = math.min(widget.g.shots.length, 8);
      if (n > 1) shot.value = (shot.value + 1) % n;
    });
  }

  void _toReviews() {
    final c = revKey.currentContext;
    if (c != null) {
      Scrollable.ensureVisible(c, duration: ms(750), curve: Curves.easeInOutCubic, alignment: .1);
    }
  }

  void _viewer(String url) => _sheet<void>(
        context,
        (ctx) => Column(mainAxisSize: MainAxisSize.min, children: [
          ClipRRect(
            borderRadius: BorderRadius.circular(14),
            child: AspectRatio(aspectRatio: 16 / 9, child: NetImg(url, fit: BoxFit.contain)),
          ),
          const SizedBox(height: 16),
          Align(alignment: Alignment.centerRight, child: Btn(label: 'Close', onTap: () => Navigator.pop(ctx))),
        ]),
        width: 980,
      );

