class FEntry {
  final String name;
  final bool dir;
  FEntry(this.name, this.dir);
}

class FilesPage extends StatefulWidget {
  const FilesPage({super.key});
  @override
  State<FilesPage> createState() => _FilesPageState();
}

class _FilesPageState extends State<FilesPage> {
  static String cwd = '/sdcard';
  List<FEntry> items = [];
  bool loading = false;
  String? error;
  final qCtl = TextEditingController();
  String q = '';
  int _seen = 0;

  List<FEntry> get shown {
    final s = q.trim().toLowerCase();
    return s.isEmpty ? items : items.where((e) => e.name.toLowerCase().contains(s)).toList();
  }

  void _queue() {
    if (InstallQueue.i.finished == _seen) return;
    _seen = InstallQueue.i.finished;
    if (mounted && !loading) _load();
  }

  static const quick = <(String, String)>[
    ('Internal storage', '/sdcard'),
    ('Download', '/sdcard/Download'),
    ('Screenshots', '/sdcard/Oculus/Screenshots'),
    ('Recordings', '/sdcard/Oculus/VideoShots'),
    ('Movies', '/sdcard/Movies'),
    ('OBB data', '/sdcard/Android/obb'),
  ];

  @override
  void initState() {
    super.initState();
    _seen = InstallQueue.i.finished;
    InstallQueue.i.addListener(_queue);
    filesDrop.addListener(_dropped);
    _load();
  }

  @override
  void dispose() {
    InstallQueue.i.removeListener(_queue);
    filesDrop.removeListener(_dropped);
    qCtl.dispose();
    super.dispose();
  }

  String _join(String name) => cwd.endsWith('/') ? '$cwd$name' : '$cwd/$name';

  Future<void> _open(String p) async {
    cwd = p;
    qCtl.clear();
    q = '';
    await _load();
  }

  Future<void> _load() async {
    setState(() {
      loading = true;
      error = null;
    });
    final out = await Adb.shell('ls -p "$cwd/"');
    final list = <FEntry>[];
    String? err;
    if (out.contains('No such file') || out.contains('Permission denied') || out.startsWith('error')) {
      err = out.split('\n').first;
    } else {
      for (final l in out.split('\n')) {
        final s = l.trimRight();
        if (s.isEmpty) continue;
        list.add(s.endsWith('/') ? FEntry(s.substring(0, s.length - 1), true) : FEntry(s, false));
      }
      list.sort((a, b) {
        if (a.dir != b.dir) return a.dir ? -1 : 1;
        return a.name.toLowerCase().compareTo(b.name.toLowerCase());
      });
    }
    if (!mounted) return;
    setState(() {
      items = list;
      error = err;
      loading = false;
    });
  }

  void _dropped() {
    final p = filesDrop.value;
    if (p == null) return;
    filesDrop.value = null;
    _send(p);
  }

  Future<void> _upload() async => _send(await Pick.files(android: false));

  Future<void> _send(List<String> files) async {
    if (files.isEmpty) return;
    toast(context, 'Uploading ${files.length} file${files.length == 1 ? '' : 's'}…', icon: Icons.upload_rounded);
    for (final f in files) {
      await Adb.run(['push', f, '$cwd/'], timeout: const Duration(hours: 1));
    }
    if (!mounted) return;
    toast(context, 'Uploaded to ${cwd.split('/').last}');
    _load();
  }

  Future<void> _newFolder() async {
    final name = await askText(context, 'New folder', 'Folder name', 'Create folder');
    if (name == null || name.isEmpty) return;
    await Adb.shell('mkdir -p "${_join(name)}"');
    _load();
  }

  Future<void> _download(FEntry e) async {
    toast(context, 'Downloading ${e.name}…', icon: Icons.downloading_rounded);
    final r = await Adb.run(['pull', _join(e.name), downloadsDir], timeout: const Duration(hours: 1));
    if (!mounted) return;
    final ok = r.contains('pulled');
    toast(context, ok ? 'Saved ${e.name} to Downloads' : r,
        icon: ok ? Icons.check_circle_rounded : Icons.error_rounded, color: ok ? null : Pal.bad);
  }

  Future<void> _delete(FEntry e) async {
    if (!await confirm(
        context,
        'Delete ${e.name}?',
        e.dir
            ? 'This folder and everything inside it will be removed from the headset.'
            : 'This file will be removed from the headset.',
        action: 'Delete',
        danger: true)) {
      return;
    }
    await Adb.shell('rm -rf "${_join(e.name)}"');
    _load();
  }

  IconData _iconFor(FEntry e) {
    if (e.dir) return Icons.folder_rounded;
    final n = e.name.toLowerCase();
    if (n.endsWith('.apk')) return Icons.android_rounded;
    if (n.endsWith('.obb')) return Icons.inventory_2_rounded;
    if (n.endsWith('.png') || n.endsWith('.jpg') || n.endsWith('.jpeg')) return Icons.image_rounded;
    if (n.endsWith('.mp4') || n.endsWith('.mkv') || n.endsWith('.webm')) return Icons.movie_rounded;
    if (n.endsWith('.zip') || n.endsWith('.7z') || n.endsWith('.rar')) return Icons.folder_zip_rounded;
    return Icons.insert_drive_file_rounded;
  }

  @override
  Widget build(BuildContext context) {
    final parts = cwd.split('/').where((s) => s.isNotEmpty).toList();
    return PageFrame(
      title: 'Files',
      subtitle: 'Browse your headset and move files in both directions.',
      actions: [
        Btn(label: 'New folder', icon: Icons.create_new_folder_rounded, onTap: _newFolder),
        const SizedBox(width: 10),
        Btn(label: 'Upload', icon: Icons.upload_rounded, primary: true, onTap: _upload),
      ],
      slivers: [
        SliverToBoxAdapter(
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Wrap(spacing: 8, runSpacing: 8, children: [
          for (final qk in quick) Chip2(label: qk.$1, selected: cwd == qk.$2, onTap: () => _open(qk.$2)),
        ]),
        const SizedBox(height: 16),
        Row(children: [
          IconBtn(
            icon: Icons.arrow_upward_rounded,
            tip: 'Up one folder',
            onTap: () {
              if (parts.length > 1) _open('/${parts.sublist(0, parts.length - 1).join('/')}');
            },
          ),
          const SizedBox(width: 12),
          Expanded(
            child: Wrap(crossAxisAlignment: WrapCrossAlignment.center, children: [
              for (var i = 0; i < parts.length; i++) ...[
                if (i > 0) const Icon(Icons.chevron_right_rounded, size: 18, color: Pal.dim),
                Hover(
                  onTap: () => _open('/${parts.sublist(0, i + 1).join('/')}'),
                  builder: (h) => Padding(
                    padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 4),
                    child: AnimatedDefaultTextStyle(
                      duration: ms(200),
                      style: t(14,
                          w: i == parts.length - 1 ? FontWeight.w700 : FontWeight.w500,
                          c: i == parts.length - 1 || h ? Pal.text : Pal.sub),
                      child: Text(i == 0 && parts[0] == 'sdcard' ? 'Internal storage' : parts[i]),
                    ),
                  ),
                ),
              ],
            ]),
          ),
          Text('${items.length} items', style: t(12.5, c: Pal.sub)),
          const SizedBox(width: 12),
          IconBtn(icon: Icons.refresh_rounded, tip: 'Refresh', onTap: _load),
        ]),
        const SizedBox(height: 14),
        Field(
          c: qCtl,
          hint: 'Search in ${cwd == '/sdcard' ? 'internal storage' : cwd.split('/').last}',
          icon: Icons.search_rounded,
          onChanged: (v) => setState(() => q = v),
        ),
        const SizedBox(height: 14),
          ]),
        ),
        if (loading)
          SliverToBoxAdapter(
            child: Padding(
              padding: const EdgeInsets.symmetric(vertical: 70),
              child: Center(child: CircularProgressIndicator(color: Pal.a, strokeWidth: 2.4)),
            ),
          )
        else if (error != null)
          SliverToBoxAdapter(
            child: Padding(
              padding: const EdgeInsets.symmetric(vertical: 70),
              child: Center(child: Text(error!, style: t(14, c: Pal.bad))),
            ),
          )
        else if (shown.isEmpty)
          SliverToBoxAdapter(
            child: Padding(
              padding: const EdgeInsets.symmetric(vertical: 70),
              child: Center(
                  child: Text(q.trim().isEmpty ? 'This folder is empty. Use Upload to add files.' : 'Nothing here matches “${q.trim()}”.',
                      style: t(14, c: Pal.sub))),
            ),
          )
        else
          SliverList(
            delegate: SliverChildBuilderDelegate(
              (_, i) {
                                  final e = shown[i];
                                  return Hover(
                                    onTap: e.dir ? () => _open(_join(e.name)) : null,
                                    builder: (h) => AnimatedContainer(
                                      duration: ms(200),
                                      curve: Curves.easeOutCubic,
                                      margin: const EdgeInsets.only(bottom: 4),
                                      padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 9),
                                      decoration: BoxDecoration(
                                        color: h ? Pal.card2 : Colors.transparent,
                                        borderRadius: BorderRadius.circular(13),
                                      ),
                                      child: Row(children: [
                                        Container(
                                          width: 38,
                                          height: 38,
                                          decoration: BoxDecoration(
                                            color: (e.dir ? Pal.a : Pal.sub).withValues(alpha: .12),
                                            borderRadius: BorderRadius.circular(11),
                                          ),
                                          child: Icon(_iconFor(e), size: 19, color: e.dir ? Pal.a : Pal.sub),
                                        ),
                                        const SizedBox(width: 14),
                                        Expanded(
                                            child: Text(e.name,
                                                style: t(14, w: FontWeight.w500), overflow: TextOverflow.ellipsis)),
                                        IgnorePointer(
                                          ignoring: !h,
                                          child: AnimatedOpacity(
                                            opacity: h ? 1 : 0,
                                            duration: ms(200),
                                            child: Row(children: [
                                              IconBtn(
                                                  icon: Icons.download_rounded,
                                                  tip: 'Download to PC',
                                                  onTap: () => _download(e)),
                                              const SizedBox(width: 6),
                                              IconBtn(
                                                  icon: Icons.delete_rounded,
                                                  tip: 'Delete',
                                                  danger: true,
                                                  onTap: () => _delete(e)),
                                            ]),
                                          ),
                                        ),
                                        if (e.dir) ...[
                                          const SizedBox(width: 8),
                                          AnimatedSlide(
                                            offset: Offset(h ? .2 : 0, 0),
                                            duration: ms(220),
                                            child: const Icon(Icons.chevron_right_rounded, color: Pal.dim, size: 20),
                                          ),
                                        ],
                                      ]),
                                    ),
                                  );
              },
              childCount: shown.length,
            ),
          ),
      ],
    );
  }
}

class TweaksPage extends StatefulWidget {
  const TweaksPage({super.key});
  @override
  State<TweaksPage> createState() => _TweaksPageState();
}

class _TweaksPageState extends State<TweaksPage> {
  static final sel = <String, int>{'eye': 1, 'timeout': 3};
  static bool dynFov = true, prox = false, guardian = false, experimental = false;
  final pasteCtl = TextEditingController();

  @override
  void initState() {
    super.initState();
    _sync();
  }

  @override
  void dispose() {
    pasteCtl.dispose();
    super.dispose();
  }

  Future<void> _sync() async {
    const keys = {
      'hz': 'debug.oculus.refreshRate',
      'fov': 'debug.oculus.foveation.level',
      'dyn': 'debug.oculus.foveation.dynamic',
      'tex': 'debug.oculus.textureWidth',
      'chroma': 'debug.oculus.forceChroma',
      'cpu': 'debug.oculus.cpuLevel',
      'gpu': 'debug.oculus.gpuLevel',
    };
    final out = await Adb.shell(keys.entries.map((e) => 'echo ${e.key}=\$(getprop ${e.value})').join('; '));
    final got = <String, String>{};
    for (final l in out.split('\n')) {
      final i = l.indexOf('=');
      if (i > 0) got[l.substring(0, i).trim()] = l.substring(i + 1).trim();
    }
    if (!mounted || got.isEmpty) return;
    int pick(String k, List<String> values) {
      final i = values.indexOf(got[k] ?? '');
      return i < 0 ? 0 : i;
    }

    int level(String k) {
      final v = int.tryParse(got[k] ?? '');
      return v == null ? 0 : (v + 1).clamp(0, 6);
    }

    setState(() {
      sel['hz'] = pick('hz', ['', '72', '90', '120', '207']);
      sel['fov'] = pick('fov', ['', '0', '1', '2', '3', '4']);
      sel['tex'] = pick('tex', ['', '1024', '1440', '1832', '2048', '2560']);
      sel['chroma'] = pick('chroma', ['', '1', '0']);
      sel['cpu'] = level('cpu');
      sel['gpu'] = level('gpu');
      dynFov = got['dyn'] != '0';
    });
  }

  Future<void> prop(String k, String v) => Adb.shell('setprop $k ${v.isEmpty ? '""' : v}');

  Widget seg(String key, String title, String desc, List<String> labels, Future<void> Function(int) apply,
          {Future<bool> Function(int)? ask, String? accent}) =>
      SRow(
        title: title,
        desc: desc,
        accent: accent,
        trailing: Seg(
          width: 440,
          items: labels,
          sel: sel[key] ?? 0,
          on: (i) async {
            if (ask != null && !await ask(i)) return;
            setState(() => sel[key] = i);
            await apply(i);
            if (mounted) toast(context, '$title set to ${labels[i]}', icon: Icons.tune_rounded);
          },
        ),
      );

  Widget toggle(String title, String desc, bool v, Future<void> Function(bool) apply, void Function(bool) store) => SRow(
        title: title,
        desc: desc,
        trailing: Toggle(
          v: v,
          on: (nv) async {
            setState(() => store(nv));
            await apply(nv);
            if (mounted) toast(context, '$title ${nv ? 'on' : 'off'}', icon: Icons.tune_rounded);
          },
        ),
      );

  Future<void> _paste() async {
    final txt = pasteCtl.text;
    if (txt.isEmpty) return;
    final s = txt.replaceAll(' ', '%s').replaceAll("'", r"'\''");
    await Adb.shell("input text '$s'");
    pasteCtl.clear();
    if (mounted) toast(context, 'Typed into your headset', icon: Icons.keyboard_rounded);
  }

  Future<void> _resetAll() async {
    for (final k in [
      'debug.oculus.refreshRate',
      'debug.oculus.foveation.level',
      'debug.oculus.textureWidth',
      'debug.oculus.textureHeight',
      'debug.oculus.forceChroma',
      'debug.oculus.cpuLevel',
      'debug.oculus.gpuLevel',
    ]) {
      await prop(k, '');
    }
    setState(() => sel.removeWhere((k, _) => !['eye', 'timeout'].contains(k)));
    if (mounted) toast(context, 'Rendering and performance are back to app defaults');
  }

  @override
  Widget build(BuildContext context) {
    return PageFrame(
      title: 'Device settings',
      subtitle: 'Tune refresh rate, rendering and capture. Changes apply instantly.',
      actions: [Btn(label: 'Reset to defaults', icon: Icons.settings_backup_restore_rounded, onTap: _resetAll)],
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Panel(
          pad: const EdgeInsets.symmetric(horizontal: 18, vertical: 14),
          r: 14,
          color: Colors.white.withValues(alpha: .03),
          child: Row(children: [
            const Icon(Icons.lightbulb_rounded, size: 18, color: Pal.warn),
            const SizedBox(width: 12),
            Expanded(
              child: Text(
                  'Rendering tweaks affect apps you open after the change, and reset when the headset restarts.',
                  style: t(13, c: Pal.sub)),
            ),
          ]),
        ),
        const SizedBox(height: 18),
        Group(title: 'Rendering', icon: Icons.auto_awesome_rounded, delay: 0, children: [
          seg('hz', 'Refresh rate',
              'Higher feels smoother but uses more GPU time and battery. 207 Hz is Quest 3 only and needs Horizon OS v2.7 or later.',
              ['Default', '72 Hz', '90 Hz', '120 Hz', '207 Hz'],
              (i) => prop('debug.oculus.refreshRate', ['', '72', '90', '120', '207'][i]),
              ask: (i) async => i != 4 || await warn207(context),
              accent: '90 Hz is the sweet spot.'),
          toggle('Dynamic foveation', 'Let the headset choose how much to soften the lens edges based on load.', dynFov,
              (v) => prop('debug.oculus.foveation.dynamic', v ? '1' : '0'), (v) => dynFov = v),
          seg('fov', 'Foveation level', 'Higher means more performance, lower means sharper edges.',
              ['Default', 'Off', 'Low', 'Medium', 'High', 'Max'],
              (i) => prop('debug.oculus.foveation.level', ['', '0', '1', '2', '3', '4'][i])),
          seg('tex', 'Texture resolution', 'Per-eye render size. Bigger looks sharper but costs GPU time.',
              ['Default', '1024', '1440', '1832', '2048', '2560'], (i) async {
            final v = ['', '1024', '1440', '1832', '2048', '2560'][i];
            await prop('debug.oculus.textureWidth', v);
            await prop('debug.oculus.textureHeight', v);
          }),
          seg('chroma', 'Chromatic aberration correction', 'Force it on, off, or let each app decide.',
              ['Default', 'On', 'Off'], (i) => prop('debug.oculus.forceChroma', ['', '1', '0'][i])),
        ]),
        Group(title: 'Performance', icon: Icons.speed_rounded, delay: 70, children: [
          seg('cpu', 'CPU level', 'Higher levels boost performance but add heat and drain the battery faster.',
              ['Default', '0', '1', '2', '3', '4', '5'],
              (i) => prop('debug.oculus.cpuLevel', i == 0 ? '' : '${i - 1}')),
          seg('gpu', 'GPU level', 'Higher levels boost performance but add heat and drain the battery faster.',
              ['Default', '0', '1', '2', '3', '4', '5'],
              (i) => prop('debug.oculus.gpuLevel', i == 0 ? '' : '${i - 1}')),
        ]),
        Group(title: 'Screen capture', icon: Icons.videocam_rounded, delay: 140, children: [
          seg('cres', 'Capture resolution', 'Size of recordings and casting.',
              ['1024²', '1280×720', '1920×1080', '1600²'], (i) async {
            const w = ['1024', '1280', '1920', '1600'];
            const h = ['1024', '720', '1080', '1600'];
            await prop('debug.oculus.capture.width', w[i]);
            await prop('debug.oculus.capture.height', h[i]);
          }),
          seg('cfps', 'Capture frame rate', 'Frames per second for recordings and casting.',
              ['24 fps', '30 fps', '60 fps', '72 fps'],
              (i) => prop('debug.oculus.capture.fps', ['24', '30', '60', '72'][i])),
          seg('cbit', 'Capture bitrate', 'Higher means better quality and bigger files.',
              ['5 Mbps', '10 Mbps', '15 Mbps', '20 Mbps'],
              (i) => prop('debug.oculus.capture.bitrate', ['5000000', '10000000', '15000000', '20000000'][i])),
          seg('eye', 'Capture eye', 'Record the left eye, the right eye, or both side by side.',
              ['Left', 'Right', 'Both'], (i) => prop('debug.oculus.screenCaptureEye', ['0', '1', '2'][i])),
        ]),
        Group(title: 'Display and power', icon: Icons.battery_charging_full_rounded, delay: 210, children: [
          toggle(
              'Keep awake off-head',
              'Turns off the proximity sensor so the headset stays on when you take it off. Resets on restart.',
              prox,
              (v) => Adb.shell(v
                  ? 'am broadcast -a com.oculus.vrpowermanager.prox_close'
                  : 'am broadcast -a com.oculus.vrpowermanager.automation_disable'),
              (v) => prox = v),
          seg('timeout', 'Screen timeout', 'How long the headset waits without input before sleeping.',
              ['15 s', '1 min', '5 min', '30 min'],
              (i) => Adb.shell('settings put system screen_off_timeout ${[15000, 60000, 300000, 1800000][i]}')),
          SRow(
            title: 'Restart headset',
            desc: 'The connection drops while it restarts. Wireless connections may need reconnecting.',
            trailing: Btn(
              label: 'Restart',
              icon: Icons.restart_alt_rounded,
              danger: true,
              onTap: () async {
                if (await confirm(context, 'Restart headset?', 'The connection drops while it restarts.',
                    action: 'Restart', danger: true)) {
                  await Adb.run(['reboot']);
                }
              },
            ),
          ),
        ]),
        Group(title: 'Experimental', icon: Icons.science_rounded, delay: 280, children: [
          toggle('Experimental features', 'Unlock Meta’s experimental toggles, like early passthrough features.',
              experimental, (v) => prop('debug.oculus.experimentalEnabled', v ? '1' : '0'), (v) => experimental = v),
          toggle('Pause Guardian', 'Turns off the boundary. Clear your space first, or you can walk into walls.',
              guardian, (v) => prop('debug.oculus.guardian_pause', v ? '1' : '0'), (v) => guardian = v),
          SRow(
            title: 'Type into headset',
            desc: 'Send text as keystrokes. Handy for long passwords and links.',
            trailing: Row(mainAxisSize: MainAxisSize.min, children: [
              Field(c: pasteCtl, width: 240, hint: 'Text to send', onSubmit: (_) => _paste()),
              const SizedBox(width: 8),
              Btn(label: 'Send', icon: Icons.send_rounded, onTap: _paste),
            ]),
          ),
        ]),
      ]),
    );
  }
}

class Cast extends ChangeNotifier {
  static final Cast i = Cast._();
  Cast._();

  Process? _view, _rec;
  String? _recOn;
  bool _demoView = false, _demoRec = false;
  DateTime? recSince;
  bool shooting = false;
  List<File> files = [];

  bool get casting => _view != null || _demoView;
  bool get recording => _rec != null || _demoRec;

  static String? _path;
  static String? get path {
    if (_path != null) return _path;
    final exeDir = File(Platform.resolvedExecutable).parent.path;
    for (final c in ['$exeDir\\scrcpy\\scrcpy.exe', r'C:\src\scrcpy\scrcpy.exe']) {
      if (File(c).existsSync()) return _path = c;
    }
    return null;
  }

  static bool get ready => kDemo || path != null;

  static String get dir => '${Platform.environment['USERPROFILE'] ?? r'C:\Users\Public'}\\Pictures\\Lightcat';

  static Map<String, dynamic> get opts => Map<String, dynamic>.from((Prefs.data['cast'] as Map?) ?? {});
  static int opt(String k, int d) => (opts[k] as num?)?.toInt() ?? d;
  static bool flag(String k) => opts[k] == true;

  static Future<void> setOpt(String k, Object v) {
    final m = opts;
    m[k] = v;
    return Prefs.set('cast', m);
  }

  static String _stamp(String name) {
    final n = DateTime.now();
    String two(int v) => v.toString().padLeft(2, '0');
    return '$name ${n.year}-${two(n.month)}-${two(n.day)} ${two(n.hour)}-${two(n.minute)}-${two(n.second)}';
  }

  void scan() {
    try {
      final d = Directory(dir);
      files = !d.existsSync()
          ? []
          : (d.listSync().whereType<File>().toList()
            ..sort((a, b) => b.lastModifiedSync().compareTo(a.lastModifiedSync())));
    } catch (_) {
      files = [];
    }
    notifyListeners();
  }

  Future<List<String>> _args(DeviceInfo d) async {
    final a = <String>[
      '-s',
      d.serial,
      '--video-codec=h264',
      '--max-size=${const [1280, 1920, 2560][opt('size', 1)]}',
      '--video-bit-rate=${const [8, 16, 24][opt('rate', 1)]}M',
      '--max-fps=${const [30, 60, 72, 90][opt('fps', 1)]}',
    ];
    final eye = opt('eye', 1);
    if (eye > 0) {
      final m = RegExp(r'(\d+)x(\d+)').firstMatch(await Adb.shell('wm size', on: d.serial));
      if (m != null) {
        final w = int.parse(m.group(1)!) ~/ 2, h = int.parse(m.group(2)!);
        a.add('--crop=$w:$h:${eye == 2 ? w : 0}:0');
      }
    }
    if (!flag('sound')) a.add('--no-audio');
    return a;
  }

  Future<Process> _start(List<String> args, void Function(int code, String err) done) async {
    final p = await Process.start(path!, args,
        workingDirectory: File(path!).parent.path,
        environment: {if (Adb.path != 'adb') 'ADB': Adb.path});
    final err = StringBuffer();
    p.stdout.drain<void>();
    p.stderr.transform(utf8.decoder).listen(err.write);
    p.exitCode.then((c) => done(c, err.toString()));
    return p;
  }

  static String _why(String err) {
    final l = err.split('\n').map((e) => e.trim()).where((e) => e.startsWith('ERROR')).toList();
    if (l.isEmpty) return 'scrcpy closed unexpectedly';
    final s = l.first.replaceFirst(RegExp(r'^ERROR:\s*'), '');
    return s.length > 120 ? '${s.substring(0, 120)}…' : s;
  }

  Future<String?> startView() async {
    final d = Device.i.info;
    if (d == null || casting) return null;
    if (kDemo) {
      _demoView = true;
      notifyListeners();
      return null;
    }
    if (path == null) return 'scrcpy is missing. Reinstall Lightcat to get it back.';
    final args = await _args(d);
    args.add('--window-title=${d.name} · Lightcat');
    if (!flag('control')) args.add('--no-control');
    final t0 = DateTime.now();
    try {
      _view = await _start(args, (code, err) {
        _view = null;
        notifyListeners();
        if (code != 0 && DateTime.now().difference(t0).inSeconds < 5) {
          notifyUser('Casting stopped', _why(err), icon: Icons.cast_rounded, color: Pal.bad);
        }
      });
    } catch (e) {
      return 'Could not start scrcpy';
    }
    notifyListeners();
    return null;
  }

  Future<void> stopView() async {
    if (_demoView) {
      _demoView = false;
      notifyListeners();
      return;
    }
    final p = _view;
    if (p == null) return;
    await Process.run('taskkill', ['/PID', '${p.pid}', '/T']);
    await Future.delayed(const Duration(seconds: 2));
    if (_view == p) await Process.run('taskkill', ['/PID', '${p.pid}', '/T', '/F']);
  }

  Future<String?> startRec() async {
    final d = Device.i.info;
    if (d == null || recording) return null;
    if (kDemo) {
      _demoRec = true;
      recSince = DateTime.now();
      notifyListeners();
      return null;
    }
    if (path == null) return 'scrcpy is missing. Reinstall Lightcat to get it back.';
    await Directory(dir).create(recursive: true);
    final file = '$dir\\${_stamp(d.name)}.mp4';
    final args = await _args(d);
    args.addAll(
        ['--verbosity=warn', '--no-window', '--no-playback', '--no-control', '--record=$file', '--record-format=mp4']);
    _recOn = d.serial;
    final t0 = DateTime.now();
    try {
      _rec = await _start(args, (code, err) {
        _rec = null;
        recSince = null;
        scan();
        if (code != 0 && DateTime.now().difference(t0).inSeconds < 5) {
          notifyUser('Recording stopped', _why(err), icon: Icons.videocam_rounded, color: Pal.bad);
        }
      });
    } catch (e) {
      return 'Could not start scrcpy';
    }
    recSince = DateTime.now();
    notifyListeners();
    return null;
  }

  Future<void> stopRec() async {
    if (_demoRec) {
      _demoRec = false;
      recSince = null;
      notifyListeners();
      return;
    }
    final p = _rec;
    if (p == null) return;
    await Adb.shell("pkill -f 'scrcpy.Server.*log_level=warn'", on: _recOn);
    for (var n = 0; n < 20 && _rec == p; n++) {
      await Future.delayed(const Duration(milliseconds: 250));
    }
    if (_rec == p) await Process.run('taskkill', ['/PID', '${p.pid}', '/T', '/F']);
  }

  Future<void> stopAll() async {
    await stopRec();
    await stopView();
  }

  Future<String?> shot() async {
    final d = Device.i.info;
    if (d == null || shooting) return null;
    shooting = true;
    notifyListeners();
    try {
      await Directory(dir).create(recursive: true);
      final base = '$dir\\${_stamp(d.name)}';
      if (kDemo) {
        await File('$base.png').writeAsBytes(await _demoShot());
        return '$base.png';
      }
      const shots = '/sdcard/Oculus/Screenshots';
      Set<String> list(String out) => out.split('\n').map((e) => e.trim()).where((e) => e.contains('.')).toSet();
      final before = list(await Adb.shell('ls $shots'));
      await Adb.shell('am startservice -n com.oculus.metacam/.capture.CaptureService -a TAKE_SCREENSHOT');
      String? fresh;
      for (var n = 0; n < 12 && fresh == null; n++) {
        await Future.delayed(const Duration(milliseconds: 500));
        fresh = list(await Adb.shell('ls $shots')).difference(before).firstOrNull;
      }
      if (fresh != null) {
        await Future.delayed(const Duration(milliseconds: 600));
        final local = '$base.${fresh.split('.').last}';
        final out = await Adb.run(['pull', '$shots/$fresh', local]);
        if (out.contains('pulled')) return local;
      }
      const tmp = '/data/local/tmp/lightcat_shot.png';
      await Adb.shell('screencap -p $tmp');
      final size = int.tryParse((await Adb.shell('stat -c %s $tmp')).trim()) ?? 0;
      var ok = false;
      if (size > 0) ok = (await Adb.run(['pull', tmp, '$base.png'])).contains('pulled');
      await Adb.shell('rm -f $tmp');
      return ok ? '$base.png' : null;
    } finally {
      shooting = false;
      scan();
    }
  }

  static Future<List<int>> _demoShot() async {
    const w = 1280.0, h = 720.0;
    final rec = ui.PictureRecorder();
    final c = Canvas(rec);
    c.drawRect(
        const Rect.fromLTWH(0, 0, w, h),
        Paint()
          ..shader = ui.Gradient.linear(Offset.zero, const Offset(w, h), [const Color(0xFF101626), Pal.card2]));
    for (var k = 0; k < 4; k++) {
      c.drawCircle(Offset(w * (.2 + k * .2), h * (.35 + (k % 2) * .3)), 120.0 - k * 18,
          Paint()..color = (k.isEven ? Pal.a : Pal.b).withValues(alpha: .22));
    }
    final img = await rec.endRecording().toImage(w.toInt(), h.toInt());
    final png = await img.toByteData(format: ui.ImageByteFormat.png);
    return png!.buffer.asUint8List();
  }
}

class CastPage extends StatefulWidget {
  const CastPage({super.key});
  @override
  State<CastPage> createState() => _CastPageState();
}

class _CastPageState extends State<CastPage> {
  @override
  void initState() {
    super.initState();
    Cast.i.scan();
  }

  void _err(String? e) {
    if (e != null && mounted) toast(context, e, icon: Icons.error_rounded, color: Pal.bad);
  }

  Future<void> _shot() async {
    final f = await Cast.i.shot();
    if (!mounted) return;
    if (f == null) {
      toast(context, 'Could not take a screenshot. Put the headset on so the display is awake.',
          icon: Icons.screenshot_monitor_rounded, color: Pal.warn);
    } else {
      toast(context, 'Screenshot saved to Pictures\\Lightcat', icon: Icons.screenshot_monitor_rounded);
    }
  }

  Future<void> _rec() async {
    final c = Cast.i;
    if (!c.recording) {
      _err(await c.startRec());
      return;
    }
    await c.stopRec();
    if (mounted) {
      toast(context, kDemo ? 'Demo build: nothing was recorded' : 'Clip saved to Pictures\\Lightcat',
          icon: Icons.videocam_rounded);
    }
  }

  Widget opt(String key, String title, String desc, List<String> labels, int def) => SRow(
        title: title,
        desc: desc,
        trailing: Seg(
          width: 360,
          items: labels,
          sel: Cast.opt(key, def),
          on: (i) async {
            await Cast.setOpt(key, i);
            setState(() {});
          },
        ),
      );

  Widget flag(String key, String title, String desc) => SRow(
        title: title,
        desc: desc,
        trailing: Toggle(
          v: Cast.flag(key),
          on: (v) async {
            await Cast.setOpt(key, v);
            setState(() {});
          },
        ),
      );

  @override
  Widget build(BuildContext context) {
    return PageFrame(
      title: 'Cast',
      subtitle: 'See your headset on this PC, take screenshots and record clips.',
      actions: [
        Btn(
            label: 'Open folder',
            icon: Icons.folder_open_rounded,
            onTap: () async {
              await Directory(Cast.dir).create(recursive: true);
              await Process.run('explorer', [Cast.dir]);
            }),
      ],
      child: ListenableBuilder(
        listenable: Cast.i,
        builder: (_, __) {
          final c = Cast.i;
          return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            if (!Cast.ready) ...[
              Panel(
                pad: const EdgeInsets.symmetric(horizontal: 18, vertical: 14),
                r: 14,
                color: Pal.warn.withValues(alpha: .08),
                border: Pal.warn.withValues(alpha: .25),
                child: Row(children: [
                  const Icon(Icons.warning_amber_rounded, size: 18, color: Pal.warn),
                  const SizedBox(width: 12),
                  Expanded(
                    child: Text('scrcpy is missing, so casting and recording are off. Reinstall Lightcat to get it back.',
                        style: t(13, c: Pal.sub)),
                  ),
                ]),
              ),
              const SizedBox(height: 18),
            ],
            FadeIn(
              child: Row(children: [
                Expanded(
                  child: _CastCard(
                    icon: Icons.cast_rounded,
                    title: c.casting ? 'Casting now' : 'Cast to PC',
                    desc: c.casting
                        ? 'Close the cast window or press stop to end it.'
                        : 'Opens a live window of what you see in the headset.',
                    live: c.casting,
                    child: greyed(Btn(
                      label: c.casting ? 'Stop casting' : 'Start casting',
                      icon: c.casting ? Icons.stop_rounded : Icons.play_arrow_rounded,
                      primary: !c.casting,
                      danger: c.casting,
                      onTap: !Cast.ready
                          ? null
                          : () async {
                              if (c.casting) {
                                await c.stopView();
                              } else {
                                _err(await c.startView());
                              }
                            },
                    ), !Cast.ready),
                  ),
                ),
                const SizedBox(width: 14),
                Expanded(
                  child: _CastCard(
                    icon: Icons.screenshot_monitor_rounded,
                    title: 'Screenshot',
                    desc: 'Grabs the current view and saves it to Pictures\\Lightcat.',
                    child: Btn(label: 'Take screenshot', icon: Icons.camera_alt_rounded, busy: c.shooting, onTap: _shot),
                  ),
                ),
                const SizedBox(width: 14),
                Expanded(
                  child: _CastCard(
                    icon: Icons.videocam_rounded,
                    title: c.recording ? 'Recording' : 'Record a clip',
                    desc: 'Saves a video of the headset view, no window needed.',
                    live: c.recording,
                    liveColor: Pal.bad,
                    trailing: c.recording && c.recSince != null ? _RecClock(since: c.recSince!) : null,
                    child: greyed(Btn(
                      label: c.recording ? 'Stop recording' : 'Start recording',
                      icon: c.recording ? Icons.stop_rounded : Icons.fiber_manual_record_rounded,
                      danger: c.recording,
                      onTap: !Cast.ready ? null : _rec,
                    ), !Cast.ready),
                  ),
                ),
              ]),
            ),
            const SizedBox(height: 18),
            Group(title: 'Cast and record options', icon: Icons.tune_rounded, delay: 60, children: [
              opt('eye', 'View', 'One eye looks like a normal screen. Both eyes shows the raw side by side image.',
                  ['Both eyes', 'Left eye', 'Right eye'], 1),
              opt('size', 'Resolution', 'Higher is sharper but needs a faster cable or Wi-Fi.', ['720p', '1080p', '1440p'], 1),
              opt('fps', 'Frame rate', 'Higher is smoother and uses more of the headset.', ['30', '60', '72', '90'], 1),
              opt('rate', 'Bitrate', 'Raise it if fast motion looks blocky.', ['8 Mbps', '16 Mbps', '24 Mbps'], 1),
              flag('sound', 'Headset sound', 'Plays and records the game audio on this PC.'),
              flag('control', 'Control with mouse and keyboard', 'Clicks and typing in the cast window go to the headset.'),
            ]),
            if (c.files.isNotEmpty)
              FadeIn(
                delay: 120,
                child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Text('Recent captures', style: t(17, w: FontWeight.w700, display: true)),
                  const SizedBox(height: 14),
                  LayoutBuilder(builder: (_, cons) {
                    final w = (cons.maxWidth - 3 * 14) / 4;
                    return Wrap(spacing: 14, runSpacing: 14, children: [
                      for (final f in c.files.take(8)) SizedBox(width: w, child: _CaptureTile(f: f)),
                    ]);
                  }),
                ]),
              ),
          ]);
        },
      ),
    );
  }
}

