      {required this.icon,
      required this.title,
      required this.desc,
      required this.child,
      this.trailing,
      this.live = false,
      this.liveColor});

  @override
  Widget build(BuildContext context) => Panel(
        pad: const EdgeInsets.all(22),
        child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Row(children: [
            Container(
              width: 38,
              height: 38,
              decoration: BoxDecoration(color: Pal.a.withValues(alpha: .12), borderRadius: BorderRadius.circular(11)),
              child: Icon(icon, size: 19, color: Pal.a),
            ),
            const Spacer(),
