}

class _RecClock extends StatefulWidget {
  final DateTime since;
  const _RecClock({required this.since});
  @override
  State<_RecClock> createState() => _RecClockState();
}

class _RecClockState extends State<_RecClock> {
  late final Timer _t;

  @override
  void initState() {
    super.initState();
    _t = Timer.periodic(const Duration(seconds: 1), (_) => setState(() {}));
  }

  @override
  void dispose() {
    _t.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final d = DateTime.now().difference(widget.since);
    final s = '${d.inMinutes.toString().padLeft(2, '0')}:${(d.inSeconds % 60).toString().padLeft(2, '0')}';
    return Text(s, style: t(13, w: FontWeight.w700, c: Pal.bad, f: 'Consolas'));
  }
}

class _CaptureTile extends StatelessWidget {
  final File f;
  const _CaptureTile({required this.f});

  bool get video => f.path.toLowerCase().endsWith('.mkv') || f.path.toLowerCase().endsWith('.mp4');

  @override
  Widget build(BuildContext context) => Tooltip(
        message: baseName(f.path),
        child: Hover(
          onTap: () => openUrl(f.path),
          builder: (h) => ClipRRect(
            borderRadius: BorderRadius.circular(14),
            child: AspectRatio(
              aspectRatio: 16 / 9,
              child: Stack(fit: StackFit.expand, children: [
                video
                    ? Container(
                        color: Pal.card,
                        child: const Icon(Icons.movie_rounded, size: 30, color: Pal.dim),
                      )
                    : Image.file(f, fit: BoxFit.cover, cacheWidth: 400, gaplessPlayback: true),
                AnimatedContainer(duration: ms(200), color: Colors.black.withValues(alpha: h ? .35 : 0)),
                Positioned(
                  right: 8,
                  bottom: 8,
                  child: AnimatedOpacity(
                    duration: ms(200),
                    opacity: h ? 1 : 0,
                    child: IconBtn(
                        icon: Icons.folder_open_rounded,
                        tip: 'Show in folder',
                        onTap: () => Process.run('explorer', ['/select,', f.path])),
                  ),
                ),
              ]),
            ),
          ),
        ),
      );
}

class ConsolePage extends StatefulWidget {
  const ConsolePage({super.key});
  @override
  State<ConsolePage> createState() => _ConsolePageState();
}

class _ConsolePageState extends State<ConsolePage> {
  static final log = <(String, String)>[];
  final ctl = TextEditingController();
  bool busy = false;

  static const quick = <(String, String)>[
    ('Devices', 'adb devices -l'),
    ('Installed apps', 'pm list packages -3'),
    ('Battery', 'dumpsys battery'),
    ('Model', 'getprop ro.product.model'),
    ('Storage', 'df -h /sdcard'),
  ];

  @override
  void dispose() {
    ctl.dispose();
    super.dispose();
  }

  Future<void> _run([String? cmd]) async {
    final c = (cmd ?? ctl.text).trim();
    if (c.isEmpty || busy) return;
    setState(() => busy = true);
    final out = c.startsWith('adb ')
        ? await Adb.run(c.substring(4).split(RegExp(r'\s+')), timeout: const Duration(minutes: 2))
        : await Adb.shell(c);
    log.insert(0, (c, out.isEmpty ? '(no output)' : out));
    if (log.length > 40) log.removeLast();
    ctl.clear();
    if (mounted) setState(() => busy = false);
  }

  @override
  Widget build(BuildContext context) {
    return PageFrame(
      title: 'Console',
      subtitle: 'Run shell commands on the headset. Start with “adb” to run an ADB command instead.',
      slivers: [
        SliverToBoxAdapter(
          child: Padding(
            padding: const EdgeInsets.only(bottom: 18),
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: [
          Expanded(child: Field(c: ctl, hint: 'getprop ro.build.version.release', mono: true, onSubmit: (_) => _run())),
          const SizedBox(width: 10),
          Btn(label: 'Run', icon: Icons.play_arrow_rounded, primary: true, busy: busy, onTap: _run),
        ]),
        const SizedBox(height: 12),
        Wrap(spacing: 8, runSpacing: 8, children: [
          for (final q in quick) Chip2(label: q.$1, selected: false, onTap: () => _run(q.$2)),
        ]),
            ]),
          ),
        ),
        if (log.isEmpty)
          SliverToBoxAdapter(
            child: Padding(
              padding: const EdgeInsets.symmetric(vertical: 50),
              child: Center(child: Text('Output from your commands shows up here.', style: t(14, c: Pal.sub))),
            ),
          )
        else
          SliverList(
            delegate: SliverChildBuilderDelegate(
              (_, i) => TweenAnimationBuilder<double>(
                      key: ValueKey('${log.length - i}${log[i].$1}'),
                      tween: Tween(begin: 0, end: 1),
                      duration: ms(360),
                      curve: Curves.easeOutCubic,
                      builder: (_, v, child) => Opacity(
                          opacity: v, child: Transform.translate(offset: Offset(0, (1 - v) * 10), child: child)),
                      child: Padding(
                        padding: const EdgeInsets.only(bottom: 12),
                        child: Panel(
                          pad: const EdgeInsets.all(16),
                          r: 14,
                          color: const Color(0xFF0B0D14),
                          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                            Text('❯ ${log[i].$1}', style: t(13, w: FontWeight.w600, c: Pal.a, f: 'Consolas')),
                            const SizedBox(height: 10),
                            SelectableText(log[i].$2, style: t(12.5, c: Pal.text, h: 1.5, f: 'Consolas')),
                          ]),
                        ),
                      ),
                    ),
              childCount: log.length,
            ),
          ),
      ],
    );
  }
}

class SettingsPage extends StatefulWidget {
  const SettingsPage({super.key});
  @override
  State<SettingsPage> createState() => _SettingsPageState();
}

class _SettingsPageState extends State<SettingsPage> {
  final ipCtl = TextEditingController();
  final nameCtl = TextEditingController(text: '${Prefs.data['name'] ?? ''}');
  bool wifiBusy = false, restartBusy = false;
  Timer? _clock;

  @override
  void initState() {
    super.initState();
    _clock = Timer.periodic(const Duration(minutes: 1), (_) {
      if (mounted && _nameWait > Duration.zero) setState(() {});
    });
  }

  @override
  void dispose() {
    _clock?.cancel();
    ipCtl.dispose();
    nameCtl.dispose();
    super.dispose();
  }

  Duration get _nameWait {
    final at = Prefs.data['nameChangedAt'];
    if (at is! int) return Duration.zero;
    final left = DateTime.fromMillisecondsSinceEpoch(at).add(const Duration(hours: 8)).difference(DateTime.now());
    return left.isNegative ? Duration.zero : left;
  }

  String _left(Duration d) {
    final mins = d.inMinutes + 1;
    return mins >= 60 ? '${mins ~/ 60} h ${mins % 60} min' : '$mins min';
  }

  Future<void> _saveName() async {
    final typed = nameCtl.text.trim();
    if (typed.isEmpty || typed == '${Prefs.data['name'] ?? ''}') return;
    final name = typed.length > 24 ? typed.substring(0, 24) : typed;
    if (_nameWait > Duration.zero) {
      toast(context, 'You can change your name again in ${_left(_nameWait)}.',
          icon: Icons.schedule_rounded, color: Pal.warn);
      return;
    }
    final ok = await confirm(context, 'Change your name to $name?', 'You won’t be able to change it again for 8 hours.',
        action: 'Change name');
    if (!ok || !mounted) return;
    await Prefs.set('name', name);
    await Prefs.set('nameChangedAt', DateTime.now().millisecondsSinceEpoch);
    nameCtl.text = name;
    setState(() {});
    toast(context, 'Your name is now $name');
  }

  Future<void> _wifi() async {
    if (Device.i.link != Link.connected) {
      toast(context, 'Connect your headset with USB first.', icon: Icons.usb_rounded, color: Pal.warn);
      return;
    }
    setState(() => wifiBusy = true);
    final ipOut = await Adb.shell('ip -f inet addr show wlan0');
    final m = RegExp(r'inet (\d+\.\d+\.\d+\.\d+)').firstMatch(ipOut);
    if (m == null) {
      if (mounted) {
        setState(() => wifiBusy = false);
        toast(context, 'The headset isn’t on Wi-Fi. Connect it to the same network as this PC.',
            icon: Icons.wifi_off_rounded, color: Pal.warn);
      }
      return;
    }
    final ip = m.group(1)!;
    await Adb.run(['tcpip', '5555']);
    await Future.delayed(const Duration(seconds: 2));
    final out = await Adb.exec(['connect', '$ip:5555']);
    if (!mounted) return;
    setState(() => wifiBusy = false);
    final ok = out.contains('connected');
    toast(context, ok ? 'Wireless ready at $ip. You can unplug the cable now.' : out,
        icon: ok ? Icons.wifi_rounded : Icons.error_rounded, color: ok ? null : Pal.bad);
  }

  Future<void> _connectIp() async {
    final ip = ipCtl.text.trim();
    if (ip.isEmpty) return;
    final out = await Adb.exec(['connect', ip.contains(':') ? ip : '$ip:5555']);
    if (!mounted) return;
    final ok = out.contains('connected');
    toast(context, ok ? 'Connected to $ip' : out,
        icon: ok ? Icons.wifi_rounded : Icons.error_rounded, color: ok ? null : Pal.bad);
  }

  Future<void> _restartAdb() async {
    setState(() => restartBusy = true);
    await Adb.exec(['kill-server']);
    await Adb.exec(['start-server']);
    if (!mounted) return;
    setState(() => restartBusy = false);
    toast(context, 'ADB restarted');
  }

  @override
  Widget build(BuildContext context) {
    return PageFrame(
      title: 'Settings',
      subtitle: 'Make Lightcat yours.',
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Group(title: 'Profile', icon: Icons.person_rounded, delay: 0, children: [
          SRow(
            title: 'Your name',
            desc: _nameWait > Duration.zero
                ? 'Lightcat calls you ${Prefs.data['name']}. You can change it again in ${_left(_nameWait)}.'
                : 'Lightcat calls you ${Prefs.data['name']}. Typed it wrong? You can change it once every 8 hours.',
            trailing: Row(mainAxisSize: MainAxisSize.min, children: [
              Field(c: nameCtl, width: 200, hint: 'Your name', icon: Icons.person_rounded, onSubmit: (_) => _saveName()),
              const SizedBox(width: 8),
              Btn(
                label: _nameWait > Duration.zero ? 'Locked' : 'Save',
                icon: _nameWait > Duration.zero ? Icons.lock_rounded : Icons.check_rounded,
                onTap: _saveName,
              ),
            ]),
          ),
        ]),
        Group(title: 'Appearance', icon: Icons.palette_rounded, delay: 0, children: [
          SRow(
            title: 'Accent',
            desc: 'Colors the highlights, buttons and battery ring.',
            trailing: Row(mainAxisSize: MainAxisSize.min, children: [
              for (var i = 0; i < Pal.accents.length; i++)
                Padding(
                  padding: const EdgeInsets.only(left: 10),
                  child: Tooltip(
                    message: Pal.accentNames[i],
                    child: Hover(
                      onTap: () {
                        Pal.accent.value = i;
                        Prefs.set('accent', i);
                      },
                      builder: (h) => AnimatedScale(
                        scale: h ? 1.14 : 1,
                        duration: ms(240),
                        curve: Curves.easeOutBack,
                        child: AnimatedContainer(
                          duration: ms(280),
                          width: 34,
                          height: 34,
                          padding: const EdgeInsets.all(3),
                          decoration: BoxDecoration(
                            shape: BoxShape.circle,
                            border: Border.all(
                                color: Pal.accent.value == i ? Colors.white : Colors.transparent, width: 2),
                          ),
                          child: Container(
                            decoration: BoxDecoration(
                              shape: BoxShape.circle,
                              gradient: LinearGradient(
                                  colors: Pal.accents[i], begin: Alignment.topLeft, end: Alignment.bottomRight),
                            ),
                          ),
                        ),
                      ),
                    ),
                  ),
                ),
            ]),
          ),
          SRow(
            title: 'Reduce motion',
            desc: 'Turns off animations for an even lighter feel.',
            trailing: Toggle(
              v: Pal.reduceMotion.value,
              on: (v) {
                Pal.reduceMotion.value = v;
                Prefs.set('reduceMotion', v);
              },
            ),
          ),
        ]),
        Group(title: 'Connection', icon: Icons.wifi_rounded, delay: 70, children: [
          SRow(
            title: 'Go wireless',
            desc: 'Switch the headset to Wi-Fi so you can unplug the cable. Both need to be on the same network.',
            trailing: Btn(label: 'Enable wireless', icon: Icons.wifi_rounded, busy: wifiBusy, onTap: _wifi),
          ),
          SRow(
            title: 'Connect by IP',
            desc: 'Reconnect to a headset that already has wireless enabled.',
            trailing: Row(mainAxisSize: MainAxisSize.min, children: [
              Field(c: ipCtl, width: 200, hint: '192.168.1.20', onSubmit: (_) => _connectIp()),
              const SizedBox(width: 8),
              Btn(label: 'Connect', onTap: _connectIp),
            ]),
          ),
          SRow(
            title: 'Restart ADB',
            desc: 'Fixes most “device not found” problems.',
            trailing: Btn(label: 'Restart ADB', icon: Icons.refresh_rounded, busy: restartBusy, onTap: _restartAdb),
          ),
        ]),
        Group(title: 'Store', icon: Icons.storefront_rounded, delay: 140, children: [
          SRow(
            title: 'Ask before opening store pages',
            desc: 'Show a heads-up before Lightcat opens Steam or Meta in your browser.',
            trailing: Toggle(
              v: Prefs.data['skipLeave'] != true,
              on: (v) async {
                await Prefs.set('skipLeave', !v);
                setState(() {});
              },
            ),
          ),
        ]),
        Group(title: 'Background and alerts', icon: Icons.notifications_active_rounded, delay: 210, children: [
          SRow(
            title: 'Keep running in the tray',
            desc: 'Closing the window hides Lightcat next to the clock. Right-click the cat to see your headset’s battery or quit.',
            trailing: Toggle(
              v: Prefs.data['tray'] != false,
              on: (v) async {
                await Prefs.set('tray', v);
                setState(() {});
              },
            ),
          ),
          SRow(
            title: 'Tell me when my headset is charged',
            desc: 'One Windows notification when the battery reaches 95% while charging.',
            trailing: Toggle(
              v: Prefs.data['notifyFull'] != false,
              on: (v) async {
                await Prefs.set('notifyFull', v);
                setState(() {});
              },
            ),
          ),
          SRow(
            title: 'Show notifications inside Lightcat',
            desc: 'Banners that slide in from the top for 10 seconds: full battery, finished installs, low storage.',
            trailing: Toggle(
              v: Prefs.data['inAppNotes'] != false,
              on: (v) async {
                await Prefs.set('inAppNotes', v);
                setState(() {});
              },
            ),
          ),
          SRow(
            title: 'Warn me about controller batteries',
            desc: 'One Windows notification when a controller drops to 20%.',
            trailing: Toggle(
              v: Prefs.data['notifyPads'] != false,
              on: (v) async {
                await Prefs.set('notifyPads', v);
                setState(() {});
              },
            ),
          ),
          SRow(
            title: 'Warn me when the battery is low',
            desc: 'One Windows notification when the battery drops to 15%.',
            trailing: Toggle(
              v: Prefs.data['notifyLow'] != false,
              on: (v) async {
                await Prefs.set('notifyLow', v);
                setState(() {});
              },
            ),
          ),
        ]),
        Group(title: 'About', icon: Icons.info_rounded, delay: 280, children: [
          SRow(
            title: 'Lightcat Sideloader $kVersion',
            desc: 'Lightweight by design. No accounts, no tracking, no restrictions.\nIndependent app, not affiliated with Meta.\nADB: ${Adb.path}',
            top: true,
            trailing: const Padding(padding: EdgeInsets.only(top: 2), child: Brand()),
          ),
          SRow(
            title: 'Updates',
            desc: 'Lightcat looks for a new version when it starts.',
            trailing: Btn(
              label: 'Check now',
              icon: Icons.refresh_rounded,
              onTap: () async {
                final found = await Updater.i.check(force: true);
                if (context.mounted) {
                  toast(context, found ? 'A new version is ready' : 'You’re on the latest version',
                      icon: found ? Icons.system_update_alt_rounded : Icons.check_circle_rounded);
                }
              },
            ),
          ),
        ]),
      ]),
    );
  }
}
